/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20160119-6","meetingId":"h28-cm01","date":"2016年1月19日","dateIso":"2016-01-19","committee":"区民委員会","time":"午後 １時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"マイナンバー「個人番号カード」の交付等","agenda":"マイナンバー「個人番号カード」の交付等","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"１０日ぐらいたって、そういうケースは同様の扱いになるのかどうかの確認と、どういう対応をされているのかなというのが１つ。どういう対応をされているかというのを教えていただきたいのが１つと、これは本人確認はどういうふうにするのか、教えてほしいと求めました。","respondent":"井浦戸籍住民課長","answer":"１点目のさまざまな事情で通知カードがお手元に届かない方への対応です。こちらについては既に住基カードで先行してコンビニ交付を行っている自治体も少数ありますが、同じ仕組みです。","id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"そうすると、コンビニのほうなのですけれども、自分で暗証番号を決めて、それで当然登録をしておくわけですよね。その辺を一つ伺いたいのと、そういう類いの相談はどのぐらいあるのかを一つ伺いたいのと、そのあたりを確認しておきたいと思います。","respondent":"井浦戸籍住民課長","answer":"１点目のコンビニ交付の暗証番号の設定ですが、四年実施されておりまして、個人情報の確保はされてあります。その中でかなりの数を占めていると認識しています。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"基本４情報以外のさまざまな情報がひもづけという形で入ってくると言われているし、私はやはりできるだけ早くやめるべきだと思っているのですけれども、くれぐれも十分な上に十分に気を付けていただきたいということをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"そうすると、今回、新たに始めるということで、そこに対してどのくらいの税金がとか、そういう話を聞いても大丈夫ですか。情報保護について、本当にどうなのかというところを説明を求めました。","respondent":"井浦戸籍住民課長","answer":"初期経費等々の効果的な実施ということで、住基カードの活用ではなく、マイナンバーを待つという方針をとっていたものです。具体的には、技術的、物理的、制度的な措置が講じられているものです。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"今、住基カードで行っているほかの自治体では、今まで情報が漏れてしまったとか、そういったことはなかったのか尋ねました。","respondent":"井浦戸籍住民課長","answer":"これまではございません。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"確認","question":"ほかの自治体でも既にやっているところとか、ソフト面で品川区がそれに参加するに当たって決められたものが何かあるという印象でいいのでしょうか。前に伺ったかもしれないですが、再送付する場合の考え方というのですか、その辺を聞かせてください。","respondent":"井浦戸籍住民課長","answer":"住所が古い住所ですので、改めて現在の住所地にこの７,０００件弱の方は送られますので、しばらくお待ちいただければ通知カードがお手元に届くです。それから、３点目……。","id":"exchange-006"},{"speaker":"松永委員","kind":"確認","question":"私からは確認で質問します。区民の方に行き渡っているとは思うのですけれども、品川区ではその確認をどのように行っているのか、お伺いいたします。","respondent":"井浦戸籍住民課長","answer":"2)の区保管で２万４,０００件余りの方についてはお手元に届いてございませんので、平均２００件前後ですが、交付を行ってあります。再送付の方は自動的に送付されるという３区分です。","id":"exchange-007"},{"speaker":"松永委員","kind":"質問","question":"聞いた話なのですが、実際どうかはわかりませんけれども、自宅にまず届いていないということと、郵便局の紙も届いていないという方がいるとお伺いしたものですから、では、その方は区に行けばあるという確証を持っていいのかなと思うのですが、その辺はいかがか尋ねました。","respondent":"井浦戸籍住民課長","answer":"郵便局の不在連絡票を見失ってしまう、あるいは紛失されている方もいらっしゃいまして、コールセンターに相談を寄せられております。私ども、調べまして、区で保管しているかどうか、ご案内申し上げまして、あるいは非常にレアなケースについては個別に対応しています。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"もう１回、コンビニの手数料のところをもっとわかりやすく教えていただきたいのですけれども。","respondent":"井浦戸籍住民課長","answer":"窓口は３００円ですが、２００円を予定してございまして、ぜひ奮って利用していただきたいということで期待しています。こちらについての運用については、負担金ということで人口割で決められておりまして、品川区の人口では年間の負担金が５００万円です。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"ごめんなさい、ちょっといいですか。〔「では違う質問に先に行きましょう」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"渡辺委員","kind":"確認","question":"いざやってみたらこういうことがあったとかいうのがあるのかどうか、あるいは大体想定どおり来たので混乱なく行けているのかの確認が１つ。２時間も待つとやはりいらいらしてしまいますよね、配慮ができることはつけ加えてでもやるべきかなと思ったので、現状のお考えを説明を求めました。","respondent":"井浦戸籍住民課長","answer":"その対応としましては、事務補助につきましては委託で用意してございましたので、委託の人員を会場に振り向けるという形で増員を図ってあります。","id":"exchange-011"},{"speaker":"渡辺委員","kind":"意見","question":"その辺の変動はあるのか。いろいろな場合の対応は必要だと思うのですが、それだけ、最後に説明を求めました。","respondent":"井浦戸籍住民課長","answer":"事務の補助的なものについて、委託で対応できるところについてはできるだけ対応するという方針で臨んでございまして、国の事務のおくれ、ずれに対応するために、委託の人員増という部分についても、変更契約も含めまして予算上の措置を講じながら対応しています。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"ちょっと混乱したので、わからないまま聞きます。区にとって、このコンビニ交付はいいことなのか尋ねました。","respondent":"井浦戸籍住民課長","answer":"コンビニ交付のメリットにつきましては、対応時間の拡大ということがあります。拠点の拡大、対応時間の拡大、コストの削減というところでメリットを組み込んでいるところです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"やはり情報が本当に保護され、今の時代、本当にそれで安全なのかという、その安全の確証が全くもって不安なのです、コンビニとかでされてしまうと。品川区でコンビニ交付が始まって、もしも情報が漏れてしまったという場合はどうなるのか尋ねました。","respondent":"井浦戸籍住民課長","answer":"コンビニ交付につきましては、個々の店員が対応するものではなくて、コンビニに備え付けの機械で行います。専用のネットワーク回線を使いまして、個人情報の漏洩防止についてはしっかりと確保されているというものです。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問","question":"私もよくやるのですけれども、ＡＴＭとかの機械だとよくわからなくて、店員にこれはどうやってやるのですかと私はよく聞くのです。〔「それは個人の責任ではないですか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"そうなるのですか。〔「それは個人の責任でしょう」と呼ぶ者あり〕。","respondent":"井浦戸籍住民課長","answer":"キオスク端末の画面表示にあります多言語対応でいたします。音声案内により個人番号カード取り忘れ防止対策等も講じられているものですので、安全が確保された形で実施できると考えています。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問","question":"いつでも行ける身近なところにあって、交付ができるというのはあるかもしれないのですけれども、情報が漏れてしまうというリスクが高くないですか。全て機械に任せてしまうとかというのは、どうなのでしょうか、リスクが高いと思うのですけれども。","respondent":"井浦戸籍住民課長","answer":"国の機関が一元的に情報安全につきましては責任を持って専用の回線、専用のシステムで管理していますので、外部から情報漏洩のアクセスができるような仕組みは、物理的にも技術的にも存在していないと認識しています。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問","question":"今の答弁の感じだと、何かが起きても国のシステムなので区には問題ないということか尋ねました。","respondent":"井浦戸籍住民課長","answer":"マイナンバー法の施行に伴いまして、国の現在でき得る非常に高いＩＴのセキュリティレベルで構築されておりますので、そのようなことはないと考えています。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"すみません。では、何かあった場合を考えていない、何かがあった場合には国の問題ということでよろしいか尋ねました。","respondent":"堀越地域振興部長","answer":"そういった可能性はないと認識しておりますが、主体の責任もありますし、区として区民の皆様に対しては所要の対応をとると。それから物理的な対応、委員がご心配になるような事由については、発生する可能性は極めて低いと考えているところです。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問","question":"区からコンビニの店員に、セキュリティの問題だったり交付の方法だったりとか、そういう指導はないのか尋ねました。","respondent":"堀越地域振興部長","answer":"それからあわせまして、用紙についても改ざん防止の所要の措置もなされますので、そういったこともあわせて対応していくです。それは当然行うということでご理解いただければと思います。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"確認","question":"窓口も２００円にすると言っていたかどうか、そこの確認と、実質８７円しか区に歳入が入ってこない……。〔「７７円」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問","question":"７７円ね。区民の利便性とか考えて、区としてはこれでいいのではないかということだと思うのですけれども、予想としてはどれくらい減ってしまうのか尋ねました。","respondent":"井浦戸籍住民課長","answer":"やはり全発行数の１０％あるいは２０％という形でコンビニ交付が普及してくるにつれて、窓口の混雑緩和という効果も考えてあります。それから、すみません、１点目の窓口……。","id":"exchange-022"},{"speaker":"渡部副委員長","kind":"質問","question":"４月にでも、９月から２００円になりますよと言っていただいて、４月に申請したら９月に絶対間に合ってカードができているのかということなのです。それが間に合う担保がないのだったら、もっと早く告知しなければだめではないですかということを言いたいのです。","respondent":"井浦戸籍住民課長","answer":"本日の資料の２ページ目に書いてありますが、条例等の整備ということで、コンビニ交付には条例の制度が必要でございまして、平成２８年第１回定例会に上程予定ですので、早目に告知をしながら、このような利便性ということで皆様にお知らせしていきたいと考えています。","id":"exchange-023"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"要望します。２００円なのだよというときに、そういうようなことがないように何とか努力をしてくださいというのが要望で、終わります。","respondent":"井浦戸籍住民課長","answer":"補足ですが、１１月に申請されている方のものが１月に国から納品されているですので、２月に申請された方は４月には区に届くのではないかということは間違いないかと思います。","id":"exchange-024"},{"speaker":"渡部副委員長","kind":"質問","question":"自分で抜くわけですから、２００円のほうをとるわけですよ、みんな。それはまた後の問題なのですけれども、流れ的にはそういうふうに思うのですが、いかがか尋ねました。","respondent":"井浦戸籍住民課長","answer":"７０％の方が住民票あるいは印鑑証明が必要で見えている方ですので、お近くのコンビニで交付を受けることができるという仕組みを推進してまいりますと、窓口の混雑緩和あるいはマンパワーという部分についても効果があらわれてくると考えています。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"今年９月からということですから、その辺を教えていただきたいのと、予算をつくる上で必要だと。その辺を教えていただきたいのと、コンビニ交付がどのくらいの割合になるのか、窓口に来る方たちが何％ぐらいなのかというのを説明を求めました。","respondent":"井浦戸籍住民課長","answer":"その中で、２年前には平成２８年のマイナンバーに合わせてコンビニ交付を行いますということではプレスをしています。コンビニ交付の利用ですが、上限として全窓口発行数の１０％ほどを初年度で利用していただければと想定しています。","id":"exchange-026"},{"speaker":"南委員","kind":"意見","question":"その後はどういうふうに推移するかわからないけれども、その１０％程度が１００円安い２００円の交付手数料になってくるということですね。そんなところで留めておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"}]},{"id":"topic-02","title":"「品川区消費生活・社会貢献活動展」の開催","agenda":"「品川区消費生活・社会貢献活動展」の開催","exchanges":[{"speaker":"南委員","kind":"質問","question":"私の印象なので正確かどうかは別ですけれども、どういう形でお考えなり、声をかけてこられたのかなと。その辺りを伺いたいと思います。","respondent":"河内協働・国際担当課長","answer":"まず一番の目的といたしましては、各団体の化学反応といいますか、お互いをまずは知るというところが大事になってまいります。経済など、いろいろな分野を合わせて、そういったところで知り合うということを目的としてやっているという実情です。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"多数来場者があるわけですから、大イベントであるわけですから、その辺についてはいかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"地区委員のご協力を得ながら、大きなイベントにつきましては、できるだけオリンピック・パラリンピックの気運醸成の事業を行っているところです。今後もそういったイベントにおいて、こちらも見極めて、できるだけ出展をしていくような方向で考えているところです。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"やっていますと伺ったので、今日、担当が……。〔「協働・国際担当」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"そうそう、国際のほうの課長ですから、どういうふうにやっていこうと思っているのかについて、お伺いします。それと、あえて伺えば、バッジの色は関係ないのですということも答弁いただいて。","respondent":"河内協働・国際担当課長、小川オリンピック・パラリンピック準備課長","answer":"その中で、友好都市、姉妹都市、また区内には１１の大使館、４の領事館があります。連携のもとで、次年度の事業につきましてもオリンピック・パラリンピック準備課と事業連携を図っていくとともに、実行に移しつつあるところです。現在、こちらの桜のバッジが暫定的なエンブレムということで、こちらについては全職員並びに管理職等にもきちんと配布をして対応しています。","id":"exchange-031"}]},{"id":"topic-03","title":"第１２回 品川区新製品・新技術クラスターフェアの開催","agenda":"第１２回 品川区新製品・新技術クラスターフェアの開催","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"これだけ２０社も出ているのであれこれあると思うのですけれども、どういうふうに見ていらっしゃるのか、その辺をまず聞きたいなと思いました。さっき言ったように、そんな差し障りのあるようなところまで求めるつもりはないのですけれども、教えてほしいと求めました。","respondent":"立木産業活性化担当課長","answer":"ライフステージに合わせたような企業支援も着目していきまして、マッチングですね、すぐれた技術を売り込んでいきたいという部分もあります。やはり産業支援の交流施設ということでＳＨＩＰを開設させていただきましたので、来年度以後の施策に反映させていきたいと考えています。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"何で２月４日にやると決めたのかということと、それと、何で１日だけの開催なのですかという２点。","respondent":"立木産業活性化担当課長","answer":"区の行事予定とか議会の予定等をいろいろ勘案いたしまして、３月、４月は避けたいということがあります。は１日の中に凝縮した形で集まっていただく、お客様にも見ていただくということで１日という設定にさせていただいているところです。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"なぜ１日かと聞いたのは、たしか大田区が同じ２月の３、４、５日か４、５、６日、３日間、蒲田のＰｉＯでやるのです。大田区はたしか３日かけて同じ時期にやるということにおいて、だからどうだという質問ではないのですが、思うか。","respondent":"山崎商業・ものづくり課長","answer":"そうした日時、これからいろいろな意味で最適なものを検討してまいりたいなということと、今年度の支援事業者の成果を改めてここで再確認をする。","id":"exchange-034"},{"speaker":"たけうち委員","kind":"質問","question":"たしかやはり大田区だとか墨田区とか、新聞の広告なのか、何かやはり新聞等を通じてこういうのをやりますよとかとよく目にすることがあるのです。幅広く目にとまって、せっかくそこに来て、そういう部分での広報はどれくらい力を入れていくべきなのかなということに見解があれば説明を求めました。","respondent":"立木産業活性化担当課長","answer":"いろいろな方に来ていただくということに関しましては、やはりメディアへの露出もいろいろやっていきたいところです。いろいろ区のかかわりのあるメディアに、これからも引き続き周知に関してはいろいろＰＲを打っていきたいと考えております。","id":"exchange-035"},{"speaker":"たけうち委員","kind":"質問・要望","question":"品川区でこんなことをやるのだと幅広く、なかなか広報とか品川区のホームページだけだと限りがあるのかなと。私たちも委員会で初めて知るみたいなイメージがどうしてもあるので、やっていただいてもいいかなと思いますので、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"渡部副委員長","kind":"質問","question":"日精ビルのときに何回か行って、今度、場所的には日精ホールより少し広くなるのですか。どういう感じの入場をやっていたか、説明を求めました。","respondent":"立木産業活性化担当課長","answer":"入場に関しましては、特に名刺受けという形ではなく、各ブースでの名刺交換を行っていただくという形で行ってあります。","id":"exchange-037"},{"speaker":"渡部副委員長","kind":"確認","question":"その辺はいかがでしょうかというのと、あと１つ、ビジネスクラブで開催されます。確認をします。","respondent":"立木産業活性化担当課長","answer":"その後の連携といいますか、そういったものも研究しながら、いろいろ工夫をしてまいりたいと思います。今回の出展企業が品川ビジネスクラブに入っているかどうかなのですけれども、全てではございませんが、クラブ員として加入されている企業もあります。","id":"exchange-038"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"書いてもらうでは大変ですから、それをどう使うか、「何かの案内に使います」とかでいいと思うのですけれども。その辺をやってみてはというか、やってほしいなというのは、いかがでしょう。","respondent":"立木産業活性化担当課長","answer":"例えば特定されないような形で、こういう大きな案件があったとか、そういったものに関しましては積極的に出していきたいと思います。そういったものも何らかの形でＰＲしていきたいと思ってあります。","id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"さっき伺えばよかったのですけれども、５分ずつのプレゼンにしても１時間半ずつ聞くのもつらいところがあるかななんて思ったりしたときに、。","respondent":"立木産業活性化担当課長","answer":"レジュメのほうで５０音順に並べてしまっているのですけれども、そちらができ次第、またお持ちいたします。そういったものも当日ご用意する予定ですので、そちらをご参考に、ぜひ各ブースをご覧いただければと思います。","id":"exchange-040"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"これは果たしていいのか悪いのかというのが実際問題どうなのだろうというのがよくわからなくて、そこら辺の説明をしていただきたいのと、どう考えていけばいいのかなということを聞きます。","respondent":"久保田地域活動課長","answer":"私どもとしましては、この数字に対しては高く評価しているものです。二、こういったことは継続的に続けいていくことが必要と思っていますので、そういう意味で私どもは高く評価しているというものです。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"でも、平成２７年度の６０件だけではなくて、もうちょっと前の実績とかも書いていただけたらもっとわかりやすかったのかなと思ったりします。平成２７年度１２月時点で相談件数が２５件というのも、もうちょっと具体的に教えていただけたらありがたいなと思いました。","respondent":"久保田地域活動課長","answer":"宅建協会等と連携をして、そのときは正直言って数件程度ということで、モデル的に始めたものをだんだん本格実施してきて件数が伸びているですので。","id":"exchange-042"},{"speaker":"田中委員","kind":"確認","question":"確認です。今、相談件数が平成２６年４月から平成２７年１２月までで２５件ということで大丈夫か尋ねました。","respondent":"久保田地域活動課長","answer":"はい、そのように思っていただければ。","id":"exchange-043"},{"speaker":"松永委員","kind":"質問","question":"ガイドブックについて質問したいのですが、これは誰がこのような作成をされているのか、お聞きしたいと思います。こういうふうにやったほうがいいのではないかという案を出しながら作られたのか、それとも地域センターで作られたのか、伺いたいと思います。","respondent":"久保田地域活動課長","answer":"これについては、各地区の連合会で作成をお願いしているものです。内容等も各町会に戻していただいて、確認をして、こういうデザインで作られたものです。","id":"exchange-044"},{"speaker":"松永委員","kind":"質問","question":"一緒ですか。大井第三地区連合会と大井第二地区連合会の差について。","respondent":"久保田地域活動課長","answer":"薄い紙のところは、部数がちょうど今なかったので、すみません、コピーで代用させていただいていますので、各地区ともしっかりした紙で作っています。申し訳ございません。","id":"exchange-045"},{"speaker":"松永委員","kind":"意見","question":"このガイドブックについては、地域センターに置かれているのか、それとも町会にどさっと置かれているのか。地域センターだったら、大井第三地域センターに大体何部数置いているのか、わかればお願いしたいのですけれどもとの意見を述べました。","respondent":"久保田地域活動課長","answer":"大体つくる際には、地区の人口等もありますけれども、１万部程度ぐらいは作成させていただいて、それがなくなり次第、増刷をすると。内容の見直しとかを図りながらやっているです。","id":"exchange-046"},{"speaker":"たけうち委員","kind":"質問","question":"同じような質問になってしまうのですが、こういうのはやってくださいねというもとでやっているのかなというのが１つと、別のバージョンもあるのです。〔「時期が違う」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"たけうち委員","kind":"質問","question":"時期が古いのか。それはあるところとないところがあるので、そういう意味で独自性はもちろん持ちながら、一定程度の統一性はやっているという考えでいいのか尋ねました。","respondent":"久保田地域活動課長","answer":"委員ご指摘のとおりでございまして、これは区と連携して作っていますので、区から最低こういうものは載せてくださいという項目の指定をしています。","id":"exchange-048"},{"speaker":"渡辺委員","kind":"質問","question":"現状の分析をどう捉えるかというところから始まって、町会の役員とかの負担とかではなく、頑張りがいがあるかなと。これは地域にやれというのは無理ですから、行政サービスとしてあり得るのかなと思うのですが、現状での見解を伺えればと思います。","respondent":"久保田地域活動課長","answer":"町会活動の支援をするといっても、平成２８年４月以降、いろいろな支援策のメニューを考えてありますので。何分、相手のあることでもありますので、その辺は意見交換をさらに進めながら検討していきたいと思ってあります。","id":"exchange-049"},{"speaker":"渡辺委員","kind":"質問","question":"５０代以降、上というのですか、ワンルームが多いからねと。全体としてのリードは力を入れるべきだなという思いがあったので、すぐではなくですね、そこだけ伺って終わりにしたいと思います。","respondent":"久保田地域活動課長","answer":"委員からご指摘があるように、ある程度区がリードしていくといった側面も必要かと思います。そういった区としての考え方、目標みたいなものを今後検討させていただきまして、少しお時間をいただいて検討を進めていきたいと思います。","id":"exchange-050"},{"speaker":"たけうち委員","kind":"確認","question":"１００入っていたら１００と数えるかで大きく違ってしまうと思うのだけれども、それは統一されているのですねという確認と、それは……。〔「これはおかしい」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"たけうち委員","kind":"質問","question":"大崎第二と同じ、考えが変わったからこうなったのか、それとも何か要因があって、つかんでいらっしゃるか、教えてもらいたい。","respondent":"久保田地域活動課長","answer":"多分そういうことだろうという回答があったというものでございまして、センターを通じて聞いているのですが、なかなか過去のはわからないみたいで。品川第一は、こういうので来ていますので、もう１回よく確認をしてみます。","id":"exchange-052"},{"speaker":"たけうち委員","kind":"意見","question":"ただ、一定程度の統一性を今後はもうちょっとやっていかれる工夫をさらにしていただけないかなということで、とりあえずそこまでにしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/294647?Template=document&Id=2742#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":42094,"voices":169}},{"id":"h28-20160119-7","meetingId":"h28-cm01","date":"2016年1月19日","dateIso":"2016-01-19","committee":"厚生委員会","time":"午後 １時００分～午後 ４時００分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"御殿山小学校西側敷地の事業計画案","agenda":"御殿山小学校西側敷地の事業計画案","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"待望の２つ目ということで、私のところにも老健がもう１つ欲しい、順調に工事が進むことを希望いたします。１５日に地域の方への説明会があったということですので、図書館、お聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"ある程度はご認識をいただいていたかと思いますので、説明会としては非常に、紛糾することなく終わったといったところです。説明会あるいは住民の皆様の反応といったところでは、このように把握をしているといったところです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問","question":"お伺いしたいのですけれども、中には一戸建てなのか、そういうところもある。品川でもどちらかというと端のほうなので、どういったまちづくりを想定しておつくりになるのかということだけ説明を求めました。","respondent":"大串福祉計画課長","answer":"高齢者福祉を考える我々のセクションとしては非常に重要なポイントができたと考えていますし、図書館は文教機能をかなりつかさどる施設というふうに考えておりますので、この地域の発展を考えていければというふうに考えているところです。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"本当に２カ所目の老健ができるということはすばらしいことであるのですけれども、それをしっかり頭の中に入れてさまざまな事業の展開をしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"横山委員","kind":"質問","question":"１点だけお伺いをします。エボラですとか、１類感染症などの衛生面につきまして、施設としてはどのような対応を考えていらっしゃるのか尋ねました。","respondent":"大串福祉計画課長","answer":"こちらの施設、先ほど来申し上げていますように複合施設ということで、いろいろな利用者の方がいらっしゃるということが想定されております。１階部分が総合受付という形になっておりまして、あるいは発生する恐れのある場合の対応については、こういったところでの対応策。","id":"exchange-004"},{"speaker":"のだて委員","kind":"確認","question":"２カ所目の老健施設としてできるということで、大変喜ばしいと考えています。確認なのですけれども、そこの確認なのですが、５）番が病院の所有ということでよいのかということです。","respondent":"大串福祉計画課長","answer":"建物ですが、建物につきましては、図書館のみが品川区の所有というふうになります。それ以外につきましては運営事業者であるこちらの河野臨牀医学研究所の所有という形になります。","id":"exchange-005"},{"speaker":"のだて委員","kind":"確認","question":"ちょっと勘違いしていたようで。そうすると、これは今までもあったことなのかどうか、初めてのことなのかという確認です。","respondent":"大串福祉計画課長","answer":"区の土地を５０年間の定期借地ということで事業者にお貸しをして、なおかつ、建物等々は事業者のほうでつくる。区有施設ということで運営を行っていくですので、そういったスキームとしては今回こちらが初めてのケースになるです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"修繕とか、この区分所有でやっていることによるメリットとかデメリットがどういったものがあるのかということをお聞かせほしいと求めました。この施設の特色として、ここのもうちょっと具体的な説明をしていただけたらと思います。","respondent":"大串福祉計画課長","answer":"最終的には在宅での生活の継続、そういった意味では、こういった複合施設は非常にメリットとしては大きいと考えられます。地域に親しまれ、また地域と連携しながら施設の運営がしていける、こういったものも考えられるかというふうに考えております。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"１カ所で、この場所で病院と急性期の治療と、介護、在宅介護へもつなげて、ワンストップでできるということだと思いますので、それは大変すばらしいことだと思いますので、しっかりとやっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"やっと２カ所目ができるということで、本当によかったと思っています。どうなっていくのかというあたりを教えていただきたいのですけれども、土地貸付料を提案してくださいということで、そういうところも含めてとの意見を述べました。","respondent":"大串福祉計画課長","answer":"今般、基本設計がまとまったという段階で、こういった地域への説明等々を行ったという流れになっております。基本的にその辺はスタートの時点といいますか、なかなか一概に比較してどうこうといえるところではないのかなというふうに考えているところです。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"合意をして協定ですか、そうすると、さくら会と利用料が違うということもあり得るのかということをもうちょっとお聞かせほしいと求めました。そこら辺の４０m2という意味を教えていただきたいのと、そこのところについても実際どうなっているのかということを教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"今のところ、多床室、要するに、従来型のものと個室というところでは、９６床を従来型というふうに考えております。区とある程度の一定の協議はすることになろうかと思いますが、必ずしもそれで区と協定を結んでというところにはならないかと考えているところです。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今の時点で、老健施設のショートステイ２０床の老健８０床という１００ベッドのところでの、わかったら教えてほしいと求めました。１ベッド当たり４０５万円掛ける、この４０５万円掛ける１.５掛ける定員数というところでの補助金が出るということで考えていいのか尋ねました。","respondent":"大串福祉計画課長","answer":"都の補助金といたしましては、今申し上げた算式に基づきまして、６億９,０００万円ほどを見込んでいるです。訪問看護と訪問リハ、これが入った形になりますけれども、施工費としては、今のところ、１７億６,５００万円ほどを見込んでいるです。","id":"exchange-011"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"最後にご説明いただいた就労の総定員なのですけれども、昨年度、就労継続支援Ｂ型とＡ型が結構増えているのですけれども、これは新たな施設が建設されたのか、それとも定員を増やしたのか、もともとある施設にさらに拡大したのか、その確認です。","respondent":"中山障害者福祉課長","answer":"平成２６年度から平成２７年度にかけて伸びているところですけれども、特にＢ型については、定員がここで増えているところです。そちらのほうのカウントとして増やしているものです。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"相談できるところを増やしてほしいというか、自分に合った仕事を見つける支援を求めるということがアンケートで一番多いものになっているのですけれども、「自分に合った仕事」が見つかっているのかというところを説明を求めました。","respondent":"中山障害者福祉課長","answer":"できる能力と、長く続けられる仕事、その方が意欲を持って続けられる仕事を見つけていくことが長く継続につながるとも考えております。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"平成３０年から精神障害者の方の雇用義務化もされるということで、今これはなかなか障害者だけでなく、企業との関係性もあって、やはり自分に合った仕事を見つけることが難しいということでしたけれども、今、区が重点に置いているというか、課題と思っているところはどこか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"やはり障害のある方はいろいろな障害があるので、その方お一人おひとりに合ったマネジメントをしていくことがすごく難しいと思っています。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうですね。やはり障害者の方でも仕事をして社会で一緒に生活していけるような品川区にしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"確認なのですけれども、どういう形で場のあっ旋を進めていただいているのかということを確認をさせてほしいと求めました。これは基本、認定を受けてから利用するという流れでよろしいのか確認をさせてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"今どういった取り組みをしているか、あるいは困難ケースのケース・スタディーみたいなものを共通の場で認識を持つことで意見を出し合って、では。","id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"本当になかなか現状は難しいところもあると思うのですが、しっかりまた確保の拡大に向けて取り組みを進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問・要望","question":"週３勤務ですとか、システムですとか、詳細につきまして区のほうから企業に対してご案内されているのか教えていただけたらと思います。新規開拓をするような営業のようなことにつきましては、区として何か支援されていることがあるのか教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"品川区と企業と連携して行っている、企業の方にどのようなことを理解していただいたほうがいいかということの講演会を実施することになっています。","id":"exchange-018"},{"speaker":"横山委員","kind":"提案","question":"講演会の中でそういったマッチングですとか提案、こういったことがやっていただけないかみたいな提案制度みたいなものもご検討いただいたり、要望で終わらせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"定員を超えて利用者数がかなりオーバーしているというところが改善をしているのかというところを教えていただきたいのが１点と、ここの要望書では。雇用の促進に尽力していただきたい」というような、そういう要望もいただいているのですけれども、考えというあたりを教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"就労継続Ｂ型については、この間、区のほうも法人と相談しながら徐々に増やしてきてはおります。利用率で見ると、就労継続Ｂ型でいくと、１００％はまだ超えていないのが現状です。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"何％ぐらいずつ身体と知的の方の品川区役所としての法定雇用率が２.９４％まで行っているということなのですけれども、そこの中で雇用されているのかというところがわかったら教えていただきたいのと、具体的にどうなっていくのかというところも教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"今のところは法の制度はそうなっております。品川区の実際の内訳というようなお話かと思うのですけれども、身体障害者の方を中心に、精神障害の方も雇用しているというような状況になっています。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところでは、ぜひ知的障害の方の雇用の場も区としてもつくっていただきたいというのが団体の皆さんからも出されている要望だと思いますので。多分、品川の障害者の方に対してジョブコーチの方が何人くらい対応しているのかというところがわかったら教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"それから、就労の支援ということで、ジョブコーチを含めてやる方が３人。実際には区内の就労移行支援事業所だけではなく、都内のさまざまなところを活用していらっしゃるので、総人数はわかりかねているところです。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"ジョブコーチの方の役割はすごく大きいのではないかと思うのです。ジョブコーチの方が、そういう支援が本当にきちんとされているかどうかという、そこら辺のところの仕組みについてもお聞かせいただけたらと思いますとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"に就労移行支援事業所の報酬の中に、その後のフォローをどれぐらいできるかというところで加算の仕組みみたいなものもあります。必要に応じてハローワークとも連携しながら、一緒に話をし、その方の継続的な雇用が維持できるような形では進めているところです。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当に皆さん思っていることだと思うのですけれども、それが実際に続けられるためには、さまざまな支援が必要だと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問","question":"どういうふうに捉えたら、いろいろ伺うと、我々が聞いても。どういうところにポイントを絞っていけばいいのかということが私はよくわからないので、もしわかればレクチャーをしてほしいと感じる。","respondent":"中山障害者福祉課長","answer":"残りの方がどういった支援が必要なのか、そういったことは考えていかないと難しい時期には来ているのかなというふうには思っております。","id":"exchange-025"},{"speaker":"若林委員","kind":"確認","question":"確認ですけれども、いわゆるそういう作業、主な内容はそういうことでいいのかという。代表的なものを逆に挙げていただければ、その２点。","respondent":"中山障害者福祉課長","answer":"１点目の４番の表の見方で、一番上の就労支援センター『げんき品川』の４２２人ですが、下の数字との関連性がない数字になります。就労継続支援Ｂ型・Ａ型でどのような仕事をしているかというところですが、花布巾をつくったり、そういうような作業をしています。","id":"exchange-026"},{"speaker":"若林委員","kind":"質問・要望","question":"今の作業内容は、手元でやるとか、公園で清掃をするとかという。１つある、品川区としてどう考えているのか、１点お考えをお聞かせいただきたい。","respondent":"中山障害者福祉課長","answer":"レストランのところの事業所を就労継続Ｂ型の作業の人に活用してもらうということは１点想定しているので、そういった形で訓練をしたことが。新たな課題ということで、相手先もあることですので、検討課題とさせていただきたいと思います。","id":"exchange-027"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"多分、建設委員会でご報告があったのかもしれませんが、この３年ぐらい開設まで月見橋が仮移転の場所になってしまうという、もうちょっと詳しい理由と、仮移設が延びることによって、建物の影響とか、そういった施設として問題ないのかということの確認です。","respondent":"永尾高齢者福祉課長","answer":"時期が２年延長になっているですけれども、所管の課のほうにお尋ねしたところ、やはり世界初の工事というふうに聞いております。こちらのデイサービスについては、送迎で実施しておりますので、今までの移設をする前の方のご利用者も継続して利用しています。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先日、そういうところでの感染の人数も教えていただきたいのですけれども、そこら辺の指導のやり方がどうされたのかということをお聞きしたいのです。その人数をお聞きしたいのと、そこのところから二次、そこのところの対応についてお聞かせほしいと求めました。","respondent":"高山生活衛生課長、舟木品川区保健所保健予防課長","answer":"職員から１５名、調理従事者から３名ということで、積み上げますと５４名というような数字となってまいります。感染につきましては、予防課長のほうからご説明を申し上げます。食中毒ということで５４名で、二次感染も落ち着いてきているのかと思いまして、こちらでは引き続き経過観察をしている状況です。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"なぜそれがそういうふうな形で防ぐことができなかったのか、こういう対策をどうしていくのかというあたりも、お聞かせいただきたい。","respondent":"高山生活衛生課長","answer":"爆発的な数で患者が出ますので、そういう意味で長きにわたって１位といいますか、不名誉な記録ということにはなります。調理従事者の健康管理などが大変重要になってまいりますので、そういったものについては今後も繰り返し衛生指導の中で普及啓発を図ってまいります。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回は重症な方が出ていないということだったので幸いだったと思うのですけれども、子どもですとか、高齢者ですとかは、本当に下痢、嘔吐で脱水で重篤になる場合もありますので、教訓にしながら今後進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/540863?Template=document&Id=3436#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":33165,"voices":81}},{"id":"h28-20160119-8","meetingId":"h28-cm01","date":"2016年1月19日","dateIso":"2016-01-19","committee":"建設委員会","time":"午後 １時００分～午後 ３時４８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件整理しています。","topics":[{"id":"topic-01","title":"の区営住宅および都営住宅（平成２８年２月）の入居者募集","agenda":"の区営住宅および都営住宅（平成２８年２月）の入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"このところの応募の人数の傾向をちょっとお伺いしたいのですが、このところ増えているのでしょうか、減っているのでしょうか。その原因についても合わせてお考えをお聞かせほしいと求めました。","respondent":"矢木住宅担当課長","answer":"その前の平成２７年１月の場合も、１１倍から８９倍までですが、平均して３７.２倍ということになっております。それぞれのお部屋の大きさであるとか、対象人数でありますとかでさまざまですので、ちょっと一概には把握できないというのが現状です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"大変多くの方が求めているということですので、ぜひ区民要望もありますので、積極的に区営住宅の増設に向けて努力してほしいと求めました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"今のお話の中でも、要は建物は違うけれども、制度的に区営的な使い方で空き家を利用するとか活用するという考え方はないのでしょうか。そこまでする必要はないと区は思っているのか、いかがか尋ねました。","respondent":"矢木住宅担当課長","answer":"空き家対策としては住宅確保要配慮者に対する住宅供給というのは当然のことながら検討する課題になるものと認識しておりますし。ただ、また都や区といった状況とは違うものがありますことから、またそれはそれで別個の課題としては認識しています。","id":"exchange-003"},{"speaker":"西本委員","kind":"意見","question":"何か条件付でもいいので、安く提供できるような何かそういうのができたらいいと思っています。私もちょっと研究していきますが、ぜひとも検討をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]},{"id":"topic-02","title":"の品川区立区民住宅ファミーユ大井における漏水事故に係る損害賠償請求事件経過報告","agenda":"の品川区立区民住宅ファミーユ大井における漏水事故に係る損害賠償請求事件経過報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"最初ちょっとわからなかったのですが、上部の階、７階だから８階ですか、ここから水漏れしたと、それの原因がわからないということですが、建物が古いからですか、そこをもう一回確認したい。","respondent":"矢木住宅担当課長","answer":"浴室に設置していた洗濯機のトレイとトラップ、それが階下の和室のほうにしみ出していった、そういう形です。要はトレイより下部で管が外れたということで、そこが原因であることから、上階の人の原因ではないというふうに認定されたものです。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。本人はもう引っ越したのですか、まだ住んでいるのですか、どうなっているのか尋ねました。","respondent":"矢木住宅担当課長","answer":"こちらの訴訟につきましては、平成２２年にまず建物の明渡し請求の訴訟をしておりまして、今般の訴訟を提起する前に勝訴判決を受けて退去しております。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"滞納されているということにおいては、滞納は滞納で処置はされているということで二つ、同じ人なのですか。２種類あると思うのですが、そこの関係性がちょっとうまくわからないので、整理してもらってよろしいか尋ねました。","respondent":"矢木住宅担当課長","answer":"もう１種類、原告の方はご夫婦だったのですが、和室におられて、たまたま天井の一部が落下したことによって、そこで頭部に当たってけがをされた。そのけがに対する補償であるとか、休業補償とか、そういう内容です。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"今回の判決が出たことで、今後どのような影響が出てくるのか、そこら辺を区としては考えているのかお伺いしたいのですが。","respondent":"矢木住宅担当課長","answer":"次に、原因を特定した上でお客様に十分説明をした上で、たまたま漏水箇所がわからないというようなこともあります。そういった対応をいたしまして、あと入居者に対するご説明をした上でご理解をいただいている、そういったところです。","id":"exchange-008"}]},{"id":"topic-03","title":"の品川区の環境に関する各計画の実績報告等","agenda":"の品川区の環境に関する各計画の実績報告等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"基準年度を平成２１年度とした理由をお伺いしたいのと、地域推進計画のほうの基準年度が平成１８年度ということで、こちらも理由をお伺いします。品川区の各計画の整合性はどうなっているのか、これから見直すという計画があるのかどうか、それをお伺いします。","respondent":"三ツ橋環境課長","answer":"その前々年度が一番一般的だと考えられておりますので、平成２１年度となっております。こちらの削減率等につきましては、環境計画等の見直しを含めて、これから検討していきたいと思います。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"４部門の増加があるのですが、やはりそうしたことになると、全体量として排出量が増えてしまうのではないかと思うのです。ですから、そういったことに対する対策というのは、ＣＯ２削減という点ではどのように区は考えているのかお伺いします。","respondent":"三ツ橋環境課長","answer":"業務部門につきましては、非常に難しい部分があります。ほぼそのようなものが多くなっておりますので、再開発だからといって業務部門が上がっているとは限らないと考えています。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと科学的な排出抑制にならないのではないかと思いますので、その辺は研究してほしいと求めましたし、私たちも研究していきたいと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"３ページにあります実績と分析というのがあって、ＬＥＤ照明設置助成ということなのですが、これは今後具体的なことが出てくるのでしょうか。今後それをどのように対策をして、家庭と業務もそうですけれども、何か計画があれば説明を求めました。","respondent":"三ツ橋環境課長","answer":"太陽光発電につきましては、非常にそこの屋根というのも１個１個非常に難しい形態になっているのは委員おっしゃるとおりだと考えています。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"ただ、助成金がいいかどうかは私はわかりません。最後に風力で、例えば地域のほうで風力発電の協定を組むとか、そういう考え方を品川区は設ける考えはありますか尋ねました。","respondent":"三ツ橋環境課長","answer":"風力発電を含め、自然エネルギーの考え方というのは、非常に難しいと考えております。規模的にどのような部分で対応が可能なのか、ちょっとそちらにつきましてはいろいろな計画の見直しを含めて検討していきたいと考えています。","id":"exchange-013"}]},{"id":"topic-04","title":"の清掃事業の概要と事業系廃棄物への対応","agenda":"の清掃事業の概要と事業系廃棄物への対応","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"微減ということなのですけれども、ちょっと消費不況というのもあるのかと思っているのですけれども、その辺はどうなのかということをお伺いします。２番目の事業用建築物に係る指導拡大ということで、例えばこのようなイメージの事業所ですというのを紹介していただけるとありがたいと思います。","respondent":"小林品川区清掃事務所長","answer":"ただ、まだまだ継続してまいりますけれども、量的に前のように何でもかんでも資源にできるものがいっぱいあるという状況にはなってきていない。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区としても、できるところから働きかけ等を含めて取り組んでいく必要があると私は思っているのですが、いかがでしょうか。あわせて、お伺いします。","respondent":"小林品川区清掃事務所長","answer":"あえて申しますと、根本的に製造システムの中の役割分担というのはむしろ国全体でその役割分担のあり方を検討していくという必要があるかと思います。だけれど、今後その実態に応じたリサイクルの全国展開に応じて区も歩調をとっていきたいというふうに考えております。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"私の勉強不足かもしれないのですが、まず基本的な用語の定義というのをお聞きしたいのですけれども、まず廃棄物はごみですか。リサイクルできるものが資源という意味なのか、その辺を確認したいのでご説明をほしいと求めました。","respondent":"小林品川区清掃事務所長","answer":"基本的には我々区民に対応するときには出された後のイメージをしておりますので、捨てるという意味で廃棄物と使わせてくださいという言い方をして。","id":"exchange-016"},{"speaker":"筒井委員","kind":"意見","question":"よろしくお願いします。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"先ほどご案内いただいたごみレポの３５ページで、こちらなのですが、資源有効利用促進法の中の扱いというふうになるのでしょうか。それをまず基本的なことなのですけれども説明を求めました。","respondent":"小林品川区清掃事務所長","answer":"学者によって違いますが、十五、六％から２割ぐらい削減できるのではないかという研究成果もあるようです。食品の食べ残し等のものにつきましては、その辺の推移を見守っていきたいと考えております。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"持ち帰りですが、そういうような取り組みについて、今後の可能性も含めて区として何かしらできることがあるのかどうか。品川区として何か可能性とか、もしくは既にやっているようなこととかがあるのかどうか、そのあたりを説明を求めました。","respondent":"三ツ橋環境課長","answer":"今委員の食品ロスに関する考え方ですけれども、各商店街の中の、もったいない推進店として推奨していきましょうという取り組みをしております。今のところ３４店舗が推進店として登録しております。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"環境課が主導となってやっていくのか、衛生がやっていくのかわかりませんが、できないものかと思うのです。そういうのを区として何かしらアクションを起こせないのかと思うのですが、ここをもう一度伺いたい。","respondent":"三ツ橋環境課長","answer":"したがいまして、お持ち帰りよりは小盛りにしていただくとか、そのような部分で推奨させていただいているのが現状のところです。しかしながら、また何か新しいことも考えていければと考えています。","id":"exchange-020"},{"speaker":"つる委員","kind":"確認","question":"だけれども、ちょっと私も国会の答弁を詳細に確認しているわけではないのですが、そこは非常に大事だと記憶しているのです。いろいろな機会を捉えて、私のほうも議会としても質問していければと思っていますので、今後ともぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-05","title":"のしながわ区民公園中央ゾーン改修工事等","agenda":"のしながわ区民公園中央ゾーン改修工事等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この所管の防災まちづくり部としましては、公園内の保育園設置が可能かどうかという判断基準というのですか、例えば面積になるのでしょうか。それとあわせて、住民説明会が２月２６日に行われるということですけれども、どういった方々を対象に説明会があるのかお伺いします。","respondent":"多並公園課長","answer":"説明会の対象ですけれども、公園から２５０ｍの範囲の約６,０００戸の方々に直接ポスティングする計画です。今委員のご紹介のとおり、子ども未来部のほうで計画しているものですけれども、一緒に連携しながら進めていこうという内容です。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"ここでやろうということで、改めて何かまた子どもたちのアイデアを募集したのかと思ったので、ちょっとわからなかったのでお伺いしました。地域によっては本当に求められているところがまだまだあって、どんどん進めていただきたいと思っているのですが、割とあるのかと思ったのです。","respondent":"多並公園課長","answer":"各地区の中で、３番目に今東中延で工事をやっていますけれども、区民公園についてもそういう形で今回アイデアを入れさせていただこうというものです。今一番ポイントとなっているのが、まず公園がどこかというよりは、保育の需要はどこが一番大きいかという話をまず聞きます。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"来年度は使えるのですか、再来年度は大丈夫なのですか、逆に言うと暗いのです。ご理解を求めても、ご理解できない方がいらっしゃるのではないかというふうに予測を立てているのですが、いかがか尋ねました。","respondent":"多並公園課長","answer":"工事説明会の前に、皆様へのお知らせについては、わかり次第すぐお知らせしてまいりたいと思います。樹木の先ほど申しましたけれども、それは一定のバッファでもありますから、そこら辺でご理解いただくように説明していきたいと考えています。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"この保育園は、ですから、やはり区民公園の予算というものを確保しつつ安全面を含めた形でうまくやっていただきたいと思うのです。最後に、キャンプ場を使えるように何とか調整できないかということはいかがか尋ねました。","respondent":"多並公園課長","answer":"今予定としては、７月ぐらいに工事の説明会を行って、現場に入っていきたいというのが現在の考え方です。もともと、平成２９年度はこちらで工事をやっているという形の段階的な整備も考えていますので、区民の方にもそうお知らせしてまいりたいと思います。","id":"exchange-025"}]},{"id":"topic-06","title":"の(6)立会川雨水放流管工事（東京都下水道局施工）","agenda":"の(6)立会川雨水放流管工事（東京都下水道局施工）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回こういった事情で遅れてしまうというのは残念なところではありますが、理由をお伺いしますとやむを得ないのかという気もいたします。それとあと、これは東京都が説明するということのようですが、そういった方々にどのような形で説明をすると聞いておられるのかお伺いします。","respondent":"和田河川下水道課長","answer":"周辺への影響、沈下等の影響が考えられますので、この辺の具体的な検討を一つ一つ慎重に検討していたというふうに下水道局から聞いているところです。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"なぎさ会館から月見橋のところに全くまだ入っていないということですか。全くではないかもしれないですけれども、なので、今回のというのは、全然まだ掘っていないと、赤線がという理解でよろしいか尋ねました。","respondent":"和田河川下水道課長","answer":"ただ、先ほど安藤委員からご指摘がございましたように、貯留管として今暫定使用している第二立会川幹線というものはできてあります。平成２４年度の末から開始する予定だったものが、２年半ぐらい検討でとまっているですので、シールドはまだ発進していないという状況です。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この検討がされて、当然いい流れで、いい形にもっていくのでしょうけれども、この検討している状況は、品川区に通知があったのか尋ねました。","respondent":"和田河川下水道課長","answer":"事実を申しますと、正式に報告がありましたのは、昨年１２月１５日、この日に区長に東京都下水道局の幹部から最終的な報告があったところです。それまでは報告はありませんでした。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"あれっと思ったのですが、ちょっとひどいのではないのというか、その辺は東京都に対して強く申し入れしていただきたい。今後もいろいろなところで絡んでくると思うので、その辺をよく言ってほしいと求めましたが、いかがか尋ねました。","respondent":"和田河川下水道課長","answer":"これまで２年半の間報告がなかったものですから、これについては強く抗議をしています。それから人工の底盤の配筋を組み始めたというような報告を受けておりますので、月見橋の家のあの敷地の中では、できることはやっているです。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"要望もしておいてほしいと求めました。これが遅れてくると、その辺の流れも全部、平成３２年の開始時期には復旧に向けていくということでよろしいのか尋ねました。","respondent":"和田河川下水道課長","answer":"なぎさ会館の全ての整備が完了するのは平成３２年の通水開始の後ですので、もう少々時間がかかるです。下水道局に問い合わせているのですけれども、まだ明らかにされておりませんので、これについては引き続き見てまいりたいというふうに考えてあります。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もう１点、場所的な話なのですけれども、今度の平成３２年のオリンピックのときに、あそこを通っていくケースも多いと思うのです。当初は３０年に終わっていればきれいな形で整備できていたと思うのですけれども、その辺も下水道局へ要望してもらいたいと思うのですが。","respondent":"和田河川下水道課長","answer":"委員のご指摘は当然ですので、強く申し入れをしていきたいと考えています。","id":"exchange-031"}]},{"id":"topic-07","title":"の(7)の平成２７年度 区内一斉防災訓練等実施結果","agenda":"の(7)の平成２７年度 区内一斉防災訓練等実施結果","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"これからもいろいろやってほしいと求めましたが、この一斉防災訓練以外で一覧を出していただきました。一斉にも、ここにもやっていないというところはあるのか尋ねました。","respondent":"黒崎防災安全担当課長","answer":"ただ年度訓練で計画を避難所ごとにしておりますので、今のところ新たに５カ所につきまして訓練の相談が入ってきております。合計しますと約１割、７避難所ぐらいがこの訓練に携わっていないというところが今年度については出てきてしまうというふうに受けとめています。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"７避難所、これが今、相談しているということなのですが、この７避難所というのは、今まではどうだったのでしょうか。今までの実施の実績というのはあるところなのでしょうか、ないところなのか尋ねました。","respondent":"黒崎防災安全担当課長","answer":"今年度未実施なのですが、昨年訓練計画をしていたのですが、それが理由で１回もやったことがないというところを除きますとございません。今まで一度も訓練経験がないというところは１カ所になると思います。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"やはり一斉にやるべきだし、何回も何回も経験して、その地域に見合ったものがあるわけです。地域の実情に合わせながらつくり上げてもらうというのが理想だと思うので、その方向についてどういうふうにお考えなのか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"いろいろなことを考えて取り組んでいただくということが大事ですので、一応体制としてはどの避難所ごとの会議も進むような形になっております。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、母体のほうで何とか手を差し伸べられるところはぜひ手を差し伸べてあげてほしいと思います。もっと実際どう訓練したらいいのか、学校現場ですから、意見という形にさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとお伺いしたいのが、当日、実際具体的にはどのような形で活動していたのかというのをまず１点お伺いするのと。今紹介していただきたいですし、みんなで改善点を出していくというのは大事だと思うのですけれども、そこら辺はいかがか尋ねました。","respondent":"黒崎防災安全担当課長","answer":"ちょっとそこまで説明しなかったのですけれども、Ａ３の表ですけれども、城南第二小学校などは応援物資搬送訓練というものをやっております。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"アンケートの点ですが、その他にいっぱい書いてみたくなるような工夫を今後していただきたいし、活かしていただきたいというふうに要望いたします。区の職員の動き方をお伺いしましたけれども、そこら辺はどうなっているのか、いかがか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"何年か前に行ったシミュレーションでは、それを逆算して３名ぐらいは最低集まるようにということで１０名程度指名をしております。場合によっては歩いてでも来られる職員がかなりの割合を占めるというような体制で避難所のほうの支援の部隊が本部から行かなくても。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"２点ほどちょっと気になる点がございまして、今後その対応はどうされるのかということと、形状が和式なのです。高齢者の方々と区民の方にとって非常に便利なので、そうした改善を行っていただきたいのですけれども、その対応についてはいかがか尋ねました。","respondent":"鈴木（誠）防災課長","answer":"アンプの設置位置によってはちょっと後ろの方とかに声が届かないということがあったので、地域センターの所長に話をしまして。ご指摘の和式便器については、その辺はちょっとメーカーのほうに問い合わせをして、対応できるかどうか確認をしたいと思います。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の質問で、最初の開始のアナウンスというのは防災無線のことを言っているのではないのですか。そこの対応はどうなっているのか、今聞きながら思ったのですけれども、今後の在庫の問題と今後の対応について。","respondent":"鈴木（誠）防災課長","answer":"それから議会でもご質問いただきまして、メーカーに確認をしたのですが、やはり５,０００台単位でないと受注生産をしてもらえない。今後も少し防災無線本体のほうがデジタル化とか、今後改修計画がありますので、ちょっとラジオの追加発注の予定は現在のところございません。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"資料１の一覧で、町会・自治会、括弧の中は町会数、そして議員のところなのですけれども、何人かの議員もいました。何人がどういう状況なのかというところで、私たち議員のような者もこの中の数字に反映されているのかどうか、これを一つまず説明を求めました。","respondent":"黒崎防災安全担当課長","answer":"各避難所に町会ごとに訓練でお集まりいただいたときに、そこの受付で避難所の名簿を作成いたします。その実数を得たものですので、委員からご質問のあった各議員の皆様の人数は、申しわけございません、入れておりません。","id":"exchange-040"},{"speaker":"つる委員","kind":"質問・要望","question":"特段名簿とかで出欠をとっているという姿もなかったものですから、その辺の把握をどういうふうにしているのかというところを確認させていただきたい。そういうものも中に混在していたのですが、この辺の管理というのはどういうふうにしているのか教えてほしいと求めました。","respondent":"鈴木（誠）防災課長","answer":"１点目、議会のほうで実施された訓練で、先ほど安全担当課長からご説明しましたように。議会の事務局からは、ちょっと議員の方が、どなたが何人いらっしゃったかというのは把握するという予定をしていなかったというものです。","id":"exchange-041"},{"speaker":"つる委員","kind":"確認","question":"実際そこに寝ていただいたものですから、最新のというか、そういう細かい整理といいましょうか、やっていただくようにお願いしたいと思います。そういう姿勢はいかがなものかとちょっと思ったものですから、参加しているときにはどういうふうに反映されているのかと思ったものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]},{"id":"topic-08","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"現状はどうなっているのかをお伺いしたいというか、そういった提案ができないか、現状はどうなっているのかをお伺いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"安藤委員","kind":"意見","question":"紙ベースで資料コーナーにあるということかもしれないのですけれども、もっと開かれたという意味では、やはり議会ホームページ等で公開していったほうがいいのではないかという考えを私は持っていますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"安藤委員","kind":"意見","question":"ご説明の中で、区が１００m2未満では公園用地に買わないという規定があるというお話だったのですが、そこら辺はどういった規定に基づいてそういうふうになっているのか、そこら辺のルールがあれば、もう少し説明をいただければと考えていますとの意見を述べました。","respondent":"寺嶋木密整備推進課長","answer":"例えば国費であり、基本的には１００m2未満ですと防災広場、それからその他の事業活用としてなかなか効率的な手法が見込めないということから。必要数等にももちろん関係はしてきますけれども、一つの基準としてそのような数字をもとに事業を進めているところです。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"ちょっともう少しお伺いしたいのですが、つまり、国や都との補助金事業との関係ということなのでしょうか。どういう条例なのか、それとも区の考え方ということなのか、そこら辺をあわせてもう少しお伺いします。","respondent":"寺嶋木密整備推進課長","answer":"数字上の基準という観点でいきますと、東京都の基準を準用しているということがまず数字的な問題です。実態として防災広場として活用できる面積がどの程度が妥当なのかというところですが、これは運用上区のほうで判断してやっているところです。","id":"exchange-046"},{"speaker":"安藤委員","kind":"確認","question":"ホームページのほうでアップしていると思うのですが、それもすぐ修正になるのでしょうか、そこだけちょっと確認をしたい。ホームページのほうで、これをアップしていると思うのですが、それは修正されるのか。","respondent":"鈴木（誠）防災課長","answer":"区のホームページでは、ＰＤＦのデータを公開しておりますので、そちらのほうも新しいものとリンクを交換しまして、区民の方にご覧いただけるようにしたいと考えております。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"もし区としてつかんでいることがあればお伺いしたいのと、もしとられたことがあるのであれば、教えてほしいと求めました。","respondent":"鈴木（誠）防災課長","answer":"この週末から月曜にかけての雪の対応ですが、それから建設防災協議会のほうで３班のパトロール部隊に待機いただきまして対応したところです。実際に区内の被害状況ですが、区がかかわって対応するような被害はございませんでした。","id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862367?Template=document&Id=4160#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":50688,"voices":136}},{"id":"h28-20160119-9","meetingId":"h28-cm01","date":"2016年1月19日","dateIso":"2016-01-19","committee":"文教委員会","time":"午後 １時００分～午後 ４時５４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件整理しています。","topics":[{"id":"topic-01","title":"品川区教育大綱の策定","agenda":"品川区教育大綱の策定","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"２番の第３回品川区総合教育会議の(2)のところで、主な意見というので、これを主に今回の大綱素案に入れ込んだということなのでしょうか。具体的に、これがどう入って、どう具体策になっていくのかというところなのですけれども、説明を求めました。","respondent":"品川庶務課長","answer":"ちょうど第３回の総合教育会議に出された資料と全く同じものとなっておりますので、現在、まだ大綱のほうには反映されていない状況です。今後、この意見も踏まえまして、大綱のほうをまた新たに修正をしていこうというような流れです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、これから意見を新たにここにまた取り入れた素案になっていくということは、まだもうちょっと意見を聞いていただけるということなのですか。それとも、もうパブコメは終わったわけですけれども、区民からの意見はもうこれで終わるということになってしまうのか尋ねました。","respondent":"品川庶務課長","answer":"そうですね。そういったところの意見を踏まえまして、大体３月ぐらいをめどに大綱のほうを完成させていただきたいというふうに考えているところです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"提案","question":"これを見ると、新しい文言で新しい提案はされているのですが、基本の根底に流れるところをしっかりと位置づけてほしいと求めました。この辺についてどういう状況なのか、ここに何が込められているのか、お伺いしたいと思いますとの意見を述べました。","respondent":"品川庶務課長","answer":"それに合わせて、学校のほうも改築等も進めている部分があります。そういったところも踏まえまして、今後、学校のあり方というのを検討していきますというような意味です。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見をぜひ言わせていただきたいのですけれども、人口減、環境をよくしていく方向でぜひご検討をお願いしたいと思います。これは意見として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（博）委員","kind":"質問","question":"同じ６ページなのですけれども、青少年教育の充実というところの丸の４番目で、抜けているのです。その辺の文言というのはぜひ入れて、それに関しても目配りしていますよというような視点というのは必要だと思うのですけれども、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"いわゆる問題行動とか非行防止というふうな視点で、多分、ここに十分書かれている部分だと思います。ただ、エイズ等につきましては、少しまだ意見のほうはこちらのほうで承らせていただければというふうに思っております。","id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この辺はぜひ再考をお願いしたいと思いますが、いかがでしょうか。非行の定義だけお願いします。","respondent":"村尾教育総合支援センター長","answer":"健康教育というのはまさに学校のほうでも十分注意をしています。今後違う形で各学校等で周知をしていくかについては、また検討させていただければというふうに思っております。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問・要望","question":"２つほどお伺いしたいのですが、まず、今回のパブコメですけれども、受付が約２週間です。意見が７５件ということで、この件数に関しての評価というのでしょうか、それを一つお願いしたいと思います。","respondent":"品川庶務課長","answer":"２点目のＩＣＴの件ですが、例えば、ネット環境のみで起業の手続なんかもできるような仕組みも最近はある傾向もあります。しっかりと使っていただいて、社会全体にメリットが出るような形で検討していきたい、このように考えております。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つお伺いしたいのですが、どのようにすれば効果的に推進されていくのでしょうかというところがありますので、どのような考えをお持ちなのかということをお伺いします。","respondent":"品川庶務課長","answer":"区長部局との連携については、区長部局と教育委員会、非常に密接していろいろな行動を行ってきております。これをさらに継続していくというような意味合いで、ここの８ページの図のほうは書いているです。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"具体的に、こういうところがあったので連携がなかなか進んでいない部分もあったのでしょうかと言うつもりはないのですけれども、そうすると。具体的に新しい体制がないとすれば、その辺についてのお考えだけ伺いたい。","respondent":"品川庶務課長","answer":"これは十分連携をしながら進めていっていたというところが、改めて何かをしていくという考えはなく、従来どおりの連携をしていくということでの表記というような形になっております。","id":"exchange-009"},{"speaker":"伊藤副委員長","kind":"質問","question":"あえてやっていることをどうして、多額の税金を使って大綱をまとめたのでしょうから、議会としては。より具体的に身を入れるための政策まで昇華していかないことには、この大綱の目的の話はできないと改めて思うのですが、いかがか尋ねました。","respondent":"品川庶務課長","answer":"あくまでも連携する形というような形での説明でありまして、それから、この辺については当然前向きな形を表記というようなことで書いております。ですので、そういう中で今後の政策の打ち合わせをしていくというような形になっていくかというふうに思っております。","id":"exchange-010"},{"speaker":"伊藤副委員長","kind":"質問","question":"多分こういうのは税金を使ってつくっているのでしょうから、政策を具体化していかないことには、目的は達成されないと思うのです。お伺いしたいのは、庁舎内の会議体の設置等々について、これからこれをどのように具体化していくのかということを説明を求めました。","respondent":"品川庶務課長","answer":"その課の中での話し合いをしながら進めていく、そういう話し合いをするにあたっては当然会議体もつくっていくというような流れになるかと思います。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"最初のアンケート、これはいつからとられているものなのか教えてください。それで、学校運営の改善につなげるというのが目的には書いてあるのですけれども、今時点で改善点は何があるのかを伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"ですから、学校選択が始まってもう１６年たつのですけれども、十数年やっているということです。いろいろ複数回答になるのですけれども、また、それぞれの学校で学校運営の中に役立てていただきたいというふうに考えているところです。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"意見","question":"例えば、どんな改善がこういうアンケートでされているのかというのを、例で挙げていただけるとの意見を述べました。","respondent":"野呂瀬学務課長","answer":"昔とどう傾向がまた違っていたのかという視点で答えしますけれども、学校選択自体も１０人に１人ぐらい、１０％ぐらいの学校選択だった。それよりも、教育の内容とか、学校選択をする前に各学校でやっている学校説明会で学校のやり方だとか運営の仕方だとかに共感を持ったとか。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"確認","question":"ちょっと確認と、それと、就学指定通知の学校に通うことになってしまう、要は、希望した学校に入れない子どもたちというのは、毎年出るものなのか。合計としてどれぐらい出てしまうものなのか、あれば説明を求めました。","respondent":"野呂瀬学務課長","answer":"それと、学校選択というのはあくまでも学区域のお子様を第一優先で入れて、学区の中で受入れ予定数をオーバーしたときには抽選になります。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"希望したところに入れない残念感というのは、聞かれているところはあるのか、教えていただけますか。","respondent":"野呂瀬学務課長","answer":"その学校に入ってよかったというのは、小学校では９割以上、中学校でも８５％ぐらいあったと思います。学校に行ったら、その中で子どもたちもその学校で学ぶうちに学校のよさとかになっていくというのはあるのではないかと考えているところです。","id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"質問","question":"９０名のところ、無抽選で最初から１３５名、何で学区の人が受入れの予定数より多いのでしょうか。同じ質問かもしれないのですけれども、納得できるご回答をお願いしたいのです。","respondent":"野呂瀬学務課長","answer":"御殿山小学校の３クラス９０名というのは、教育委員会からの案内通知には、３クラス９０名は受け入れる予定ですと宣言するわけです。","id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"先ほど学務課長のほうから、毎年同じだったらどうして変えるように変更するとかというような検討というものはされないのでしょうか。その辺のご回答をお願いしたいのですが。","respondent":"野呂瀬学務課長","answer":"６４名については学校選択を希望しなかった人でその学区にいるという方で、それは無抽選という表示にさせていただいたということです。だから、今後の親御さんとか本人の動向で変わってくるということですので、受入れ人数と優先順位のところに差異が生じるということです。","id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問","question":"だったら１月３１日ではなくて１週間延ばしたほうが、１月３１日から１週間ぐらい延ばすご検討というのはされないのでしょうか。７日ぐらいになるとはっきり、１週間ずらせば精度が大分違うと思うのですけれども、それはいかがか尋ねました。","respondent":"野呂瀬学務課長","answer":"学校のほうからそういう把握が最終的にできていなかったり、ですから、ほとんどが２月上旬にできております。転出予定だとか、３月までに転出予定だとかいう情報も固まりますので、決めさせていただいたものです。","id":"exchange-018"},{"speaker":"浅野委員","kind":"質問・要望","question":"もしかすると、そういう形勢というのでしょうか、可能性があると知って学校選択制を今回やってみようとする家庭というのはおられるのかどうか。そういうふうに考えた場合に、希望申請を出される人にはお伝えされているのかどうかということについて、情報があれば説明を求めました。","respondent":"野呂瀬学務課長","answer":"このアンケートにどれぐらい検討しましたかといったとしても、似たような学校はここかここかみたいなところを選ぶ方もいらっしゃると思います。","id":"exchange-019"},{"speaker":"浅野委員","kind":"意見","question":"やはり親御さんにしてみれば、希望を持って学校選択制を使っているというところの中では、もう少し兄弟枠のところについては慎重にさらに周知のほうを検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どう思っていらっしゃるのか教えてほしいのと、中学校は２月末のところで決定していくというのですが、その後どうなっていくのかというところを１つ。結果発表の後に他区から転入されてくる方にどうご案内をして、どう決まっていくのかを説明を求めました。","respondent":"野呂瀬学務課長","answer":"これも学校選択希望のときにはこういう結果が出ました、ほかも総合的に勘案して、今後に活かしていただきたいというふうに思っているところです。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"確認","question":"結果発表後はその学区域、あと、抽選に漏れた方も全て自分の学区域だったら吸収ができるということで確認、よろしいか尋ねました。","respondent":"野呂瀬学務課長","answer":"先ほどおっしゃったとおり、そのとおりです。学区域に戻るというのも勘案して抽選を行っておりますので、抽選に漏れたら基本的には学区の学校に戻っていくというのがルールになっております。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認ですが、学区が決まっているわけですけれども、この学区というのはいつごろ決まったあれですか。もしわからなかったら、ここ二、三年でなければ。","respondent":"野呂瀬学務課長","answer":"昭和２０年、昭和３０年、数十年前からやっているものです。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問","question":"では、その学区というのはいつ決められたのかというと、今のお話で数十年前だというふうな話を考えていくと、それが１つ。数字的なものをもっときちんと何年間もこれからも考えていく必要があると思うのですが、そういうことについてはいかがお考えか尋ねました。","respondent":"野呂瀬学務課長","answer":"学区の考え方ですけれども、それは昔からあったと思うので、学校選択に伴って学区域は今のところずっといじってはおりません。そういうのを検討する協議というのは必要だと考えていますので、今後、教育のあり方を検討する協議は必要だというふうに考えてはいるところです。","id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"確認","question":"そういうのを設置する必要があるのだと思うのですけれども、それは課長のお話ではないかもしれませんが、それだけ確認です。どなたかちょっとわからないですけれども。","respondent":"品川庶務課長","answer":"場所によっては、芳水小学校などについては改築というような方法で、就学人口の増に対応しているケースもあります。就学人口の増に対して、対応する措置の一つとして考えられる選択肢は何かなというふうには思っております。","id":"exchange-025"},{"speaker":"伊藤副委員長","kind":"質問","question":"今、ほかの委員からそういう学区域の話もあったけれども、もっと総合的に対策を考えたらどうなのでしょうかという思いがすごくあるのです。そこまですることは品川区が選択制を導入した責任ではないのですかと思うのがいつもついて回るのだけれども、その辺のお考えはいかがか尋ねました。","respondent":"野呂瀬学務課長","answer":"ほかの学校に行きたいという理由で、これは指定校の変更という手続があるのですけれども、その手続の中でやっていると。先ほど申しましたとおり、今後、品川区の教育のあり方を検討する中で協議をしていくのは必要と考えているところです。","id":"exchange-026"},{"speaker":"伊藤副委員長","kind":"質問","question":"調整をするなり、検討会を立ち上げていくなりするべきではないでしょうかと思うのですが、考え方をお聞かせください。すぐにできる、できないは言えないでしょうから、考え方だけ説明を求めました。","respondent":"本城教育次長","answer":"こちらも今、副委員長もおっしゃられましたように、選択制のベースにあります諸制度があります。１つは、しっかり検証、検討していかなければいけないと考えているところです。","id":"exchange-027"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"要望だけ伝えますけれども、進めてよいかと思うのですけれども、それについていないさまざまな古い制度は当然あるわけです。学校選択制を導入したのは品川区のほうですから、中学校の学区に入れますように、柔軟な調整をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-02","title":"平成２８年度品川区立学校における土曜日の授業の実施","agenda":"平成２８年度品川区立学校における土曜日の授業の実施","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"品川区の授業というのは、ほかと比べると、授業時間が多いのでしょうか。その辺も説明を求めました。","respondent":"渋谷指導課長","answer":"校長会等のやりとりの中で、土曜日授業については第１・第３、２回が適切であるという意見が圧倒的な多数だというふうに認識しています。他区の状況は今、詳しくはわかってはおりませんけれども、月２回というのは比較的多いほうの部類には入るのかなというふうに思っています。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１週間のリズムとか１カ月のリズムとか、ぜひ子どもたちの声も聞いてほしいし、やはり能率の上がる勉強の仕方というのはあると思うのです。そういった面で、土曜日授業はどんなものかというのをぜひ総合的に勘案してほしいと求めましたが、いかがか尋ねました。","respondent":"渋谷指導課長","answer":"月２回やることで、２日休みになることで、多くの子どもの生活リズムが乱れるというような現象も現場の声としてたくさん上がってまいりました。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろな方のご意見をぜひ聞いてほしいのと、文化芸術にも触れてほしいといった意味で、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"鈴木（博）委員","kind":"質問","question":"土曜日は月２回、非常に評価が高いので、いいことだという意見が豊富にある。そのときに実際小学生の子どもたちがどういう生活をしているかというようなアンケートとか調査とかは教育委員会のほうでされているのか尋ねました。","respondent":"渋谷指導課長","answer":"第２・第４土曜日に具体的にどういう生活をしているかというピンポイントに絞ったアンケート調査はしておりませんが、休みの日にどんな過ごし方をしているのか等々というのは、全児童・生徒アンケート等で把握をしているところではあります。","id":"exchange-032"},{"speaker":"浅野委員","kind":"質問","question":"今は道路で遊ぶと危ないということで、なかなか遊ばない子どももいると思いますけれども、どうなのでしょうか。やはり体を動かしたほうがいいという観点からすると、どうなのかということで、教育委員会のお考えをお願いします。","respondent":"村尾教育総合支援センター長","answer":"一輪車というような、学校にある遊具等で遊んだり、体を動かす取組みについては随分多くの学校で取り組んでいるかなと思っています。図書室で本を読むという子どもたちもいますし、いろいろな形で子どもたちは休み時間をうまく使いながら、交流をしているというふうな内容です。","id":"exchange-033"},{"speaker":"浅野委員","kind":"意見","question":"スポーツと学業ということで、子どもたちに一番必要な事柄が満遍なく行われているというふうに認識をしました。これからも続けていってほしいと求めました。","respondent":"渋谷指導課長","answer":"土曜日や日曜日など、これは今度、全く勉強しないという子が１１％とかというふうに増えるという状況はあろうかと思っています。それから、休みのときには一旦勉強率は下がるというのは顕著にあらわれているのかなというところを読み取ることができます。","id":"exchange-034"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"それで、要するに、学校がない日の土曜日にどのように有効に時間を使うかということを教育委員会としても配慮していただきたいと思うのです。ある程度教育委員会のほうでも配慮していただければいいのではないかということを考えているのですけれども、いかがか尋ねました。","respondent":"伊崎子ども育成課長","answer":"平日、学校がある日の放課後に加えて、土曜日も朝から夕方まで子どもたちを迎えております。学習支援の場でもありますので、学習活動の支援、すまいるスクールとしては行っております。","id":"exchange-035"},{"speaker":"鈴木（博）委員","kind":"質問","question":"すまいるスクールというのは非常にすばらしい活動をされているということでお聞きして、子どもがしっかりとその部分を育まれて、学べるような環境をつくっていただいたほうがいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-03","title":"御殿山小学校西側敷地の事業計画案","agenda":"御殿山小学校西側敷地の事業計画案","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"今、２階の平面図を拝見させていただいたのですけれども、ベビーカー置場というのがあって、授乳室があるということは、ここまで結局、ベビーカーで入ってこられるということか尋ねました。","respondent":"木村品川図書館長","answer":"あくまでも仮ですが、そのようにこの図では想定をしています。","id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"質問","question":"図書館というのは静穏なところですから、話が出てくると思うのですが、それに対しては何か対策とかというのはないのか尋ねました。","respondent":"木村品川図書館長","answer":"こちらに関しましては、本当は委員おっしゃるとおり、今の図書館でも実際に起こっている問題であります。ご意見を賜りまして、これから中身につきましては検討してまいりたいというふうに考えています。","id":"exchange-038"},{"speaker":"浅野委員","kind":"質問","question":"高齢者の方の施設が隣接するということで、３ページ、１階平面図案というのがあるのですが、左側が北側になるのでしょうか。図面の左側が北側になるのか。","respondent":"木村品川図書館長","answer":"そうです。","id":"exchange-039"},{"speaker":"浅野委員","kind":"質問","question":"その上側というのでしょうか、東側がここですね。１階平面図案を見ると、２カ所、それはどのような考え方でおられるのか教えてほしいと求めました。","respondent":"木村品川図書館長","answer":"委員のおっしゃるご指摘は今までも、この説明会の中でもいろいろとご意見として頂戴したところです。老健施設と図書館と、どのように配慮していくかというところを今後検討して、きっちり安全管理をしていきたいと思っています。","id":"exchange-040"},{"speaker":"浅野委員","kind":"質問","question":"看板を立てるだけで済むものではないと思いますし、そういう一般車の方への対応についてもお考えがあれば教えてほしいと求めました。子どもたちもご高齢の方というのはということで、いい勉強にもなるかと思いますが、いかがか尋ねました。","respondent":"木村品川図書館長","answer":"しっかり検討して対応していきたいと、そこまでしかお答えできませんが、考えてまいりたいと思います。一体として考えているというところで、事業者のほうもそのような発想で建物のほうを考えています。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つは、区立図書館のところが２階で１,５７５.３３m2ということで、イメージを聞かせていただきたいのが１つです。品川区立ですけれども、区立であって、運営がどうなるのか説明を求めました。","respondent":"木村品川図書館長","answer":"老健との併設という部分も極めてユニークな建物ですので、そういう部分を活かした中身にしていきたいというふうに、今のところは考えています。基本的には同様になるという形で想定をしております。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここには本当に図書館を充実してほしいという願いがあるので、移転でなくて、充実をさせてほしいと求めました。地域の子どもたちもすごく来やすくて、そういう図書館を存続してほしいという思いはしっかりとお伝えをしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]},{"id":"topic-04","title":"平成２８年度すまいるスクール利用料の減免等","agenda":"平成２８年度すまいるスクール利用料の減免等","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"減額と免除が何人ぐらいになるのか人数、またはパーセントを教えてほしいと求めました。","respondent":"伊崎子ども育成課長","answer":"こちらはあくまでも試算ですけれども、まず、免除対象が先ですので、免除対象は２５.６％程度の方が、試算で出しますと対象になると考えております。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、２人以上いるときに、最年長である児童１名を除くその他の児童を対象に半額になるということなのですけれども、３人目というのはどうなのか。それで、５割というのは何を根拠に行ったのか、伺いたいと思います。","respondent":"伊崎子ども育成課長","answer":"５割というのは、特に児童健全育成事業等の利用料につきましては国の示すものがございませんので、区の判断といたしまして、５割減といたしました。ちなみに学童保育料としていただいていたときも同じ２人目以上の兄弟が、５割減とさせていただいておりました。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それが２人目は半額で、３人目も、これはもっと減額してもいいのではないかと思うのです。ぜひ３人目をさらに下げる、もしくは無料にしていっていただきたいと思うのですけれども、伺いたいと思います。","respondent":"伊崎子ども育成課長","answer":"その中で、金額が高いために利用ができないということがないように、対象としては低所得の方を中心とした世帯に対して減免を行うものです。このような考え方から、３人目以降についての減額率を変えるということは、現在のところは考えておりません。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ考えていただきたいと思うのですけれども、どういった形でやられたのかというところをお聞きしたいのと、どのような説明や周知がされるのか伺いたいと思います。","respondent":"伊崎子ども育成課長","answer":"昨年の秋の学校説明会のときに紙ベースの説明書を渡していただきまして、説明会は１月末から２月にかけて、説明会を行いたいと考えています。在校生につきましても、２月、３月に保護者会がありますので、そのときにご説明をいたします。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"説明会後でもいいのですが、保護者の方からの声なんかはどのように聞かれているのか、把握されているのかというところをお伺いしたいのです。私のところには、やはり３,０００円という驚きの声が……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、そこら辺から伺いたいと思ったのです。そういった声があれば伺いたいのと、午後６時までが３,０００円で、子どもたちの放課後の育成の場の金額だったわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、先ほど言った説明会では子どもの声と、あと、私たちのところには高すぎるという声が届いているのですけれども、今後、そういった声があれば検討はしていくことになっていくのかを伺いたいと思います。","respondent":"伊崎子ども育成課長","answer":"説明会のときには、免除が決まっておりませんでしたのでご説明ができませんでしたが、進めてまいりたいと考えています。時代の流れの中でさまざまな面から検討はもちろんされていくもので、これが全く未来永劫固定したものということでは考えておりません。","id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これから進んでいくことですので、保護者の皆様の声を聞いていただいて、それから、３人目のところの検討なんかも、いろいろ再検討をしていきながら進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"浅野委員","kind":"質問・要望","question":"そのような中で教えていただきたいのが、当初予定していた歳入があるかと思います。どのぐらい減ってしまうのかということについて、大まかで結構ですので、教えてほしいと求めました。","respondent":"伊崎子ども育成課長","answer":"詳細につきましては、来年度予算になりますので、大まかな数字でお答えいたしますと、こちらの当初の算定時には、約６,０００万円ほどの歳入を見込んでおりましたが、この減額をかけたところによりまして、２,０００万円ほど減少すると見込んでおります。","id":"exchange-052"},{"speaker":"浅野委員","kind":"質問・要望","question":"２,０００万円の減収ということで、よろしいのではないかなと、このように思います。これからの発展とか、計画なども立てていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"確認","question":"細かいことで申しわけないのですけれども、平成２７年度まではすまいるスクールの利用料は年度当初に一遍に納めていただいたという認識で、平成２８年度からは銀行の引き落としで毎月利用に応じて、そういう引き落としの体制だということの確認なのですけれども。","respondent":"伊崎子ども育成課長","answer":"委員のご指摘のとおりです。３,０００円と４,０００円につきましては月ごとの引き落としで、午後５時までの２５０円につきましては半期ごとの引き落としと考えております。","id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、これまでよりも、委託でしょうか、その事務作業というのが相当大変になると思うのです。まず委託のほうとどういう打ち合わせをしているのかということと、気がついたらたまっていて、その辺についての対応をどのようにお考えか尋ねました。","respondent":"伊崎子ども育成課長","answer":"そのシステムの構築については、前回もお話ししましたが、今進んでおりまして、２月にはテストをと考えているところです。滞納につきましては、それでも引き落としができない方については督促状をお送りして、ご納付をお願いするということにしてまいります。","id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"意見","question":"平成２７年度で変わって、ご負担いただくということですので、ご利用する方のお支払いにいろいろな問題が生じないように、今までのやり方と違って負担の額も増えますので、その辺をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのですけれども、３人目がいる率というのがわかれば教えていただきたいと思うのと、申請についてはどういうふうにしていくのかというのを教えてほしいと求めました。","respondent":"伊崎子ども育成課長","answer":"申請の書式につきましては、今、いろいろ検討はしていますが、申込書と延長利用とは別々の形でしまして、減額について丸をつけるような形にしたい。４人いらっしゃる方が７世帯いらっしゃいます。","id":"exchange-057"},{"speaker":"大倉委員","kind":"質問","question":"４人いる世帯が７世帯ということは、２８人ということでいいか尋ねました。","respondent":"伊崎子ども育成課長","answer":"そのとおりです。","id":"exchange-058"},{"speaker":"伊藤副委員長","kind":"質問","question":"１人当たり平均これだけお金がかかっていますよと、出てくるわけですよね。そのうちにこれだけの金額を今回使わせていただきますというようなことになれば、相当理解が進むと思うのですが、いかがか尋ねました。","respondent":"伊崎子ども育成課長","answer":"委員ご指摘のとおりでございまして、保護者会のときにも、そういった総経費の中での保護者の方のご負担ということも説明しております。これからもそういった大きな視点でのお話も含めて、きちんとお伝えして、理解を求めていきたいと考えております。","id":"exchange-059"},{"speaker":"伊藤副委員長","kind":"質問","question":"そのときになって、今回のような騒ぎにならない可能性も出てくるわけではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"減っていて、やっていけない状況ではないし、十分やっていける財源があるにもかかわらず、かかっていなかったことに不満はどこから出ていたのですか。やはり漏れがないための努力を十分していただきたいのですけれども、どのようなことを考えておられているのか説明を求めました。","respondent":"伊崎子ども育成課長","answer":"そういった意味での放課後教育への支援というのは、かなり低額に抑えた形で今回も考え、設定をしております。すまいるスクールの開始時間からのご利用の時間帯も含めまして、減免という形で、それぞれの能力に応じたご負担をいただこうと思っているところです。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"区民の側から声がいっぱい出ているということですか。いただいている声なのか尋ねました。","respondent":"伊崎子ども育成課長","answer":"利用者の方は子育て世帯ということでございまして、こちらの子育て世帯に対するコストが１１億１,４００万円、平成２６年度決算でかかっていると。","id":"exchange-062"}]},{"id":"topic-05","title":"子ども・子育て計画の一部改訂","agenda":"子ども・子育て計画の一部改訂","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"１つだけお聞きしたいのですけれども、今の課長のご説明だと、１号認定と２号認定で平成３０年度はプラス２７人になると言っていたと思うのですけれども、これを見てみると、平成２８年度から１号認定と２号認定はプラスになっているように見えるのですけれども、これはいかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"委員ご指摘のとおり、プラスマイナスの差は確かに平成２８年度から改善できているという状況です。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問","question":"説明の中身からすると、ほかの部分はそんなに変わりがないという捉え方で、ここのところだけを注目すればいいのでしょうか。その点を説明を求めました。","respondent":"伊崎子ども育成課長","answer":"先ほどお話しいたしましたが、ほかの部分についても数字は変わっておりますので、後ほどまた改めて全体を報告します。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"確保の方策のところも、具体的にこの後の長い横の表を見るとわかるのでしょうか。確保方策がどう構えられていて解消するのか、そこのところを説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"３４５人の受入れ枠の拡大を考えておりましたが、８５４人の拡大枠という形で、この計画をつくっているところです。平成３０年度が６園、平成３１年度が４園という形で推移しておりまして、それぞれの内容が細かく４ページに記載されているところです。","id":"exchange-065"},{"speaker":"浅野委員","kind":"質問","question":"前にもいろいろと区域ごとに見るとどうなのかという質問をさせていただきましたけれども、このような見方で資料をつくられる予定とか、そういうのはあるのかどうかお聞きします。","respondent":"今井待機児童対策担当課長","answer":"この資料の１ページ目の１番のところにありますけれども、品川区としては、子ども・子育て支援事業計画でも一つの区域での保育料を出しています。逆に言うと、入園の申込み、それを踏まえながら開設のエリアについては検討をさらに進めていきたいと考えています。","id":"exchange-066"}]},{"id":"topic-06","title":"都市公園内における認可保育園の開設","agenda":"都市公園内における認可保育園の開設","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"大事な保育園のところをぜひ公設公営で運営してほしいということを常々主張しているわけですけれども、そこのところを１点、お伺いいたします。","respondent":"今井待機児童対策担当課長","answer":"品川区は、ご案内のとおり、平成２２年度から民間の事業者による保育園の開設に積極的に取り組んでまいりました。さまざまな事業者が工夫を凝らした保育を進めているところですので、１０年間の期間が可能ですので、私立保育園で進めるものです。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その１点をお伺いしたいのと、品川区内の保育園では、大きな事故はそんなに起こっていない。民間でできるところは民間で、ぜひ考えを改めていただきたいと考えていますが、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"子ども・子育て支援新制度の対象内施設がどのように運営されているか、品川区も指導検査という形で係もつくり、対応しています。今、引き続き子どもの安全・安心に配慮した運営が公立、私立とも適切に進めなければいけないものと考えております。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はぜひ区の確認の役割を十分果たしていただきたいのと、きちんと長続きして、私は品川区独自のチェックがあってもいいと思っているのです。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"浅野委員","kind":"質問","question":"西大井広場公園に続いて２つ目ということで、開設をされるということで伺いました。めど、場所のあるなしというのも要素としては入ってくると思うのですが、お考えがあれば説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"来年度の予算といいますか、来年度検討したいことの一つでもありますけれども、また来年度引き続き検討していきたいというふうに考えております。国の都市公園法の改正にも広場を３０％までの活用ですとか、今後、来年度改めて検討していきたいというふうに思っております。","id":"exchange-070"},{"speaker":"伊藤副委員長","kind":"確認","question":"夜間保育をやるのでしょうから、それから、保育園を通って公園の中に入らないようにするという対応も必要ですよね。そういうことは担当課で調整をとっていただけるのでしょうかという確認をお願いします。","respondent":"今井待機児童対策担当課長","answer":"開設が平成３０年を予定しておりますので、たしか一部の門は９時まであいていたりですとか、そこの点は十分検討していきたいと考えています。","id":"exchange-071"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"２点お伺いしたいのですけれども、３ページ目のコミュニティ・スクールのところなのですけれども、言い回しが難解なのです。何でこういう難しい漢字が並んでいるものにしたのか尋ねました。","respondent":"渋谷指導課長","answer":"かなり事務局でいろいろな選択肢を検討してつくり上げた名前で、ちょっとしていい名前が出てくれば、考えていきたいと。特に学校支援地域本部については、例えば、そんなふうな愛称を使って進めていければなというふうに考えているところです。","id":"exchange-072"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"要するに、日本のことを英語で話すというような、逆の立場の取組みとかというのはあまりお考えにならないのでしょうか。通り一遍の学習でいいというものでもないわけだから、そういう取組みをぜひやっていただきたいと思ったのですけれども、いかがか尋ねました。","respondent":"渋谷指導課長","answer":"２泊３日のイングリッシュキャンプ、グローバル人材育成塾の中でも、品川区のいいところを紹介するようなプログラムを入れているところもあります。小学校１年生から新たに今やっている英語の新カリキュラムでは、例えば、品川区の英語教育の大きな特徴になっているところです。","id":"exchange-073"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"英語を教わるということは、あくまでも子どもが受け身になるので、子どもが主体的に英語を使って何かできると、主体的な取組みというのはすごくモチベーションが高くなると思うので、ぜひいろいろ検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問","question":"中身を伺っていて、どういう方たちがかかわってここまで来たのかというのと、その辺をどのように考えているのかというのが１点。いろいろな接し方があるので、あまり英語ばかりが強調され過ぎているのではないかという思いも持っていますが、いかがか尋ねました。","respondent":"渋谷指導課長、村尾教育総合支援センター長","answer":"どのような検討をというのは、冒頭ご説明申し上げましたが、それぞれ部会に分かれて検討してまいったところです。それから、３点目のグローバル化の対応については、これもご指摘のとおりで、いろいろな国の方がいます。区では３学期、東京都と連携を図りながら、品川区のオリンピック・パラリンピック教育というものを進めていく予定になっています。","id":"exchange-075"},{"speaker":"高橋（し）委員","kind":"質問","question":"４ページの品川版コミュニティ・スクールの概要の図が出ているのでわかりやすいのですが、「何でしょうか、それ」というところがあるのです。そういったところの連携については、教育委員会もそうなのですけれども、他の所管の方たちはどう感じているかというのを伺いたいところはあります。","respondent":"渋谷指導課長","answer":"基本的には社会教育を所管している部署が中心になって担っているという実態もあろうかというふうに思います。今までの縦割りだけではなくて、教育委員会だけでなく、区長部局との連携というのは最重要テーマだというふうに考えているところであります。","id":"exchange-076"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、そういった方が連携をとるというのは、話し合いの場ができるのか尋ねました。","respondent":"渋谷指導課長","answer":"学校ごとにしっかりとした基盤をつくっていただくということが第一だというふうに思っています。関係各課の方との連携のあり方だとか、また、そういった様子を連絡調整するような場をぜひつくって進めていきたいというふうに考えております。","id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462438?Template=document&Id=4874#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":69984,"voices":206}},{"id":"h28-20160119-5","meetingId":"h28-cm01","date":"2016年1月19日","dateIso":"2016-01-19","committee":"総務委員会","time":"午後 １時００分～午後 ２時５６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"時間別というのでしょうか、どういう動きをしたのか、もう少しタイムスケジュールをご説明いただきたい。","respondent":"江部危機管理室長","answer":"品川警察署とは既に連絡がとれておりましたので、そういう対応をし、朝の段階で方針を決めようというふうに判断したところです。１０時ぐらいですか、方針といたしましては、不審者かいないかどうかを全体的に調査をかけてくださいということをお願いされたところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"もちろん会派としてお話は伺ってはいるのですけれども、どういう考え方で動いているのか、お考えをご説明ください。","respondent":"江部危機管理室長","answer":"それは書類を、時間がありませんので、実際は話し合いで決めていくという流れです。総務委員会でも報告しなければということなので、先ほど会派を回らせていただいて、今日、総務委員会で報告させていただいているという流れです。","id":"exchange-002"}]},{"id":"topic-02","title":"品川区総合戦略の策定","agenda":"品川区総合戦略の策定","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"策定委員会の中でどういった議論や到達があったのか伺いたいのと、この計画自体は５年間ということですけれども、そこを伺いたいと思います。いつの経営会議で確認するのか、どんな会議で確認をするのか、そこの今後の予定についても伺いたいと思います。","respondent":"柏原企画調整課長","answer":"３月末には発表といいますか、遅くとも２月ぐらいには確定ができて、そのぐらいのタイミングでできればというふうに思ってあります。先ほど申しましたように、いろいろ手続き等もありますので、２月ぐらいまでには決定というようなスケジュール感で動いているものです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"まず１点、今回も３人の方の提出という点では、その点を改めて伺いたいと思います。その仕組みや中身ももっぱら住民同士の助け合いを強調している点は改めるべきだと思うのですけれども、全体を通じてまずそこを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"さらに、これを実施していくところでのＰＤＣＡといいますか、まずはそこに今回この総合戦略については力点を置いているといったところです。総合実施計画ということで、これはトータルで５年間、それから３年間といったところの進め方をしているものです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ経済的負担の軽減は重点課題として私は加えるべきだと思うのですけれども、その点を伺いたいと思います。やはり区の責任で支援の仕組みをつくることの位置づけが私は足りないと思うのですけれども、この点もいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"進めていく中で、それはこの総合戦略の目的を進める上で、そういった見直しの中でも見ながらです。触れている事業は、まずは基本的に進めていくことが考え方だろうと思ってありますし、それから支援の仕組みを住民の方と一緒にというところは。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"そういう位置づけはやっぱり集中してやっていくべきことではないかと思うのですけれども、その点を伺いたいと思います。参加者を増やすだけという目標では、戦略としては位置づけが乏しいと思うのですけれども、最後にいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"長期計画、それから総合実施計画等々でこれは着実にやっていくといったところがありますので、ここは切り離したといったところです。アウトプットという考え方でこれをいくのか、２つの数値目標の捉え方がありまして、これは議論があるところであります。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"予算の関係上というお話がありましたが、であれば、やはり第１回定例会を踏まえて意思決定をされるというのが筋ではないのかなというふうに思います。いずれにしても、切実な区民要望、様々な意見を取り入れてほしいと求めましたので、修正、改善、充実を要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問","question":"簡潔に１つお聞きします。１つ１つについては伺いませんけれども、素朴にどうなのかなと思って、それだけ説明を求めました。","respondent":"柏原企画調整課長","answer":"区の今の考え方ということで、そういったところで出ているご意見等々を踏まえながら現段階での考え方ということでまとめたということで、所管とも調整した上での中身です。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"これをもう１つの支えるものにしていこうというようなことは、ここに落とし込まれていくというような形になるのかなというふうにも感じておりました。あるいは、関わり方になっていくのか、何かその辺の整理等をされておられますか尋ねました。","respondent":"柏原企画調整課長","answer":"今、総合実施計画のところでも議論をしていてというところからこちらのほうへ持ってきているといったところでありますので。基本的な捉え方といいますか、考え方はそういう考え方でこの戦略については動かしていくものです。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"パブリックコメントを求めて出していただく以上、それがどう反映されたかということが必要になっていくのではないかと思うのですが、どういうふうになっていくのか尋ねました。","respondent":"柏原企画調整課長","answer":"施策の中で参考にさせていただいたりとかといったところと、区分けがやっぱりどうしても中身によっては出てくるといったところです。ゆくゆくは、書類としましてはもう少し整理いたしますけれども、これを想定する形でお知らせしていきたいというふうに思います。","id":"exchange-010"},{"speaker":"吉田委員","kind":"意見","question":"パブリックコメントということに対してどう評価するかという、なかなかパブリックコメント、ちょっと感じることがあるのです。もし何かコメントしていただけるならとの意見を述べました。","respondent":"柏原企画調整課長","answer":"ホームページのアクセス数は非常に多かったというところを考えると、なんだろうというところにはしてもらっているのだとは思うのです。ですので、その先にどううまく伝わるかというのは、それは工夫はさせていただきたいと考えています。","id":"exchange-011"},{"speaker":"あくつ副委員長","kind":"質問","question":"いわゆるＫＧＩ、それを達成するまでの経過を評価するためのものであるというところが非常にわかりにくいのではないかということを感じています。ＫＰＩとして指標として取り上げるのか、ＫＧＩとして取り上げるのか、そこのところも素案の中では変わってくるのか尋ねました。","respondent":"柏原企画調整課長","answer":"全ての事業、出したものに対してＫＰＩがそれにそぐうかどうかというのは、それは難しいでしょうというのは国も言っております。ものによっては、前回の言い方はありますけれども、ちょっと混在するような形で最終的にはまとまっていくというふうには考えております。","id":"exchange-012"},{"speaker":"あくつ副委員長","kind":"確認","question":"私も質問させてもらったのですけれども、そこまでこだわらなくてもいいですかということを質問しましたら、それはやはり経過を見るものですから。そこのところはしっかり達成をされていくのかどうかという意識を持ってやっていくのかどうか、この２点、確認の部分とその点を説明を求めました。","respondent":"柏原企画調整課長","answer":"どちらにしても、先ほど申しましたように、ＫＰＩとＫＧＩは混在するような形というふうに考えてあります。でも、それに向かって、それが実現できるように施策も充実して頑張っていくという姿勢でこの総合戦略はつくっていくというものです。","id":"exchange-013"}]},{"id":"topic-03","title":"品川区教育大綱の策定","agenda":"品川区教育大綱の策定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"大綱素案の２ページの「しながわ学びの杜」の開設ですか、これは今どういう動きになっているものなのか解説していただきたいのが１つ。教育都市というのはどういう、概念といったらいいのでしょうか、として位置づけているのか、そこのお考えを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"いろいろな部分で地域の方とも事業を進めたいといったところがあるというふうには認識してございまして、こういったご意見をいただく中で。一定の成果も上げてきているというふうな認識です。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて伺いたいのですけれども、私はこれは統廃合を区長部局が教育委員会に求めるものだと思うので、改めてこれは一体何を考えていることなのか。私はやはりこの議論は学校統廃合につながっていく議論だと思うので、削除すべきだと今でも思っておりますけれども、この点だけ伺いたいと思います。","respondent":"柏原企画調整課長","answer":"今、いろいろなそういったハード的なところのことを考えたときに、学校改築等々につきまして検討していかなければいけないのだということです。ですので、就学人口の動向を見据えながら、老朽化する建物にどう対応していくのだといったところが一番の基本となるといったものです。","id":"exchange-015"},{"speaker":"あべ委員","kind":"確認","question":"それとも、当該の方にその部分をご説明とかという中で、このままこれそのものをお送りするような形になるのか、確認させてください。前も別の科目で聞いたような気がするのですけれども、改めてお伺いします。","respondent":"柏原企画調整課長","answer":"いろいろなことでパブリックコメントを行っている手法と同じ手法でございまして、もう少し中身は整理をいたしますけれども、これを直接お返しするということではなくて、この中身をつくったものを一般的に公表して、それをご覧いただくという形で捉えております。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"視点として、行政や社会が子どもをどうしたいとか、子どもが学ぶ主体であるという目線のものもどこか基本理念だか何かに少しは入っていてほしいと。それをどのようにお考えになっているか伺えればと思います。","respondent":"柏原企画調整課長","answer":"いろいろご意見をいただきながら、少し整理といいますか、考え方をきちんと整理しようという段階です。ですので、表現の仕方は今おっしゃったとおりになるかどうかはあれですけれども、ここは今、議論をしているといった状況です。","id":"exchange-017"},{"speaker":"あべ委員","kind":"意見","question":"そこがだんだん意識から薄くなっていってしまっては困るなという、そのような危機感と言ったら言い過ぎですけれども、ちょっと不安があってですね。でも、そのような視点からさらに議論を深めていっていただけるということですので、そちらに期待したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"質問","question":"２１番は学校教育の充実にカウントされているということですから、質問の趣旨は、これをつくられた方はわかっていらっしゃる。それとも、それはやっぱりもう、そこはあまり必要ないのですというお考えなのかどうか、そこのところを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"１つは、考え方としては、学校教育という１つの大きな軸の中で捉えていこうということがあります。それは認識はしているところでありますので、一定程度、その点についてはもう少ししなくてはいけないだろうというような感じを持ってあります。","id":"exchange-019"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"学校教育の充実というところに本当に１項目入れていただきたいぐらいの思いではあるのですけれども、そういったところもぜひ入れていただきたいというふうに、これは要望ですけれどもお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"どういうふうに反映されていくのかということで、こういうふうに反映されていきますみたいなことは、コメントを寄せられた方にいくのでしょうか。基本的な質問にどんどんなってしまうかもしれないのですけれども、私、知識としてないので教えていただけますか。","respondent":"柏原企画調整課長","answer":"これはまだ正直申し上げまして、まだ意見への対応の欄につきましては、文章の練りをやっていきたいと思っています。こういった形で１つの意見に対してこういうふうな考えを持つということを、そういったところで公表をしていくということで考えております。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"どういうふうに反映されたかということがコメントを寄せた人に対しては、その回答こそが求められるのではないかというふうに思います。全体の中でどういうふうに運営されていくのかということについて、難しいかもしれないですけれども、コメントをいただければと思うのですが。","respondent":"柏原企画調整課長","answer":"こういう区の考えを持っていますということで、それがまず１つ、意見をいただくところに対しての返しということでの関係性になるのだと思います。","id":"exchange-022"},{"speaker":"吉田委員","kind":"意見","question":"自分が意見を出しても、ここで精査していただいて、さらに次にまた区政への参加ということにつながるような対応をしていただけたらいいかと思います。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"大沢委員","kind":"質問","question":"簡単に伺いますけれども、パブコメですから広く意見ということで拒むものではない、品川の教育の根幹の内部にいた方たちのご意見が寄せられた。どういう取扱い、そこのところをどういうふうにお考えになって取り扱う、そこのところはどういうふうに捉えられていらっしゃるのか説明を求めました。","respondent":"柏原企画調整課長","answer":"中身をご覧いただきますと、そういった形で内部の方といいますか、というところのご意見もあるということは認識はしています。あくまでこれは意見をいただくという１つの手法、場面でありますので、パブリックコメントという意味で言えばないというふうに考えているものです。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"これを読んだ方は、そうなのだ、そうなのだと思う方が結構いる部分もある。そこらの表現を工夫をしないと、何か混乱が生じてしまうのではないかと思うのですけれども、そこのところはどうか尋ねました。","respondent":"柏原企画調整課長","answer":"それに耐え得るようなといいますか、誤解のないような形での表現といいますか、出し方はしていきたいと思ってあります。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろ総合教育会議の中でも議論があったということがありましたけれども、そこを改めて伺いたいのが１つです。やっぱりそうは言っても、子どものためになってほしいというふうに願いますので、意見と質問をさせてほしいと求めました。","respondent":"中山企画部長","answer":"いろいろな切り口で書かなければいけない部分が、今日のようなご意見を踏まえて、最終の場面で修正なり工夫できるものは考えていきたいと思います。","id":"exchange-026"}]},{"id":"topic-04","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"放棄の根拠が５号になっているということは、特段、時間があまりに経って回収ができそうにないので放棄するというふうになるのですね。状況がどういう感じなのか教えてほしいと求めました。","respondent":"福島会計管理者","answer":"４月に学童保育に入会したということなのですが、それがうまく伝わらずに、１年間あったということで督促をしていました。本人もほかの区に引っ越したりとかそういう事情もありましたので、今回、このような形をとらせていただきました。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"私は、この障害者福祉手当は、これ、返還する分なのですね。参考までに、どういうもので、どう返還すべきだったのかを説明を求めました。","respondent":"福島会計管理者","answer":"それがわかったのが平成２２年の秋頃でして、わかったと同時に、本人がもう死亡しているということもまたわかりました。相続人ということで、名前も変わっていて住所もわからないというところで、もう取り立てることはできないだろうというふうに判断したものです。","id":"exchange-028"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"この変更に伴って何か区に負担が発生するとか、そういうことがないのか。一応、変更なので、そこだけ確認させてください。","respondent":"提坂人権啓発課長","answer":"若干使いづらい面がありますけれども、区民の方の浸水被害ですとか水質改善のために、その辺は全面的に協力したいと思います。行政財産使用許可を出していますけれども、その期間が終了するということもありますので、その辺は延長でまた使用許可を出すということもあります。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"２年半長くなる、たしかプレハブづくりで、一般の建物に比べると非常に不具合もあるかと考えています。やはり２年半延びるとなると、何か対策のようなものも一定必要ではないかと思うのですけれども、その辺の対応はいかがなのか尋ねました。","respondent":"提坂人権啓発課長","answer":"私も約３年間、２年半、何とか乗り切っていきたいとは考えております。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問・要望","question":"確認なのですが、その際の対策というのは、都のほうに要望を出して、都でやっていただくということでよろしいのか尋ねました。","respondent":"提坂人権啓発課長","answer":"ただいま、都のほうとも調整しています。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問","question":"どうなのでしょう、別の遊び場みたいなものを用意したほうがいいのではないかと思って、そういった考え方はないのでしょうか。工事の反対側のほうです。","respondent":"提坂人権啓発課長","answer":"工事関連の詳細については当方では把握していないのですけれども、立会川沿いの町会の方ですとか、現在の仮移転先の町会の皆様に対して、東京都がその辺を丁寧に説明していくとは聞いてあります。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701406?Template=document&Id=2036#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":39666,"voices":91}},{"id":"h28-20160120-14","meetingId":"h28-cm01","date":"2016年1月20日","dateIso":"2016-01-20","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時１３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査の(1)国家戦略特区に関すること","agenda":"特定事件調査の(1)国家戦略特区に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"最初はまず区にお伺いしたいのですけれども、改めて区としてはこの介護・保育の人材不足の現状をどのように考えているでしょうか。保育士もほぼ同様の１０万円低いということになっていまして、私はこういった低い現状というのは、区としてはどのようにこの現状をお考えか尋ねました。","respondent":"柏原企画調整課長","answer":"福祉の現場、それから保育等の現場において、人材を確保するのが難しくなっているという状況が現実としてあるというのは認識しています。賃金等の関係も、幾つかの要因が重なる中での人材が不足しているといったところが言えるのではないかと考えています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは資料の中にありますけれども、現状をお伺いしたいと思っていまして、どのような場所や時間帯などでこういった見直しがあるのか。品川区内での現状というのは、この見直しの現状というのは何かあるのかということをお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"やはり道路管理者、警視庁等々と協議、交通公安の部分との協議が必要だろうというところは思ってあります。それ以外の部分でも、これは他の区の現況ですけれども、そういったところも見据えながらということにはなってこようかと思います。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"ですから、例えば業種などになるのでしょうか、やはり一定の改善が必要なのかなという思いがしております。これは全て意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"提案","question":"ただし、これも各自治体が条例で基準を定めているわけですから、甚だちょっと疑問だということです。この確認と、それからいつぐらいにこの方向が見えるかということについて、品川区の現状のお考えを説明を求めました。","respondent":"柏原企画調整課長","answer":"現在も国会の審議中ということで聞いてございまして、まだこの案件については進んでいないと認識しています。それから品川区としても施策を進めていく上で、法が通った際には、どういう形で使えるかというのは十分検証・検討するべきことだと思ってあります。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それこそ国会で多分法案が提出されて議論されていくのでしょうから、こちらの当委員会として出すのは非常に難しいのではないかという気がします。繰り返しますけれども、もちろん私たち自民党のところにも多くの要望が来ています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"最初に１番から６番までは国家戦略特区で、最終的にこの行財政改革特別委員会として提案・提言をしていくということです。７番から１４番はまだそれほどやっていないので、これを提案したときには、その中で安藤委員みたいに終の住みかだからというのもあってもいいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"中塚委員長","kind":"確認","question":"私から一言。次回しっかり確認をして進めていきたいということは思いますけれども、見えないもの、よろしくお願いしますということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問・要望","question":"こういうことがあって、この緩和については東京都の公安委員会になるのでしょうか、そのようなことは検討してもいいのではないでしょうか。そういう話をちょっとそのようなところに落としたレベルで対応すべきなのかなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今の枠組みの中でそこへの具体的な要望等で対応できるものもあるような感じなので、結論から言いますと、そこに含んでもらえばいいのかなと。個室もあるし多床室もということで、あえて言うならば７番から１４番を意見として、何かどこかに挙げなくてもいいのではないかと個人的には思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"そうしないと、この待機児童対策の賃貸ビルの空き室を借りられないという要望があったので、ここに挙げてもらったというのが一つです。この１２番は文言を変えれば、上の６番とか７番に入るという理解なのだけれども、その理解でもし違ったらそこは説明を求めました。","respondent":"柏原企画調整課長","answer":"今、不定期航路をやるにしても具体的にどことどこを結ぶとか、そういうところも具体的な提案ができないと難しいだろうという議論まで今来ております。","id":"exchange-010"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"それは長くしたい気は確かにわかるけれども、それは１０年、２０年の中で償却できていくというようなことは訴えていければいいのかなと。これはこういう案になっているということなので、もしご理解があればありがたいというのが、一つの考え方ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"こういうことを緩和するとなると、今までこのとおりにつくってきた方々に対して不利益が生じる可能性が当然出てくるわけですね。しかも、これは例外的に建替えが認められているという表現になっているのですけれども、聞いて大丈夫ですかね、どのような例外があるのか尋ねました。","respondent":"柏原企画調整課長","answer":"それは現地の確認とかいろいろする中で判断をするとか、そういった個別の状況を見ながらを例外的に認めていると。こういう例外ですというのがかっちりしたもので条文化されたものではないのですけれども、そういう現場の状況を見ながらとは聞いているところです。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問","question":"そうするとこれも同じような可能性が、もしかしたら出てくる可能性があるわけじゃないですか。恐らくは円滑なのではないかと思って、結果としてこの１１番は国家戦略特区にそぐわないのではないかということを意見としてお話をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"商店街のアーケードの更新なのですけれども、商店街に来る人にとっては、安心して歩くためにもアーケードというのは重要だと考えています。やはり守っていくためにやっていくべきではないかと思っているのですが、区の現状の考えを教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"それから災害への対応だとか、やはりそういったインフラという意味でたくさんの人が集まるところですから、クリアしなくてはいけない。商店街全体の考え方で、何かしらの支援というのは区としても考えられるのではないかと思いますが、ちょっと大きな答弁になってしまいました。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"これをどう維持していくのか、これは意見として、やってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"いろいろお話も伺う中で、先ほどお話があった１２番は、これはぜひ進めていってほしいと求めました。今お話を伺ったりもしましたが、この７番、１２番というところでいいのかなという意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"ですから、私は現行のルールをさらに緩めるというのは、やはり問題があるという意見です。あるいは社会福祉法人などがそういった基準にかなう施設をつくるときに、やはり必要な支援こそ、やはり私は行うべきではないかという意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"現行の児童福祉法ではどうしても難しいというものについて、区としてどのようにお感じになっているのかというところをお伺いできたらと思います。ただ、そういった視点、どういった現状があるのかというところを区として把握されているのかをお聞かせいいただけたらと思います。","respondent":"柏原企画調整課長","answer":"そこが認可するために、直接的にその国家戦略特区でそれがクリアできるかというと、ちょっと難しい面があると思われます。東京都と話す中ではそういう考え方はあるのだというのは伝えていきたいと思いますけれども、現状はなかなか高いハードルだというところです。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"現状をお知らせいただきまして、ありがとうあります。今後、実際ある施設をどう活用できるかといった方策につきましても、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"たけうち委員","kind":"確認","question":"今のところでちょっとわからないところがあるのですけれども確認で、そこでどうなるかはわからないけれども、という考えなのかというのが一つと。それは蹴上げがどうなっているのか、所管ではないので、わかればなのですけれども。","respondent":"柏原企画調整課長","answer":"ちょっと認可保育園のところの考え方がなかなか難しいものがあるのですけれども、大きなところで一定の基準をクリアしなくてはいけないと法律で言う。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"意見","question":"やるとすれば、ある程度東京都の理解をいただいた上で国家戦略特区のほうに挙げてやらないと、あとは法律改正しかないということですね。わかりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"}]},{"id":"topic-02","title":"基金に関すること","agenda":"基金に関すること","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"やむを得ず起債をしてしまったものの負の遺産みたいなものを償還しているという類のものではないのかどうかというところの確認と、その債券の中で政策を実行していくのだという考え方のもとで今ある残高なのかということの確認を、お伺いしたいと思います。","respondent":"秋山財政課長","answer":"減債基金の元となる起債という考え方ですけれども、起債についてはいろいろな考え方があります。そういうものの平準化をしたものについても、十分な返済のものを持つという意味で、この減債基金を積み立てると考えているものです。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問・要望","question":"一応、年度当初ではないのですけれども、改めて確認のために質問させていただきました。これの使い方をどうするのだという中で、予算特別委員会だったか決算特別委員会だったか、ちょっとそのようなことも伺った記憶が若干あるのです。","respondent":"秋山財政課長","answer":"今すぐそれを、基金としての残高がありますので使うというのは、なかなかちょっと難しいのかなという認識です。今回新しいものを、今、検討を進めている最中です。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問・要望","question":"地域振興基金は、やはり本来の目的のままというお話だったかと思いますので、それは理解をいたしました。一つだけ要望的なことを言わせていただくと、なるべくオリンピック後も考えたような、そこだけ要望させていただいて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"沢田委員","kind":"質問・要望","question":"ちょっとわからないことがあるので教えていただきたいのですけれども、ちょっともう一回確認したいのですけれども、そのあたりのところを説明を求めました。","respondent":"秋山財政課長","answer":"それから公共施設整備基金につきましては、この１０年間の改築の想定をして、先ほどm2数に単価ということで、およそ３５０億円程度を目標と。それから義務教育施設整備基金も同じように、学校改築が１０校程度ということで、３００億円程度というような目標を立てております。","id":"exchange-025"},{"speaker":"沢田委員","kind":"意見","question":"これは予算書などを見ればわかることなのかもしれないですけれども、どの程度取崩しをしたときがあったのか、近年そういうことがあったのかという点をお聞かせほしいと求めました。","respondent":"秋山財政課長","answer":"ただ、だからといって、歳出のほうは継続性がありますので、そこまで落とすことはもちろんできません。一つはその基金を用いて、行政の区民の福祉のための業務が継続されていくという考えで、今いるです。","id":"exchange-026"},{"speaker":"沢田委員","kind":"質問","question":"その年、リーマンショックは今からもう６年前ですか、その年に取り崩したということでよろしいですか。その辺のところのこの財政調整基金が取り崩されたときというのはいつなのか。","respondent":"中山企画部長","answer":"１８年と、この辺は４５７億円、４２５億円というように落ちてきているわけですね。ちょっと内訳の金額は今確認しておりますけれども、当然こういうときには充当していったと、取崩し型基金を取り崩していって対応したです。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問・要望","question":"そうするとその１９０億円という目標は、どういう形のことを想定されて立てられているのか、お聞かせいただきたいです。","respondent":"中山企画部長、秋山財政課長","answer":"例えば平成２０年以降でも、いわゆる特定目的基金が７４０億、７５０億円ほどあったものが平成２２年度までには６８０億円。このように考えているものだということでご理解いただきたいと考えています。その１割を２年分持っていれば、その２年分ぐらいを積み立てておけば、その２年間の間は景気の低迷した分を財政調整基金で補うことができる。","id":"exchange-028"},{"speaker":"横山委員","kind":"意見","question":"こちらの２番の基金の設置と財源についての(3)で想定される政策等にオリンピック・パラリンピック、スポーツ振興、施設建設などとあるのですけれども、今挙げられているこの３点以外にどのようなものを想定していらっしゃるのかお聞かせいただけたらと思いますとの意見を述べました。","respondent":"秋山財政課長","answer":"一般的にこういうことが考えられるということで出させていただいたもので、それぞれかなりいろいろなものが想定はされていると。ただし、現時点でのトピック的なものとして挙げられるとすれば、このようなものが挙げられるということで、今回出させていただいたというところです。","id":"exchange-029"},{"speaker":"横山委員","kind":"質問","question":"景気が悪くなったときに大体回復に２年くらいはかかるということで、子育て支援は今、緩めるわけにはいかない品川区の大事な政策かと思います。そうした点については、現在はどのような考えか尋ねました。","respondent":"秋山財政課長","answer":"２年かかるというのは、確かに子育て世帯の収入の減というのが問題になってくるということは当然考えられることだとは思っております。そういう経済が落ちて減収になったとしても、そういうものを継続的に進めていくというところがひとつ重要なものだと考えております。","id":"exchange-030"},{"speaker":"伊藤委員","kind":"質問","question":"見えることは見えるのですけれども、いろいろなものをあちこちから照らし合わせて見ないとわからないところがあるわけじゃないですか。ちょっと今日の基金についての内容とは変わってくるのだけれども、ぜひいい機会ですから、お考えを説明を求めました。","respondent":"秋山財政課長","answer":"例えば公共施設であれば、特別養護老人ホームであるとか幼保一体施設であるとかというのがそれぞれに書かれているということもあります。","id":"exchange-031"},{"speaker":"伊藤委員","kind":"質問","question":"それから、公共施設有効活用プランとの連携も、これも基金と相当絡んでくるわけじゃないですか。けれども、経年的な変化については、こちらが勉強して資料を探していかないと見当たらないわけじゃないか尋ねました。","respondent":"秋山財政課長","answer":"充当先の内容につきましてもご要望ですので、今後ともわかりやすくということも含めて、出していくような形で検討はさせていただきたいとは思ってあります。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"資料の具体的なところからまずお伺いしたいのですけれども、積立原資ということで４つの箇所に出ていますが、具体的には何を指しているのか。一般区民税なのか財政調整交付金なのかということもお伺いしますし、そこら辺の違いもお伺いしたいと思います。","respondent":"秋山財政課長","answer":"財政調整基金の積立原資と公共施設整備基金の「等」ですけれども、「税等」と書いてあるのは、歳入のほうのその他の財調等のことです。この「税」と書いてあるのは区民税です。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"例えば保育園あるいは児童センター、図書館などは含まれるのかどうか伺います、これが２点目です。３点目は、義務教育施設整備基金のほうでも同様に「今後１０年間で１０校程度の改築を想定し積立」とありますけれども、伺いたいと思います。","respondent":"秋山財政課長","answer":"ですからその増収分何割を積み立てるということではなくて、結果として増収分がこちらに入ってきていると考えていただければよろしいかと思います。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"伺ったのは数で考えているということでしたけれども、保育園、児童センターや図書館が含まれるのかどうかというのをお伺いしたいので。ですから、これはちょっと口頭で聞いてもあれかもしれないですけれども、わかる範囲でいいのですが教えてほしいと求めました。","respondent":"秋山財政課長","answer":"最初の公共施設整備基金ですけれども、公共施設整備基金は学校以外の公共施設ですので、全部入ります。平成２６年度の積立が９億５,０００万円ほどですので、それは毎年の予算書には積立額が出ておりますので、その分が入っているです。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"これ以上積み立てる必要ないのではないかと思うのですけれども、この財政の健全な運営を図るためというのはどのような意味なのかお伺いしたい。やはり取り崩すという想定はほとんどないということなのか、ちょっとそこら辺がよくわからなかったので、お伺いしたいと思います。","respondent":"秋山財政課長","answer":"国で言えば指標がいろいろありますので、それらの指標を満たしているというのが一つ健全財政とはというお答えになるのかなとは思います。ですので、財政調整基金を使っていないから、ずっと基金を使わないのかということではないかと考えています。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"出を減らし、そうした他区の基金との関係の中で、今私が言ったような捉え方についての何か見解があればお伺いしたいというのが１点です。もう一つ、必要な施策であれば、あえて基金にするという品川区の今の考え方というのはどうなのかというのも合わせてお伺いします。","respondent":"秋山財政課長","answer":"これはもう何度もご説明しますけれども家計と一緒でありまして、すべからく皆さんがそうやっていくべきであるし、自治体としても同じであると。今回、第１回定例会に提出を予定しているものにつきましても同じような考えでやっているです。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"目の前で今大変求められているサービスにきちんと税収を使うということを優先しないと、やはり理解を得られないのではないかなと。あえて基金にするというお考えということですけれども、具体的には施設整備の充実などにつながっていくのかどうかお伺いしたいと思います。","respondent":"中塚委員長、秋山財政課長","answer":"条例はこれから出るということで、ただ一般的な特定財源としての基金について一つの考える視点でもあるかなと思いますので、その辺をよろしくお願いします。その中で積立て、決して何か恣意的に歳出を下げて基金を区が積み立てているというようなことでは決してないということを申し上げたいと思います。","id":"exchange-038"},{"speaker":"たけうち委員","kind":"質問・要望","question":"少し考え方を教えていただきたいのですけれども、いろいろな家計に例えてやりますよね、品川区の予算の場合は食費はないですけれども。そういう、どう考えればいいかというのを説明を求めました。","respondent":"秋山財政課長","answer":"それから国民健康保険と後期高齢者医療保険と介護保険と足しますと、そうですね、２,３００億円とかその辺の金額になろうかと思います。その８００億円がどうかというよりも、結果としてこのぐらいがあれば望ましいという形で数字を出させていただいたと考えているものです。","id":"exchange-039"},{"speaker":"たけうち委員","kind":"質問・要望","question":"何かわかりやすいものをやはりつくってもらえると非常にいいかなというのが、これと直接関係ないのですけれども、要望です。共産党の安藤委員のほうからいろいろお話が出て、保育園とかは確かに大事なのだけれども、それで毎年つくっているじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"安藤委員","kind":"意見","question":"そこにやはり地方自治体の使命としてどうそこに応えていくかといいますか、どこにやらなくてはいけない仕事があるのかというのをきちんと正面から見た上で、必要な財政措置をしていくというのが私は基本だと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"たけうち委員","kind":"意見","question":"それをじゃあ品川区が何十億円かけて買って、恐らくそうではないと思うんですよ、共産党さんはそこまでの極論を言っているのではないと思うのですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"２位が港区で４８万円。やはり１人あたりで見ると多いと思うのですけれども、これを多いと思っているかどうか、品川区にお伺いしたいと思います。","respondent":"秋山財政課長","answer":"基金の各区の考え方というのはそれぞれあるかと思います。基金をこれだけ持っていれば行政の継続性が担保されるということで考えて、特に私どもでは考えたことがないというのが現状です。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり税が増えた分は、区の自治体としての責務だと思いますので、そういった方向に使っていくべきだと思います。そういったところに増収分のところは使っていってほしいと求めましたが、そこのお考えを説明を求めました。","respondent":"秋山財政課長","answer":"増収分を施策に使っていくというのは、当然考えることだとは思っています。そういう税収の変動についても対応をとるために基金というものを積み立てて、今、運用しているというところでご理解いただければと思います。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"減収もあるということで、その減収になったときにワクチン等はやめられないというお話ですけれども、一つのことをやるのにそれほどお金が、１００億円とかかかるわけではないので、やはりそういったことにはしっかり使っていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"伊藤委員","kind":"提案","question":"改めてやはりお願いしたいのは、それから入る子どもたちの定員も含めて、それを具体的に提案していかないといけないのではないでしょうか。紹介議員としてやった以上は、それはこの財源も含めてぜひどこかの部分で提案していただきたいと思うのですが、いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"４月の時点で待機児をゼロにするというためには、２０園の保育園の増設が必要だということも言っております。ただ、それは入れる状況をつくるというのが、私は議会の本当に努力をしていかなくてはいけないという点で紹介議員としてサインをしたわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"伊藤委員","kind":"質問","question":"けれども、万万が一大きな震災が起こったときどうするのですか。あるいはほかの様々な行政上の緊急の目的が出てきたときに、どうするのですかということについても考えなくてはいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"松永委員","kind":"確認","question":"ちょっと間違えていたら申し訳ございません、先ほど公共施設整備基金のところで、新築、改築、大規模改修と言われたような気がしたのですけれども、義務教育施設整備基金のほうでは新築というのはなかったのですが、その確認だけお願いします。","respondent":"秋山財政課長","answer":"聞き間違いではないのですが、私も冒頭お話しさせていただいたのは、公共施設の場合は、今後有効活用プランとかいろいろなプランを今後検討していく中で、新築が全くないということではないのかなということで、お話をさせていただいたです。","id":"exchange-049"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと教えていただきたいのですが、取り崩されているのかという数字がわかればちょっと教えていただきたいのと、わかれば教えていただきたいです。これ、１校大体前回の決算だと３０億円だか２０億円だかかかるという部分で、大丈夫なのかなというところの確認をさせてください。","respondent":"秋山財政課長","answer":"今後１０年間で耐用年数等を考えていくとこれぐらいが必要になるだろうということで、決して今の現状でＡ学校が何年、ご理解いただければと思います。","id":"exchange-050"},{"speaker":"大倉委員","kind":"質問","question":"１０年でどこがというより想定だというところで、１校二、その辺についてちょっとお考えを教えてほしいと求めました。","respondent":"秋山財政課長","answer":"これは想定として考えているだけであって、これで１００％改築が全部行きますよというものではないので、金額を考えているというふうにご理解いただければと思います。","id":"exchange-051"},{"speaker":"大倉委員","kind":"意見","question":"そういった中でも本当にちゃんと１０年間で想定をしながら、ちょっとがっと３００億円を目標としていて、最後何かあればお願いしますとの意見を述べました。","respondent":"中山企画部長","answer":"基金の望ましい額の考え方という中での積算においては、個別具体の学校の想定はこの中にしていないという説明をしております。そのことと、具体的にどこの学校も積み上げて基金が出しているものではないという説明が、そういうきちんとした改築計画というものはそれとしてある。","id":"exchange-052"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"基金のことなので、考え方をお伺いします。そこに耐震補強工事をやったから１５年で、企画財政部門で出してくるのか、そこら辺をちょっと教えてほしい。","respondent":"秋山財政課長","answer":"その辺は今後どういう形になるのかということも含めて、ちょっと検討していかなければいけないかなと考えています。それから、それとは今回の基金の積立てという形の考え方とはちょっと違って、財政側で考えている数字だとご理解いただきたいと思います。","id":"exchange-053"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"私が質問するかどうかは別としても、予算特別委員会なり何なりどこかで私はやるべきだと思っていて、起債残高というのを持っていれば安全だろうと。なおかつその目安が、今伺うと残高では、この平準化から言うとあまりにひどすぎるのではないかと思っているというのだけ言っておきます。","respondent":"中山企画部長","answer":"本格的な議論をしているわけではありませんが、今後そういうことも含めた議論をさせていただきたいと思います。どうしても大きな視点で備えていくという部分と、ご指摘のことを踏まえてしっかり備えた対応はできるようにしてまいりたいと思います。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858443?Template=document&Id=6000#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":40312,"voices":103}},{"id":"h28-20160121-18","meetingId":"h28-cm01","date":"2016年1月21日","dateIso":"2016-01-21","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時１５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"この説明でも、「メンバーの拡充を図り」となっていて、今後の目標値みたいなものはあるのでしょうか。知らなければきっかけもできないですから。","respondent":"小川オリンピック・パラリンピック準備課長、伊崎子ども育成課長","answer":"ちなみに７万人、８万人というところの、１つの目標ができ上がったのではないかと推測しております。お答えするとすれば、おそらく語学力ですとか… この役立ち隊というのは、できれば行政主導ではなく、子どもたちの活動を行政が支援する形で継続していければいいと考えているところです。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"質問の仕方が難しいのですが。だから、そういうやりとりを強く申し入れしてもいいのではないかなと感じたので、その辺のお考えを聞かせてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長、河内協働・国際担当課長","answer":"いろいろ歯がゆい思いをしながら考えているところではありますが、東京都なり、大会組織委員会にも働きかけてまいりたいと思います。 先ほどの把握の件につきまして、ちょっと補足の説明をさせていただきたいと考えています。それぞれの事業に活かしていきながら、無事にオリンピック・パラリンピックを迎えるべく、そういったところの計画をしています。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２枚めくって、もう１つ外国人おもてなし語学ボランティア、どちらも東京都の登録になるというようなご説明だったと思うのですけれども。同じ東京都との関係で、どういうふうなくくりになっているのか説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長、河内協働・国際担当課長","answer":"やはり３万５,０００人という人数が確保できないということで、２３区並びに東京都内の市区町村のほうに、協力の依頼がございました。東京都がやっているものも、品川区がかかわっているものも… 東京都に昨年末、確認したところなのですが、おおむね１万５,０００人程度の見込みであるというようなところが、言われたところです。この２時間半、３時間半の間で、定員の限りがあります。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"で、区に協力を求められて、港区と品川区で先行されてやられたということで。何かこの大学連携について情報があれば、説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"確認したところによりますと、区内の立正大学や清泉女子大学といったところは、そういった連携に入っているというものを確認しています。そういったことで、区内の大学も、きちっとそれぞれの考え方を持って動いているというような情報は得ているところです。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはり８万人を確保するには、この大学連携がどうしても必要だということが、情報収集していただいて。ボランティアというところからちょっと拡大してしまうかもしれませんけれども、こういったこと、何か動きがあれば教えてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"私どもも教育委員会とは連携をしておりまして、長野オリンピックに近いようなものを、具体的に考えてあります。そういうような構想を、具体的に打ち立てて、品川区のほうにも話が来ているということは聞いてあります。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"詳しくは、多分、教育委員会のほうにお話が来ているかと思うのですけれども。ぜひそういったことも、今後の子どもたちが参加することに非常に大きな意義があると思いますので、進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"あくつ委員からも質問ありましたけれども、この講座内容というのは、一緒なのですか。その点。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"全く同じでございまして、東京都のほうからご紹介をいただき、講師を派遣していただいているものです。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"質問させていただいた外国人おもてなし語学ボランティア、４団体ありますけれども、大会のときには図られるのかどうかということと。どこで取りまとめというか、どうやって連携をとるのかというのを、ちょっとお聞きしたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今年度４月１日より、品川区では、区長をトップといたしました、オリンピック・パラリンピックに関する推進本部を設置しています。それぞれの活動については把握をし、全体のコントロールにつきましては、推進本部が役割として担っているところです。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"では、ボランティアもそこの推進本部で統合して、うまく連携して活躍をされることを期待するというわけか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"新たな動きが出てくるかと思われますが、そういったことに確実に対応していくために、推進本部がコントロールをするという意味合いです。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"この平成２７年１２月１２日に行われた、その辺の実績といいますか、そういうことを教えていただきたいのが１点と。３点伺いたいと思います。","respondent":"河内協働・国際担当課長","answer":"今回、１２月に実施した分につきましては、一定の英語力を持った方がいらっしゃったものです。その方たちに共有するとともに、改めて、その後のおもてなし講座の中で紹介してまいりたいというようなところで対応していきたいと考えています。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"やはり、災害のときは、一番意識をしないと、外国の方に対する、逃げるというか、防災のところまで、考えが及ばないと思うのです。こういう講座の中で、やはりその災害時ということも想定する必要があると思うのですけれども、その点については現状ではいかがなのか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"具体的に、大会開催期間中の災害にかかわることにつきましては、今、まさに大会組織委員会のほうで検討をしています。品川区としても、何ができるかということを、できるだけ早目に検討していきたいと考えています。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こういった外国人の方だけとか、あとはオリンピック・パラリンピックに限らず、ボランティアは区内でやられていると思うのですけれども。ボランティアに自主的に参加していくというところでの課題などをどう見られているのか、もし把握されていれば、教えてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"やはり皆さん、そういったお気持ちはあるにしても、なかなか行動は起こせないというところだということだと思います。２０１１年度の実績は、２０２４年度には、環境整備をしていくことが必要ではないかと考えているところです。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"こういった、過去の大会、ロンドンだったり、そういったところでは、やはり、ボランティアの中心というのは、若い世代になってくるのでしょうか。どういった方々が中心に取り組んできたかというのは、わかるか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"例えばリオだと、自分の国よりも外国人のボランティアのほうが多いというような実態もあるというようなことも聞いております。２０２０年の東京オリンピック、それについては、こういったことを地道に続けていくことが重要ではないかと考えているところです。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それがやはり行動に移していけるように、この時間のなさとか余裕のなさをなくしていく環境整備を、ぜひ進めていただきたいというふうに思います。そうしたら、開いていくということに、そういう検討もされているということか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういったボランティアの方が、どこまで力が必要かというようなことにつきましては、もう少し先を見据えて考えてまいりたいと思っているところです。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"大体その辺の、この８万人の中身、どういうふうに考えたらいいのかというのを、ちょっと１つ教えていただきたいのと。この、２８年３月２６日の２回目で終わりではないというふうに思いますので、その辺をちょっと２点目に伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長、河内協働・国際担当課長","answer":"８万人の中身につきましては、具体的な数字が示されているわけではないので、ちょっとなかなかご説明が難しいところではありますが。今まさにオリンピックに向けて検討していますので、そうした中にボランティアが一つあるということで… 現在、７割程度はもう非ネーティブの英語だと言われておりまして、聞き取りにくい英語も多数あるというふうな情報も入っているところです。そういうところをしっかり押さえながら、次年度以降も講座を展開していきたいという考えです。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと全体のところのあれを教えていただければ、ぜひ紹介していただきたいのですけれども。同時に、正副の委員長さんにお願いしたいのは、今、どういうところがあって、どこまで到達されているのか、全体的に。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"区として独自の推進本部を設置をいたしまして、３競技ありますので、３競技をいかに周知していくか。都議会で提供された資料を全てこちらの委員の皆様には知っていただくように努力していますので、ご理解をいただければと考えています。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"ちょっとわからずに、そんな質問をさせていただいたのですけれども、ありがとうございました。ぜひ、今、委員長がそうおっしゃってくださったので、それは本当にうれしく思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"３.１１の災害のときにも、これはぜひやっていただきたいというふうに思う中で、１点だけ。既に品川区としては情報を持っていると思うので、それをどうやって活用していくのかも含めて、受け入れ態勢について説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"例えば、今後、オリンピック・パラリンピックの区のイベントに参加する気がある方は言ってくださいというようなことも問い合わせてあります。ただ、区としては、歯がゆいばかりではなく、実践的にいろいろことで取り組んでいるということはご理解いただきたいと思います。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/158474?Template=document&Id=6486#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":26501,"voices":58}},{"id":"h28-20160122-10","meetingId":"h28-cm01","date":"2016年1月22日","dateIso":"2016-01-22","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"の３、区議会防災訓練の実施結果","agenda":"の３、区議会防災訓練の実施結果","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"議員は、その地域で救助とかで動いて、来られないのではないかということがあると思うのです。ただ、現実を考えたら、ちょっとどうなのかなという疑問点が残りますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"１回目を平成２５年度にやったときに、Ｂ施設で何が起きたというときに、ここの区議会本部に地図がなかったのです。本部員が確認したほうが機能がよくなるのではないかとか課題があったのが、改善された点とかがあれば教えていただきたいのです。","respondent":"原区議会事務局長","answer":"あえて説明しませんでしたけれども、災害があったら、すぐそれを取り出して準備できるというような体制もつくってきてあります。前回の訓練での教訓で、白地図といったもので準備をしておいたというようなところです。","id":"exchange-002"},{"speaker":"塚本委員","kind":"意見","question":"議員アンケートの集計結果のところで、その他でサイレンや防災無線の放送が聞こえないというのが上がっている。ＩＣＴ導入のときに災害発生時を、ＩＣＴを導入するときにも、そこを考えてほしいと求めました。","respondent":"原区議会事務局長","answer":"説明がいろいろと少なくて大変恐縮だったのですけれども、いざというとき、いただきました。それも含めて、何らかの形がとれるかどうか、ちょっと検討をしてみたいというふうなところです。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"なぜ集まることが必要なのかとか、判断できると思うので、そういう機会もぜひ検討をしてほしいと求めました。今後の訓練では、ぜひ、全会派に本部を体験していただくということを積極的にやっていただきたいと切に願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"提案","question":"各会派の代表を本部役員にしていただきたい、あと、議事録の作成をしていただきたいという３点の改善点の提案をしています。要綱そのものについての議論も、ぜひ今後していっていただきたいと切に願っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701951?Template=document&Id=5166#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":13594,"voices":36}},{"id":"h28-20160216-10","meetingId":"h28-cm02","date":"2016年2月16日","dateIso":"2016-02-16","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"平成２８年第１回定例会","agenda":"平成２８年第１回定例会","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"特に陳情第２号については、意見書を出してほしいという内容であるので、いかがでしょうか。皆さんのご意見を伺いたいと思います。","respondent":"大沢議長、渡辺委員長、原区議会事務局長","answer":"なぜ出したかというのは、意見書を求める原理原則に従ってということです。それしか言いようがありません。問いに対して、今お答えをいただいたと思いますが、重なってしまうかと思いますが、今のご意見について、局長。これについてはご確認くださいということなので、当然、事務局が決める中身ではないと理解しています。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"議会運営委員会の意見を求めることが適当と認めるものは、その取扱いを協議するという申し合わせ確認事項の項目もありますので、私は。ぜひ区議会の中で審議してほしいということに対しては、審議するということで、検討することはとても大事なことではないかと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"本多委員","kind":"意見","question":"まさに陳情の議会運営委員会での取扱いをどうするかという投げかけについては、検討をしてほしいという申し入れについてはわかります。できれば、請願にすればよかったのにという思いを持って、議長の判断に従いたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"塚本委員","kind":"提案","question":"申し合わせ確認事項に書いてあるというのが原理原則として、議長のほうから、これは参考送付にすると。それを今この場で議論しましょうという提案をされているのですけれども、議長の判断のとおりで進めていいのではないかという意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"提案","question":"今回、議会運営委員会の中でそういう提案をされたということは一理あると思うのですが、それはそれで。ただ、今この場でどうしよう、こうしようとなると、少し問題があるのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"あべ委員","kind":"意見","question":"どちらも区民の権利であると思っているので、どちらにすべきだったというようなことは、議会としての発言としてはどうかと思います。このことは、多分、否定されないと思うのですが、そのような運用をしてきたということと、どちらが原則かということとは、ちょっと…との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"あべ委員","kind":"意見","question":"今、おっしゃっていただいたそれぞれの会派のご意見の中で、少しあれっと思う部分があったので、その部分を言わせていただきました。より広く区民の皆さんの意見を区議会の議論に乗せていこうという考え方から言えば、私は、ちょっと機械的過ぎるのではないかと感じておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]},{"id":"topic-02","title":"議会報告会の実施","agenda":"議会報告会の実施","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"ワークショップの議題について、いつごろまでに決まることになるのでしょうか。もし目途があれば教えていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"たけうち副委員長","kind":"意見","question":"２月１９日までに各会派で案を持ってきてくださいということで、今、投げかけてあります。厳しければ、もしかしたらもう１回くらい持ち帰りになる可能性はありますけれども、３月中旬前までには決めていかなければいけないと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"}]},{"id":"topic-03","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"たけうち副委員長","kind":"質問・要望","question":"２点ですが、(5)期末手当の支給日の日にちをおっしゃらなかったと思うのですけれども、日にちの確認です。議会として何か合理的配慮で必要なものがないのかどうかということを、４月１日を迎えて、そういうことをやっていただけないかという要望です。","respondent":"原区議会事務局長","answer":"２点目の関係ですけれども、物理的な配慮、それから窓口での対応等々の配慮ということでやってきたところです。テープについては昭和５９年から、デイジーについては平成２３年からそれぞれ実施してきてありますし、さまざまな形で配慮をしてきたところです。","id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"提案","question":"北朝鮮の弾道ミサイル発射の強行に対して、品川区議会として抗議の決議を上げてはどうかと、提案をしたいと思います。弾道ミサイル技術を利用したいかなる発射も行わないことを求めた国連安保理の決議にも反しますし、ぜひ厳重に抗議したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"本多委員","kind":"提案","question":"今の提案を受けて、私は平成２１年に区議会議長に就任させていただきましたときに、議長になって最初の仕事だったのを思い出しました。確かに思いはありますが、ただ取扱いについては、会派に持ち帰っていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"塚本委員","kind":"意見","question":"大前提としては、そういう抗議、または決議をやっていくことに関しては、前向きに検討すべきことだと思いますけれども、文言その他、今あったいろいろなことへの配慮もしながら、どのタイミングで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"そういったことも含めて、もし過去にミサイル関係では出していなかったことの判断の基準がわかれば、事務局にお伺いしたい。それも参考にしながら、会派のほうでも考えてみたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"私はやはり、国民、都民、区民から考えれば、抗議文を出したほうがいいとは思います。品川区議会に議長がいらっしゃるわけですから、我々の代表ですから、どういう対応がいいのかお任せしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701951?Template=document&Id=5168#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":21776,"voices":75}},{"id":"h28-20160218-10","meetingId":"h28-cm02","date":"2016年2月18日","dateIso":"2016-02-18","committee":"議会運営委員会","time":"午前１１時４０分～午前１１時４５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"の１、北朝鮮のミサイル発射に対する抗議","agenda":"の１、北朝鮮のミサイル発射に対する抗議","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"持ち帰りということで会派内で話をさせていただき、議長のほうで改めてしっかりと判断をしていただきたい。抗議の形で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"塚本委員","kind":"意見","question":"抗議すべきということについては、何かしらの抗議を、反対の意を表明するということはありだというふうに思っております。今後、必ずしもそういう決議ということではなくて、議会を代表して議長のもとで何かしらの発信をしていただくというほうがいいのかなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"あべ委員","kind":"意見","question":"ちょっと違和感がありますので、今回、会期中だから決議というわけにはいかないかなと感じております。そういった意味でも、やはり今後どういうような場合には、何らかのちょっと目安みたいなものも少しずつ固めていけたらいいなとは思っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701951?Template=document&Id=5170#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":1829,"voices":15}},{"id":"h28-20160219-3","meetingId":"h28-c-budget","date":"2016年2月19日","dateIso":"2016-02-19","committee":"予算特別委員会","time":"午後３時４０分～午後３時４７分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"つる副委員長","kind":"意見","question":"石田秀男委員長のもと、しっかりと、今、委員長のほうからもご挨拶ございました活発な議論、そして実りある委員会としてまいりたいと思います。そのためのしっかりと副委員長としての職務を全うしてまいりますので、各委員の皆様のご協力をどうかよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/523832?Template=document&Id=1034#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":2084,"voices":17}},{"id":"h28-20160222-6","meetingId":"h28-cm02","date":"2016年2月22日","dateIso":"2016-02-22","committee":"区民委員会","time":"午前１０時００分～午後 ２時００分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問","question":"本当にそれが確実なものなのか、信頼に足りるものなのか、その点を一つ伺いたい。この３つの種類がコンビニ交付になるわけですけれども、この３つでスタートするけれども、その辺を２点伺いたいと思います。","respondent":"井浦戸籍住民課長","answer":"１点目の情報漏えいについてのご懸念ですが、先ほどご説明いたしましたが、まず全体的なシステムとしての安全性が高められているところです。今後の拡大の可能性といたしましては、戸籍証明についてはシステム的に現在でも実施可能ですが、現在は区としては考えていないです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"区民のそういうプライバシーを守るという立場に品川区自身が立たない、投げ捨てだと私は思っていますので、これはやめるべきだと思います。後半のこの２つの２番以降の問題については賛成の立場ではあるのですけれども、コンビニ交付だと思いますので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"マイナンバーカードを利用してのコンビニ交付は、どのくらいの利用を見込んでいるかというのを教えていただきたいのですが。","respondent":"井浦戸籍住民課長","answer":"当初の平成２８年度につきましては、１０％の利用を見込んです。","id":"exchange-003"},{"speaker":"松永委員","kind":"質問","question":"私からは、まずこの印鑑登録証というラミネートされたものがあるのですけれども、それはコンビニでも使えるのかどうかちょっと伺いたいのが１点です。要するにコンビニでやるのと区の窓口でやるのでは、時間がどのくらい短縮されるのか、その点について伺いたいと思います。","respondent":"井浦戸籍住民課長","answer":"２点目につきましては、暗証番号で公的個人認証をいたしまして、コンビニの多機能端末機で交付を行うという仕組みです。コンビニの多機能端末機につきましては常時お１人いるかいないかというところですので、かなりスピードアップも図れるのではないかと考えています。","id":"exchange-004"},{"speaker":"松永委員","kind":"質問","question":"その短縮というのは、要は、今窓口で大体１人何分かかる、ではコンビニだったら何分という、具体的なのを教えていただければ。","respondent":"井浦戸籍住民課長","answer":"現在平均いたしますと、印鑑証明については３分ほどで窓口でも交付という形で運用されているところです。コンビニ交付につきましては１分前後で交付可能と考えています。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"全国４万８,３３０店というこの４事業者なのですけれども、提携しているコンビニであればそこでもとれるかどうかということが一つです。この２番の建築物のほうなのですが、先ほどもありましたけれども平成２０年からということで、認定があるのかというのを説明を求めました。","respondent":"井浦戸籍住民課長、鈴木建築課長","answer":"１点目の全国の約５万店舗です。こちらでご案内してあります４社につきましては、全国どこのコンビニでも区民の方はマイナンバーカードを利用してコンビニ交付が可能です。 長期優良住宅の認定申請の実績ですが、平成２２年度から受付を開始しておりまして、例年７０件から９０件程度というところで、今月現在時点で、トータルで４８９件という実績です。","id":"exchange-006"},{"speaker":"たけうち委員","kind":"意見","question":"コンビニのほうは、そういう面では非常に利便性が高まるなという感想です。予算書を見ればよかったのですけれども、予算的には新年度、どれくらい見込んでいるのかがわかればとの意見を述べました。","respondent":"鈴木建築課長","answer":"法律の改正を見込んでの予算上の措置は、今のところしてございませんが、見込み的には、全体の新築に対する増改築の割合というのが大体２％程度ですので、年間１件あるかないかというところで見込んでいるところです。","id":"exchange-007"}]},{"id":"topic-02","title":"第２３号議案、品川区町会および自治会の活動活性化の推進に関する条例","agenda":"第２３号議案、品川区町会および自治会の活動活性化の推進に関する条例","exchanges":[{"speaker":"田中委員","kind":"質問","question":"その区政協力委員会というのですか、その発言は町会を背負ってではなく、個人の発言でいいというように聞いています。しかし、それが町会・自治会が条例で位置付けられることで、区政協力委員としての立場がどのようになるのかということをまず説明を求めました。","respondent":"久保田地域活動課長","answer":"そして、今まで皆様方がそれぞれの町会・自治会の立地特性とか地域特性に応じて活動してきたものを継続してやってくださいと。これらにつきましても、その趣旨の部分には変更は全くございませんので、ご懸念は要らないかと思ってあります。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"最後のところをもう一回聞きたいのですけれども、個人の発言ではなくて、地域を背負った発言ということになるのか尋ねました。","respondent":"久保田地域活動課長","answer":"ちょっと説明が足りなかったのですけれども、そういう意味ではやはり地域の声であるということで、私どもは認識しているです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"では、ちょっとほかの話に行ってもいいですか。いろいろな方のご意見を伺っていきたいと思っています」と答弁されているのですが、それらの意見をどの部分に反映されているか説明を求めました。","respondent":"久保田地域活動課長","answer":"例えば意見としましてよくお聞きするのが、会計の透明性がなかなかわからないとか、どういった活動をされているかがわからない。そういうことがないように、そういった活動の支援ができるようなこととして、条例の制定も一つの手法だと思ってあります。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"そして品川区としては、さっきちょっと言ったように、今まで以上に取組むことが重要というのは何を取組むのかをまず伺いたいと思います。そういう角度で、やはりこの条例が本当にそういう皆さんの支えになるのかどうか、質問させてほしいと求めました。","respondent":"久保田地域活動課長","answer":"これ以外にも、区との関係でご説明をさせていただいているのは、今まで以上に力を合わせて取組んでいきたいと思ってあります。区民の方々にもう一度注目をしていただきたいと、もう一度改めて町会・自治会の大切さというものを認識していただきたいということとともに。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことを思ってしまうような印象を私はちょっと持ったので、改めてそこについてどのように見ておられるのかを伺いたいと思います。だからそこはどこなのかというのがもしあるのであれば率直に指摘をしていただきたいし、そういう質問をしたいと思います。","respondent":"久保田地域活動課長","answer":"そこのところは私どもとしましては、そういう不十分だという認識はないということをご理解いただきたいと考えています。町会・自治会が今まで以上に中心となってやっていかれるということは私どもも十分認識していますし、この条例を制定するというものです。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"あるいは、行政との関係ではそういう枠組みをつくっていきたいと思っておられるのか、そのあたりを確認したいと思うのです。いや、とんでもない、そういう不安があるということについてどのように区は見ているのかというところを伺いたいと思います。","respondent":"久保田地域活動課長","answer":"ご意見をいただいた中で改めて認識をしたところですが、下部組織であるというような認識は全くございませんので、ご理解いただければと思います。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、町会・自治会の責任あるいは仕事量は、今と比べて増えていかないということで考えていいのですか、というのが一つです。お願いする仕事に対しては、ないと見ていいのですかというのをさっき質問したつもりなのですけれども、そこを答えてほしいと求めました。","respondent":"久保田地域活動課長","answer":"逆に答申でいただいている三本の柱の３本目でありましたように、消防、それの負担軽減を図らなければならないと考えています。その意味では、また警察や消防に対しても、こういった結果が出ていますということを広く知らせることで負担を軽減していきたいと思ってあります。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"さらに全地域に広がっていくという状況の中ですから、こういう分野の業務、仕事はなっていきがちだと思うのです。行政の仕事は行政としてしっかりやるという態度にしっかり立っていただきたいということを強く求めたいと思います。","respondent":"久保田地域活動課長","answer":"それと、私どもとしてはこれを支えて、そういう点に関しましては積極的に支援をしていきたいと思ってあります。地元の方々にとっても安心して生活ができると、そうした点を踏まえつつ、町会・自治会の活動をさらに支援していきたいと思ってあります。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"確かに身近に相談できる機能は必要だけれども、しかしやはりここは自治体がやるべき仕事は、品川区が行政としてやるべき分野だと思います。もう一つ伺いたいのですけれども、施策とは例えばどのような内容なのか、それを伺いたいと思います。","respondent":"久保田地域活動課長","answer":"例えばこの第５条の地域コミュニティの活性化に資する施策というものですけれども、そういった季節の行事等が主なものと思ってあります。そういったものに新規の事業があれば、それは町会・自治会ともいろいろ話をしながら、区の責任において実施をしていきたいと思ってあります。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"私有地になるわけですから、そういう私有地に入ることも含めて認めてほしいという考え方を品川区としても示すみたいに私は理解したのですけれども。この「資する施策」というのはどのようなことなのかを伺って、終わりにしたいと思います。","respondent":"久保田地域活動課長","answer":"第５条の第２項ですけれども、委員から話がありました主なものとしましては、加入促進活動というものが主なものだと思います。その前段となるものとして、それを一歩踏み込むという意味で、共有部分への立ち入りの協力をマンション等に求めていこうというものです。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"そして、区外の事業者にもこの条例の適用は求められるものなのでしょうか。各行政機関が相互に連携を図り、この部分をどう条例に反映しているか、反映しているところの箇所を教えていただきたいです。","respondent":"久保田地域活動課長","answer":"住宅購入者のほうの重要事項説明については、住宅販売をする方々に、加えていただきたいと思ってあります。ご議決をいただいた後に、関係する団体等にも説明をし、理解を求めていきたいと思ってあります。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"事業者の方の了承についてなのですけれども、条例を提出後に話をするということだったのですけれども、その話をするのは、町会・自治会の方が事業者の方に条例のことを説明するのではなくて、行政のほうからきちんと条例の説明を行うのか尋ねました。","respondent":"久保田地域活動課長","answer":"私どもが責任を持って相手の団体に説明はします。","id":"exchange-019"},{"speaker":"たけうち委員","kind":"質問・要望","question":"２３区の中では高いほうなのですけれども、６５％にするだとか、何かそういうのがあるのかどうか教えてください。この名和田委員長のお話を２年ぐらい前に伺う機会があったのですが、地方分権とかいろいろ言っていますが、いわゆる町会が加入率を高める。","respondent":"久保田地域活動課長","answer":"この２年間の成果を報告書に取りまとめる等は、今、考えてありますけれども、アクションプラン等の取りまとめは予定はございません。第１０条の加入促進の支援ですけれども、例えば加入が何人ということでも構いませんので、それに向かって活動していただければと思います。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"確認","question":"もう、そうすると１回延長したと思うのですけれども、もう終わってしまったということですか。そこを確認したいのと、そうは言ってもなかなか町会・自治会に入りづらい、もしくは入りたくない。","respondent":"久保田地域活動課長","answer":"私のほうの説明が不十分でしたけれども、町会・自治会の方々と話し合いながら、今後進めていきたいと思ってあります。私どもも認識していますし、やはり町会・自治会側としてもきちんと自分たちの置かれている立場というか期待感というものを認識して。","id":"exchange-021"},{"speaker":"田中委員","kind":"確認","question":"確認してもいいですか。財政上の措置のところで、会計の報告をきちんとしなければいけないと思うのですけれどもという質問にもう一回答えてもらってよいか尋ねました。","respondent":"久保田地域活動課長","answer":"会費や寄附等を受けて活動をしていますので、これらにつきましては年に１回会計報告を各町会・自治会とも作成をしています。年に１回ですけれども、その会計報告についても報告をいただいてありますし、会計はきちんとできていると認識を持ってあります。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"その会計報告というのは、同じ町会・自治会の方たちが見られるのか尋ねました。","respondent":"久保田地域活動課長","answer":"会計報告ですので、きちんと総会等を経て決定していると認識していますので、町会・自治会の会員の方々にも公開はしているものと思ってあります。","id":"exchange-023"},{"speaker":"松永委員","kind":"確認","question":"確認で３点伺います。３点目が、第１４条に関して、掲示板について新築だけなのか、それとも既存のマンションについても含まれているのか伺いたいと思います。","respondent":"久保田地域活動課長","answer":"例えば第７条の中の事業者の役割の中で、これに準じた形で町会・自治会との良好な関係を築いていっていただきたいと思ってあります。第１４条に関しましては、掲示板の設置だけではなくて、ここは既存のマンションも含めているです。","id":"exchange-024"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"今後、区から助成してもらいやすくなるための条例でもあるはずですから、そういう意味では町会・自治会の方々はあらあら歓迎だと思います。町会・自治会、区民に対してそれを求めるわけではないですから、そこは相当自由度が高い条例になっていると思います。","respondent":"久保田地域活動課長","answer":"この第１３条ですけれども、今イメージとして考えていますのは、地域活動課のほうに事業者に来てもらうというイメージを持ってあります。そういった情報をお寄せいただければ、届出をしていただいて、それを町会のほうへもきちんと情報として提供はしていきたいと思ってあります。","id":"exchange-025"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"例えばそういうのが選任されたところで、向こうがすり替えてくる可能性も、よく１年で交代するとかいう話も聞きます。この説明のときに、かなりここをきっちりやっていただきたいというのを要望するのですけれども、その辺はやっていただけますか。","respondent":"久保田地域活動課長","answer":"１点目が、きちんとそれが引き継がれるようにするということが大事ですので、それぞれの段階で地域連絡調整員の届出をしてもらうということが１点。","id":"exchange-026"},{"speaker":"南委員","kind":"確認","question":"下におりてくる業務、仕事が減っているという発言について改めて確認したいと思っているのですけれども、減っているのでしょうか。平成２３年度からの五、私は増えているのではないかと思って先ほど質問したのですけれども、実際はどうなのか尋ねました。","respondent":"久保田地域活動課長","answer":"私どもは減っていると認識はしています。それもできるだけ数を減らす、効率的にできるよう形では工夫してきたところですので、そういう意味では業務量は減っていると思ってあります。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"その辺はどうなのですか。むしろ拡大しているのではないかと私は思ったので、さっきそのように質問したのですけれども、いかがなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"渡部副委員長","kind":"質問","question":"町会・自治会が２０３団体あって様々な事業をなさって、今の高齢者の見守りというのは手挙げですから、別に手を挙げなければやっていないです。ですから、南委員のお話で言ったら仕事など雪だるまのように増えていくわけで、減ることはなくなるのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"南委員","kind":"確認","question":"そういう事実になっているということは改めて確認したのですけれども、そういうのが大事だという認識がまちの中にもいっぱいあるではないですか。そういうことに対して、やはりもうすごく苦労しているところは事実としてあるわけですから、そこのところをちょっと言ったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"南委員","kind":"意見","question":"私は自治体として、町会・自治会を支援するということは大事だと、前提として当然そのように思っています。自主的なところは自主的に大いにやってくださいと、しかしできるだけ投げていくということは、そういうことを申し上げたということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"最後に意見を言っていいですか。私はやはり任意団体というところをしっかりと改めて確認をして、しっかりと仕切っていくという態度が行政の側で求められるのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"田中委員","kind":"意見","question":"個々の町会・自治会の状況に合わせた活動の自由と、参加する個人の自由は担保されるべきだと考えています。その２つを前提にして賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]},{"id":"topic-03","title":"第２５号議案、品川区消費者センター条例の一部を改正する条例","agenda":"第２５号議案、品川区消費者センター条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"平成２１年に法律が制定されたということなのですけれども、配置をしていたことのその思い、そのあたりがどうだったのかをひとつ教えていただきたい。現状６人の消費生活相談員を置くということで、その資格のあたりを聞き逃してしまったので、もう一度説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"かれこれ３５年前というようなことで、消費者被害の防止などについて区のほうの施策の中に取り込んでしっかり対応してきたということと。それぞれ資格取得した年度は違いますが、すべて６名の方々についてはこの資格を取得されているという状況です。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"あるいは区としての当時のご認識が非常に先んじて積極的であったとか、どういうところに由来するのかが知りたかったのですが、わかれば説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"区の様々な事業につきましては、１０年を一区切りの長期基本計画というものが一番計画行政の骨子としています。その中で区民の、そうしたことに規定をしながら、当時からこの業務について力を入れてまいったというような経過です。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"９時から１６時になった理由と、その部分と、あと火曜日の時間が増えたのですね。日曜日にしか相談に行けないという方はどうするのかということと、今とどう変わるのかということを説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"月１回午後７時までという夜間での対応をしようということで、第４火曜日と定めております。したがいまして、そうした時間外につきましては、国などの機関と連携しながら一時的な対応、受付をするようなことはできるようになっております。","id":"exchange-036"},{"speaker":"たけうち委員","kind":"意見","question":"改正理由のところで、だから去年の４月から条例施行みたいな感じでやってくるのかなと思ったので、その辺の理由が何かあればということ。第４条を第１０条とすると、もとの４条、どのような内容だったのかとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"それは、２年の間に施行を消費者庁もにらみながら、それぞれの自治体の対応具合を見ていたと聞いてあります。それから第３条が、消費者センターで取組む事業内容が列記されているというようなことです。","id":"exchange-037"},{"speaker":"たけうち委員","kind":"意見","question":"第４条を第１０条とするとあるので、第４条をちょっと知りたかったのです。それとも政省令で平成２８年、今年度の４月１日にしなさいとなっていたのか、そこがわかればとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"公布から施行まで２年以内という間の中で、そういった消費生活相談員を配置してということがそれぞれの自治体に求められることに当然なります。品川区はそういった要望はありませんでしたけれども、そうしたこともありまして１年と少し時間がかかったと聞いてあります。","id":"exchange-038"}]},{"id":"topic-04","title":"第２６号議案、品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","agenda":"第２６号議案、品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ＮＰＯ法人というのはもう特定非営利法人ということですから、利益を民間の事業所みたいになかなか出すような仕組みになっていないと思うのです。ちょっと性格が違う非営利法人というところでは、その辺をどのように見ているのかを教えてほしいと求めました。","respondent":"河内協働・国際担当課長、山崎商業・ものづくり課長","answer":"次に多いのが福祉、保健、医療の分野で１０％です。その次は子どもの健全育成の８.５％でございまして、そのほか人権、国際、科学技術、情報というようなものが１９個並んでいるという状況です。先ほどちょっと説明を申し上げなかったのですが、改正理由で１０月１日に法改正があって、今回条例が４月１日に改正になります。","id":"exchange-039"},{"speaker":"南委員","kind":"確認","question":"２４２団体のＮＰＯ法人があるというところで、子どもの問題等々、そういう意味でも財政的な支援は本当に必要なのかなと思っているのです。信用保証協会の保証制度によって保証されるのかということを確認したいのですけれども、部分保証になるのか、そのあたりも説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"これは信用保証協会が８０％、銀行が２０％ですけれども、そうした融資それぞれの種別で責任共有の範囲が決まっているです。国のほうで今、それ以外のものが先ほどの８対２というような責任割合のものを利用できるということが基本になっております。","id":"exchange-040"},{"speaker":"南委員","kind":"質問","question":"返済能力というのは先ほど伺ったのですけれども、ぐんと利益だけを上げるような活動というのは大体あり得ないと私は思うのです。だから２４２団体のＮＰＯ法人がどれくらい不況業種としてあるのか、品川区が肩がわりすることも含めて、その辺についてはどうなのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"融資制度の適正な運営に資する部分と、それから区としてＮＰＯ活動を支援していくということで、そういう意味では両輪の部分です。今決まっている融資制度の中において、ＮＰＯ法人の活動も担保していく、あるいは相談をしっかり丁寧に聞いてまいりたいと考えています。","id":"exchange-041"},{"speaker":"南委員","kind":"意見","question":"要するに２４２団体の品川区内で活動している非営利法人のうちの、不況業種にあたる活動をしているところはどのくらいあるのかがまず１つ。（「調べようがない」と呼ぶ者あり）との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、今こういう状況の中で、１００％融資というところをしっかり担保していきたいというような趣旨の答弁をしていらっしゃるのです。改めてここを確認したいと思って質問したのですけれども、不況業種とそうでないところの仕分けをしたのか、そこを教えてほしいと求めました。","respondent":"河内協働・国際担当課長","answer":"私のほうからは、数の部分をご回答させていただきたいと思います。ＮＰＯ団体の登録要件の中には、この２４２の内訳の中で、今の段階でちょっとお答えすることが難しいということです。","id":"exchange-043"},{"speaker":"南委員","kind":"意見","question":"資金がどうこうではなくて、そういう活動をしているのかどうか、そういう団体があるのかということを聞いているのです。（「相談にまだ１件しか来てないのだから、わからないでしょう」と呼ぶ者あり）との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"だから、その辺をちょっと教えてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"したがいまして、例えばまちづくりの分野では６７団体とかいうような統計のもとにお答えしておりますので、非常に今現状ではわからないです。対応をしっかりとらなければわかりません。","id":"exchange-045"},{"speaker":"南委員","kind":"質問","question":"そうしますと、この品川区内で活動しているＮＰＯ法人の２４２というのは、不況業種にはあたらないと見てしまってもいいのですか。」と呼ぶ者あり）。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"南委員","kind":"質問","question":"それは、では相談に来たときに、こういう活動をしていてこういう運営状況だという話が当然ありますね。では、では１００％保証になりますとか、そうではないから責任共有制度での融資なのですよというふうに仕分けをするということなのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"まさに委員がおっしゃったとおり、経営相談の相談員は、相談されたＮＰＯ団体、これからはそうです。利用していただいているということの流れで、ＮＰＯ団体につきましても、適正な相談業務等も行ってまいりたいと考えているところです。","id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"８割は保証されるけれども、２割は銀行のほうに責任が行ってしまって、今までしっかりと活動していたのができなくなってしまう。そういう思いで聞いているので、その辺のフォローはどのように考えているのかを教えていただきたい。","respondent":"山崎商業・ものづくり課長","answer":"その中で、区としては銀行のほうに協力あるいは指導をさせていただいているようなことを通じて、先ほどのご意見などについて対応してまいりたいです。区としましては、直接融資の部分の信用を区のほうで直接とるということは、現状では考えてございません。","id":"exchange-048"},{"speaker":"南委員","kind":"確認","question":"今の答弁の確認ですけれども、そこは具体的にはもっと厳しく見るのではなくて、そこのところをちょっと確認したいのですけれども。","respondent":"山崎商業・ものづくり課長","answer":"協定の内容の中で、正当な理由がなくいわゆる貸し渋りを行うような不当な行為については、協定の中でそれをうたってあります。そうした協定遵守をお願いすることによって適正な関係を保ちつつ、いろいろな経営の支援の一助ということでやってまいりたいと思っているところです。","id":"exchange-049"},{"speaker":"南委員","kind":"確認","question":"最後に１点、やはりそれはもう上位のところですから、今この時期にはそれはやらないという趣旨のご答弁なのです。そういうところで、そこから発した今の答弁と読んで評価をして受けとめていいのかということを最後に確認して、終わりたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"国の法律に基づいて信用保証制度というのはありますので、法の規定を遵守する形で、区としては取組んでまいるです。","id":"exchange-050"},{"speaker":"たけうち委員","kind":"意見","question":"ご案内などはどうされるのかということと、そちらのほうは何か動きがあるかどうか、もしわかればとの意見を述べました。","respondent":"河内協働・国際担当課長、堀越地域振興部長","answer":"こういうスキームが利用・活用できることをしっかり宣伝していって活用の実施を図っていきたいというところで連携をとるということで進めていくつも…そういったところの活動は今後も継続していただくような形で対応することが重要と考… 今日も１件あったという報告をさせていただきましたけれども、実態を見ながら実態に即した形で対応していくというのはもちろんそのつもりです。","id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"賛成ですけれども、ちょっと意見言っていいですか。そこをもって、責任共有制度になった場合はそういうことも含めて、今回の制度の改善も求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]},{"id":"topic-05","title":"────────────────────────────── (6) 第２７号議案 品川区立総合区民会館条例の一部を改正する条例 次に、(6)第２７号議案…","agenda":"────────────────────────────── (6) 第２７号議案 品川区立総合区民会館条例の一部を改正する条例 次に、(6)第２７号議案…","exchanges":[{"speaker":"田中委員","kind":"意見","question":"細かなことなのですけれども、改正内容の（１）「母子」を「母子等」に改めると書いてあるのですが、なぜ「母子・父子」ではなかったのかということの意見を述べました。","respondent":"間部文化観光課長","answer":"その第１条第１項の部分「母子」を「母子等」にというのは、まさに今委員がご指摘のように、父子を含むということで「等」とさせていただいたものです。","id":"exchange-053"}]},{"id":"topic-06","title":"報告第１号、専決処分の報告","agenda":"報告第１号、専決処分の報告","exchanges":[{"speaker":"たけうち委員","kind":"意見","question":"１点だけ。区の場合はどうなっているのか、担当が違ってわからなければ、今日でなくて結構ですとの意見を述べました。","respondent":"間部文化観光課長","answer":"保険につきましては経理課庁舎管理係のほうで一括してなのですが、本件については多分任意保険に入っておりまして、そちらからの補償ということになっていると思います。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/294647?Template=document&Id=2744#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":56610,"voices":182}},{"id":"h28-20160222-7","meetingId":"h28-cm02","date":"2016年2月22日","dateIso":"2016-02-22","committee":"厚生委員会","time":"午前１０時００分～午後 ４時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を136件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"いながわ委員","kind":"意見","question":"２点聞きたいのですが、この規定に対するメリットとかデメリットはどういうものがあるのかということが１点と、今。推進会議を設置したりしなければいけないので、そういった部分はスムーズに移行されるものなのかという、その辺だけとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"例えば変更届等の手続のときに、現在、品川区では近隣の区の中でその手続が少しでも楽になるように協定を結ぼうかということで検討しています。そのうちの３３カ所が移行の予定になっています。","id":"exchange-001"},{"speaker":"のだて委員","kind":"確認","question":"どの職員の方が何人いればいいのかということの確認と、それぞれ介護職員の方ですとか、機能訓練指導員の方の資格要件などがあるのか伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"５ページになりますけれども、管理者、第５９条の４に規定しておりますけれども、これも１人以上ということになっています。ただ、サービス提供加算があるので、資格のある人の人数をそろえることによって、報酬のところで加算をつけるというような制度になっています。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"いいかという確認と、利用者の方ですとか、このメンバーの中に必ず入れなければいけないのかということを確認させてほしいと求めました。人数も説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"１つ目の事業所の人数のことになりますけれども、さっきの説明でいくと、この人数ではやっていないかと考えています。去年の４月から第三者評価をしなくてもいいという規定になっていますので、そうなると、区としては必ず入れていただくということです。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"運営推進会議のほうも、もし平均的な人数がわかるのであれば教えてほしいと求めました。その方向で進めていってほしいと求めましたが、それとも、ずっと誰か１年間ずっと一緒の人が参加するということになっているのか説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"ご利用者を参加にしたときに、交代か固定かということですけれども、１年間は固定にしています。引き続きということも考えられますし、毎回かわるということは想定しておりません。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"昨年１２月に行われた全国の介護ですとか保険、これから法人への委託を推進していかれるのか、そこの考え方をお聞きしたいと思います。あわせて、監査なのですけれども、市町村が実施と書いてあるのですが、それはどのくらいの頻度で行っていくものなのか伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"ですので、この規定ができたからといって特に変更になることはないと考えております。ですので、委託は考えておりません。","id":"exchange-005"},{"speaker":"のだて委員","kind":"確認","question":"これまでも区のほうで実地指導などやってきたということで、委託は考えていないと、区の負担が増えるわけではないからということだと思います。指定事務についても同じ考えでいいかという確認をさせてください。","respondent":"永尾高齢者福祉課長","answer":"新規の指定だけではなくて、更新だとか、変更届の数はかなり行くのではないかと想定しております。その辺については、区の高齢者福祉課のほうでも今から準備をしています。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、これから準備するということですので、今のところは委託を考えていないということだと思います。現在、その中でサービスが切られてしまうということをちょっと危惧するのですけれども、その辺の考え方も説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"他自治体のご利用者につきましては、現状ではそのまま継続してサービスの利用ができるというふうな規定になっておりますので、切られることはございません。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"他の自治体からの利用者というのは、どのくらいいらっしゃるのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"その数字は、現在、手元に持ってありませんので、基本的には通所となりますと、そんなに遠くから通えるわけではございませんので、せいぜい区界のところのご利用者だと思いますので、そこら辺は隣接区とも協議しながら進めていきたいと考えております。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"継続していくということですので、やはりしっかりと利用者の方がサービスが受けられないということがないようにやっていってほしいと求めました。この具体的なイメージが沸かないのですが、どういったことをやっていけばこれに当たるのかというところを説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"今度、そういう行事のときに地域の方も参加できるようになるということで、かえって利用者にとってもいいことではないかと思います。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"これも今回新しく指定事務も全く新しい事務だということで、区の体制としてはどういったことになるのでしょうか。は財源は、これは都から改正によっておりてきたものだと思うのですけれども、どこから財源が出ているのか伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"この事務がおりてきたことに伴いまして区の体制ですけれども、現在、人員の調整等をしています。財源については、東京都からは特におりてきておりません。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"新たにおりてきて、人員配置していって、しっかりとこの事業をスムーズにやっていけるようにしていってほしいと求めました。都から事務はおりてきてもお金はおりてこないということで、利用者が財源がなくて困るということはないようにしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"趣旨は質の向上を図ろうかということなのかどうかということがあって、もともとの介護保険が１回区でやれということになったわけではないですか。どうしてこういうことを聞くかというと、連携して、そのときだけ来てもらおうという考え方もあったわけではないか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"こういうふうに区市町村に落とすことによって地域包括ケアの一歩になるかというふうに国としてはにらんでいるところかというふうに思っています。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"すごくやっていらっしゃると思うのだけれども、ケアマネのその部分については、結果としてなかなかうまくいっていないのではないのかと思っています。こういう部分が、ここから入ってもいいけれども、一歩前へ進むと思えばいいのかなという感覚を教えてほしいです。","respondent":"永尾高齢者福祉課長","answer":"地域包括ケアを進めるというのはとても大変だというのは、もう何年も前から取り組んでいてもなかなか難しいところはあるのですけれども、もう二歩というふうに進めていきたいというふうに考えております。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１９人未満ということで分けられて、ここのところがなかなか、それは今後に向けての要望ということで１つ出させてほしいと求めました。改めて確認させていただきたいのが、常勤者はこの場合は１人で、そういう体制なのかというところを教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"かえってわからなくなるかなということで、今回は条例のご審議ということで、新旧対照表を見ながらの説明とさせていただきました。ですので、介護職員常勤１人以上の確保というところしか現状でも明文化はされておりません。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこのところの確認と、何カ所ぐらいあるのかということを１つ教えていただきたいのと、ここに参加をする地域住民の代表者というところがありますね。大体町会長とかが入られていることが多いのかということを教えていただきたいのと、そうなると、３３カ所の事業所の推進会議に入られていくとなると。","respondent":"永尾高齢者福祉課長","answer":"ですので、小規模多機能とか、グループホームとか、定期巡回をやっているところとか、夜間対応をやっているところ、そこは全部やっています。民生委員というのもありますので、それはその事業所の中で決めていただければいいかと思っています。","id":"exchange-015","title":"町会・自治会支援"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"おおよそ１年間にすると、区内では３３カ所ということですけれども、都外の事業所はどれくらいあるのかということについてもお聞かせいただけたらと思いますとの意見を述べました。","respondent":"永尾高齢者福祉課長","answer":"それは変更の都度ということで、管理者が変更になったり、そういう変更も入ってきますので。都外については７０カ所、現在あります。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"都外が７０カ所となると、この委託のところも体制を整えてずっと区できちんとやっていただきたいと思っていますけれども、その確認もさせてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"内容もすぐわかるし、質も担保されるということですので、委託は考えておりません。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"もう１つお聞きしたいのが、６カ月に一遍に緩和されるという、認知症の対応の通所介護の運営推進会議の設置のところだというところでいいのかという確認をお願いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"第２９号議案については、認知症対応型通所介護の運営推進会議の２カ月から６カ月に緩和するというところだけが変わるところになります。認知症対応型通所介護は、総合事業には移行しませんので、認知症対応型は移行しませんので従来どおりとなっております。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"要支援１・２の認知症の方も、認知症対応の通所介護に通う場合は総合事業ではないという、そういう仕組みだということでの理解でいいということか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"給付の事業でも総合事業でも、介護保険事業の中には入っているのですけれども、認知症対応型のように医療がかかわってくるものについては、今回、総合事業のほうには移行していませんので、従来どおりというふうになります。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"認知症対応型のグループホームですとか、地域密着型の特養ホームですとかというのは、運営推進会議を２カ月に１回という形でされていましたよね。地域密着という形での２カ月に一遍の運営会議がされていたものが、それが今度は、そういう変更ということでよろしいか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"そのとおりです。全てもともと２カ月に１回という規定になっていたのが、認知症対応型も通所になりますので、同じにそろえるというような考え方になります。","id":"exchange-020"},{"speaker":"若林委員","kind":"質問","question":"区のほうで指定される業務があります。３３カ所が今回この地域密着に移行するということですが、通所介護は、適正な数というのは何か想定されている根拠とかをお持ちなのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"基本的には法律上では区が日常生活圏域ごとに必要な数量を計画に定めてバランスよく計画しなさいというような規定がされております。","id":"exchange-021"},{"speaker":"若林委員","kind":"確認","question":"３３カ所が地域密着になると。そうすると、もうそろばんでパパンとはじけてしまっているのかなと思うのですが、それを確認。","respondent":"永尾高齢者福祉課長","answer":"その中で、運営するに当たって、やはり介護方針もある程度定められておりますので。要するに、そういうところは経済的なところも考えながら、利用者も進出する場所を考えていくのではないかというふうに思っているところです。","id":"exchange-022"},{"speaker":"若林委員","kind":"質問・要望","question":"面倒を見ている方たちをどこにどうするか、高齢者福祉課が、一緒になってやる作業になるわけですね。そうすると、適正な規模というのは、これはしっかり事業者に頼るのかどうかというところはしっかりと監査も含めてやってほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"この変更に伴いまして、その内容をきちんと検査をした上で指定を許可するという形をとろうかと考えています。事業者がだめになった場合につきましても、どこの通所のほうにお回ししたらいいかということも一緒に話し合いながら決めていきたいと考えております。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１つだけ教えていただきたいのは、ここに入るのかどうかわからないので教えていただきたいのは、地方に住宅型有料老人ホームがあるではないですか。これとは違うのだというならいいのだけれども、間違っていたらごめんなさい、ちょっとよくわからなかったのでそこを教えてもらいたい。","respondent":"永尾高齢者福祉課長","answer":"やはり１９人以上と未満で分かれるようになって、そこでもし品川区の住民の人が入ってくるとすれば、品川区にも届け出を出すというような仕組みになっております。","id":"exchange-024"}]},{"id":"topic-02","title":"第３０号議案 品川区立シルバーセンター条例の一部を改正する条例","agenda":"第３０号議案 品川区立シルバーセンター条例の一部を改正する条例","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"もともと平塚のシルバーセンターは、たしか狭い道を入っていたところにあったと思うのですけれども、もともと使っていた利用者がいるではないですか。は、５月１日以降は、これは取り壊しをするのかどうなのかということだけ説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"もともとのご利用者の方につきましては、昨年と今年に入りまして説明会を設けております。それからあと、取り壊しについてですけれども、今後、耐震補強ができない構造ですので、それを次年度に予定しています。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問","question":"ちょっとわからなかったのでお聞きしたいのですけれども、耐震補強ができない構造というのは、どういった構造になるのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"平塚シルバーセンターは、軽量鉄骨構造の２階建てになっておりまして、柱と梁の接合部等で揺れたときに柱と梁の物質内部に力のつりあいをとるのが困難な構造になっているということで、それを補強するということが難しいということで、施設の所管課から報告を受けております。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"廃止した後の土地はどういうことに使っていくのかというのは決まっているのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"高齢者福祉施設等を予定しています。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"平成２６年度では１日平均で７２人ということで、入浴者の方も３,９００人ほどいらっしゃるということで、現地での建て替えで残すことはできないのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"ご説明させていただきましたように、複数回直接お会いしてご説明を申し上げて、平塚橋の新しい施設のほうに既に優先枠を設けてそちらに移行するという予定になってあります。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"優先枠を設けて近くにできるということですけれども、やはりシルバーセンターですから利用者の方は高齢者が多いということになります。近くとは言いますけれども、建て替えてシルバーセンターを存続していくべきだと私は思うのですけれども、改めて区のお考えをお聞きします。","respondent":"松山高齢者地域支援課長","answer":"平成２４年度の厚生委員会その他、それ以降、ご利用者には丁寧に説明をしています。今後、シルバーセンター跡には高齢者福祉施設等の整備が予定されているものですけれども、そういったことも踏まえまして検討していく予定です。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところですけれども、でも、４４年間あそこの地元でシルバーセンターがあったわけではないですか。そこのところはどう考えているのかということと、そうは言っても、そういう意見というふうなことについてもお聞かせほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"区としても重要だということで認識しておりますので、介護予防といった観点、総合事業の観点からもあわせて現在検討しています。建物が、それは丁寧にご説明をし、それはいたし方ないということでおわかりいただいている方もいらっしゃいます。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう中で、やっぱりこれだけ地域の方も要望が多いというふうなことであれば、建て替えて残していただきたいと思うのです。今後どうなるのかというふうなことについては全然聞いていないし、シルバーセンターの機能がそこに入るのかというところを説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"１点目、ご利用者の方なのですけれども、ご利用者の方の説明会では、やはり新しい施設への期待感というのは非常に大きい方がほとんどです。通うことによって、区としても非常に大事だと考えていますので、機能については今後整理していく必要があると考えております。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうふうな状況の中であの坂道を上って、どれくらいあるのですか、１.５キロぐらいあるのですか。２番目、２番目くらいに多い利用になっているというところでは、私はシルバーセンターという機能としてぜひ残していただきたいということで思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"確認","question":"跡地利用をこういう形にするというのは、厚生委員会なり議会で、ここで報告はあったのでしょうか。この４年間ぐらいの間でもいいのです、３年間の間でもいいのだけれども、そこら辺の感覚を説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"平成２４年のときには、やはり高齢者福祉施設等の活用を予定ということで、現在もそれは変わってはおりません。私のほうで総合事業と申し上げたのは１つの案でして、改めて、もちろんしかるべきところでしかるべき時期にご報告ということになろうかと思います。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問","question":"基本設計とか。ただ、福祉施設として残しますというのは、どこかを見れば必ず議事録かあるということだという理解でいいわけか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"そのため、今後、検討を具体的にしていこうです。平成２４年度以降、「高齢者福祉施設等」という文字と、あと書面でということで残されてはおります。","id":"exchange-034"},{"speaker":"若林委員","kind":"質問・要望","question":"特に高齢者系の福祉施設は１つ１つ、いわゆる地域包括ケア構築のための大事な大事な地域資源であるとする、まずそういう認識があります。そういうものを要するにどこにどう配置てしていくのかといところが、また前に進めていただきたいという思いで、意見だけ言って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"今年であればいつされて、利用者の方にどういうふうに周知がされて、利用者どれぐらいの方のうちどれぐらい説明会に参加されているのかということもお聞かせいただけたらと思いますとの意見を述べました。","respondent":"松山高齢者地域支援課長","answer":"説明会についてなのですが、今年は１月７日にしています。その利用者団体の方から、それぞれ所属している利用者の方にはお伝えいただくような形をとっております。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"すごい便利に長い間使われている利用者の方皆さんを集めて、やはり区としてはこういうふうにしていくということでの説明会が必要だと思うのです。ぜひ区として利用者の方に、利用者の方からの意見もきちんと聞くという場を私は持つべきだと思うのですけれども、いかがか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"平成２４年度の厚生委員会の中で統合が示され、利用者全員の方を集めて説明会は何度か、それ以降の年度にも行っております。具体的に安心してその後もご利用できるような形で日時などを、押さえる部屋などを調整して、具体的に集まっていただいたというものです。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"いよいよ今度５月に、今までずっと便利に使ってきたところが使えなくなるというところに当たるわけですから。これからやっていくというためにも、ぜひ説明会を開いて聞いていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"もちろん平成２４年度、平成２５年度には、説明会の中でお伝えしてきたところなのです。具体的に行いまして、もちろん説明しますし、また新たに３月末あるいは４月にもう一度説明会を予定しておりますので。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は区としてやるべきだと思いますし、そこできちんと使っている方の声を受けとめるというふうなことをぜひしてほしいと求めました。今使っている方の声を聞くという、そのためにもぜひ説明会を開いていただきたいということで要望をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-03","title":"第３１号議案 品川区立高齢者住宅条例一部を改正する条例","agenda":"第３１号議案 品川区立高齢者住宅条例一部を改正する条例","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"新たに契約を結んでということなのですけれども、ずっと１０戸だったのですね。不動産価値が下がったから３,０００円値下げをしたという単純な考え方でいいのかということと、これ、これを変えるものなのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"３,０００円の引き下げということでまず１点目ですけれども、その理由ですが、当該建物のやはり経年劣化と、あと、近傍家賃との比較について、この所有者にご提案を区のほうから差し上げまして、事前に協議をさせていただいてあります。","id":"exchange-040"},{"speaker":"いながわ委員","kind":"意見","question":"アツミマンションがどこのエリアにあるかということがピンと来ないのですけれども、これ、ほかの借上型でも、これからまたいつか契約のときになったら、そういった近傍家賃といいますか、値下げというのはしていくような流れにはなっていくのかどうかお願いしますとの意見を述べました。","respondent":"松山高齢者地域支援課長","answer":"今後、同じような値下げになっていくのかというところのご質問をいただきました。これまで別紙の新旧対照表の第２の上から３つ目は建設型なのですけれども、カガミハイツ、事前に協議をしていくという方向には変わらないです。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"今、近傍家賃と経年劣化によって引き下げられるということでしたけれども、ほかはいろいろ、６万７,０００円から８万５,０００円までさまざま値段が決まっているのですけれども、この決めるに当たっての基準などはあるのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"こちらの家賃の基準ですけれども、やはり近傍家賃との比較ということになっております。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"近傍家賃によるということで、そうすると、周りの家賃が上がれば、この高齢者住宅の家賃も上がるということでしょうか。契約期間というのは何年ぐらいになるのか説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"これまでほかの借上型の高齢者住宅の２０年という契約期間が終了いたしまして、１０年という契約期間にこれまでも変更してきております。それに準じまして、アツミマンションも１０年という契約期間に変更するものです。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"今、現在、アツミマンションが１０戸あるということですけれども、それは全て埋まっているということで、何人の方がいらっしゃるのかということを聞きたかったのですけれども、埋まっているのかということと、今回の引き下げによって使用料が下がる方はいるのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"１点目ですが、１０戸ございまして、全て満室になっております。それと２点目ですけれども、利用者の方の家賃が下がる方がいらっしゃるかといいますと、アツミマンションではおりません。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問","question":"済みません、特に意味がないのかもしれませんが、どういうことなのかということをお聞きしたいと思います。契約額が下がって、利用している方は減免等を受けているために、そこには反映されないという理解でいいか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"ですから、毎年の所得をこちらでお調べしまして、毎年その方の所得に応じて減額をしているです。今回は、区が借り上げする家賃の契約金額が下がるです。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、これまで下げてきたということですから、別に７万５,０００円のものが７万２,０００円になっていくというわけではないのですか。バンブーガーデンが７万５,０００円と、オーク中延も７万５,０００円なのですけれども、。","respondent":"松山高齢者地域支援課長","answer":"先ほどもご説明差し上げたように、それ以降の契約につきましても、これまでの経過に準じまして所有者と協議をするという方向で考えております。","id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"質問","question":"品川も例えば２万戸を超える空き家がある、そういうところをどういうふうに活用していくのだという話をしたら、入れるように大分なってきている。そういう行政として空き家活用した高齢者住宅の対策をやっぱり模索しながらやっていくという感覚でいるのか、そこら辺をお聞きしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"まずは住宅あっ旋制度につきまして、宅建協会のほうとお話し合いを再度しまして、もう一度パイプを強くしようという確認はしております。そちらのほうであっ旋を進めたいとは思っております。","id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"意見","question":"あっ旋の部分をやっぱりやっていくというその路線で、多分いいのだろうと思うので、ぜひそこら辺のところは高齢者の方々がお一人でも入れる住宅を見つかるような形を行政もやっぱり強く後押ししてほしいとお願いだけしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"１件相談がありまして、大家も含めて、この制度を全く知らなかったのですね。そういう点では、引き続いて高齢者の方々、また大家も含めて知らないという方がいないような形での周知をぜひお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"}]},{"id":"topic-04","title":"第３２号議案 品川区国民健康保険条例の一部を改正する条例","agenda":"第３２号議案 品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"これ、この後の請願のあれにも絡んでくるような感じもしないでもないのですが、とりあえずここで質問をさせてほしいと求めました。今後どういう見通しで、そういうことがいつかやってくるのかどうなのかということをまず１点お伺いしたいということと、それをまず説明を求めました。","respondent":"高森国保医療年金課長","answer":"全体として６０歳以上の方が４０％というふうな状況でございまして、一説によりますと、３２万円ぐらいの年間の医療費が総額としてかかる。１６万円だとか、１４万円だとかというふうな形で、なかなか保険料を下げるというふうな状況にはならないというふうなことです。","id":"exchange-050"},{"speaker":"いながわ委員","kind":"質問","question":"何点かお伺いしたいのは、納付した方の権利というのですか、そういうもので済む。それを３割負担で済むわけですから、それ以外にはどういったものが、サービス的な要素を考えたときに存在するのか。","respondent":"高森国保医療年金課長","answer":"３８０億円ぐらいが、３８０億円ぐらいのうちの１００億円ぐらいが今、収入があっても払わない人も中にはいらっしゃいます。しっかりした形でご相談に応じますし、その人の納付状況、生活状況に見合った形で可能な限り対応していくように努力しています。","id":"exchange-051"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そういうものは何かないのかと思うのですが、今後、そういうことはお考えですか。その人たちに対して何かあってもいいのではないかという思いがあるのですが、そういった制度はどうなのか尋ねました。","respondent":"高森国保医療年金課長","answer":"私も昔聞いた話では、１年間お医者さんにかからなかった方については、そういうものも時代にそぐわないということで廃止になっているかと思います。なかなか１年間お医者さんにかからなかった人について何か差し上げるというか、ご理解いただきたいと、済みません。","id":"exchange-052"},{"speaker":"いながわ委員","kind":"質問・要望","question":"課長からそれを１回伺ったので、その払っている人というのは、普通に何とも思わないで払っていると思うのです。これで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問","question":"少しお聞きしたいのですけれども、なぜ制度の安定化につながるのかということと、そもそも国保財政というのは不安定だったのかということもあわせてお聞きしたいと思います。","respondent":"高森国保医療年金課長","answer":"市町村によっては、全体で見ればかなりの負担になっている市町村もあるというのは事実だというふうに認識しております。ただ、これも全国のおそらく９０％以上がそういう方式になっていますので、全国レベルに合わせたというふうな状況です。","id":"exchange-054"},{"speaker":"のだて委員","kind":"意見","question":"品川では幸いにも国保財政が不安定ということはないということだと、今のご説明だとそう私は受け取りました。ちょっとまだ責任を負うというのは、都がお金を出すとか、そういったことがあるのかお聞かせ願いたいと思いますとの意見を述べました。","respondent":"高森国保医療年金課長","answer":"国でも国の検討会で検討しながら少しずつ実は情報が出てきていて、東京都と２３区の代表の区でいわゆる検討会を今進めているところなので、東京都。区の負担もそうですし、国の負担も、方向性としてはそういうふうに願っているところです。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"広域化によって品川区の保険料はどのように変わっていくのでしょうか。今、大体の感じで上がるのか下がるのかとか、それとも基準等算定方式が変わってくるのかというところを説明を求めました。","respondent":"高森国保医療年金課長","answer":"２３区の統一保険料方式を維持していくのかどうかということも、検討、この後の議論の中で進んでいくわけです。そういうふうな状況ですので、高くなるのか安くなるのかというのはお答えができない状況ですので、ご理解いただければと思います。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"次に移らせてほしいと求めましたが、５割と２割の軽減基準額が引き上げられるということで、５割と２割それぞれ教えてください。この部分に当たる総額は幾らになるか尋ねました。","respondent":"高森国保医療年金課長","answer":"２割軽減については４,７４３ということで、この数字でいくと２０８件、世帯としては２０８件増加するというような状況です。金額については、済みません、ちょっと資料がございませんので、申しわけございません。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり２６万５,０００円と基礎控除額で５割軽減されるわけですけれども、さらに増えていく方向を願っております。この賦課割合が決まっているわけですから、そこの辺がどういうことなのか、もう少し詳しく説明してほしいと求めました。","respondent":"高森国保医療年金課長","answer":"点線が平成２７年度の保険料率の線なのですけれども、それが限度額が上がることによって少し角度が緩やかになっているかと思います。これによって、ここの中間層の保険料について配慮した形というふうな内容です。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"この限度額を上げることによって緩やかな傾斜になるということなのですけれども、ちょっとそれがイメージできないのですが、この限度額が上がれば上のところが上がるのはわかるのですけれども、それによってこの傾斜が変わるというのはどういうことなのか、もう少し説明ほしいと求めました。","respondent":"高森国保医療年金課長","answer":"平成２７年度で試算したとき。５２万円お支払いいただいていた方なのですけれども、基礎額が５４万円になったことによって、こういうふうな内容です。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"一般質問でも我が党がお聞きしたいのですけれども、答弁では、実際に区に入ってきたお金は幾らなのでしょうか。それをどのように使用したのか説明を求めました。","respondent":"高森国保医療年金課長","answer":"これ、平成２７年度に入ってくる予定になっていますから、最終的に補正予算で個々の歳入に入ってくるのかという状況ですけれども。実は、財政支援の拡充策ということで、公費で私が持っている資料では１,６６４億円を財政支援するというふうに国が言っているのですけれども。","id":"exchange-060"},{"speaker":"のだて委員","kind":"提案","question":"１億８,０００万円を使うことができるということでしたけれども、広域連合の会議で、この引き下げのために使うということを提案したのか尋ねました。","respondent":"高森国保医療年金課長","answer":"２３区統一保険料方式を採用していますけれども、これは最終的には２３区の区長会で合意をして、間違えのないように確認します。","id":"exchange-061"},{"speaker":"のだて委員","kind":"提案","question":"広域連合ではなくて区長会のほうでやっているということで。今、品川区としてはこれを保険料引き下げに使いましょうと提案しているかということをお聞きしたので、そこの辺もお願いしますとの意見を述べました。","respondent":"高森国保医療年金課長","answer":"品川区では提案しておりませんし、２３区からも今そういう話にはなっておりません。現在のところはそういう話は出ておりません。","id":"exchange-062"},{"speaker":"のだて委員","kind":"提案","question":"品川区だけでなく、ほかのところも一切声が上がっていないということでしたけれども、なぜ提案しなかったのでしょうか。高過ぎる国保料が区民を苦しめているということは区が一番つかんでいると思うのですけれども、提案しなかった理由を伺いますとの意見を述べました。","respondent":"高森国保医療年金課長","answer":"実は公費の財政支援、均等割額の軽減に対する国の財政支援というのも別にありまして、この部分は国民健康保険の財政支援の拡充というふうな視点でお金が入ってきているというふうに理解しておりますので、そういう状況でしたので、申請をしております。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"財政支援のためということですけれども、国会でも政府はこのお金を保険料引き下げに使うことかできると言っているわけですから、その引き下げのためにぜひ使っていただきたいと思うのですけれども、改めてになってしまいますが、品川区の見解を伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"２３区の統一保険料方式を採用しておりますので、品川区だけがそれを採用することで下げるということは考えてございません。仮に２３区の中での合意が図れるということであれば、それは方向性としてはそういうこともあり得るというふうに考えています。","id":"exchange-064"},{"speaker":"のだて委員","kind":"提案","question":"合意がとれればということでしたけれども、ぜひ品川区からこの提案をしていってほしいと求めました。あるいは扶養家族が４人以上いる方、区としても減免策を検討していただきたいと思うのですけれども、区の見解を伺いますとの意見を述べました。","respondent":"高森国保医療年金課長","answer":"は刑務所等の拘禁されたことによる減免だとか、被扶養者等の軽減、非自発的失業者の軽減等を実施しています。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問","question":"差し押さえの件も質問いたしまして、８,２００万円、その内訳を教えてください。差し押さえが何件以上で幾らですとか、収納率が何％以上で幾らなど、具体的にお願いします。","respondent":"高森国保医療年金課長","answer":"平成２５年度の実績に基づいて平成２６年度に支給されている状況でございまして、細かく言ったほうがいいですか。Ｃ、それと差押件数が３００件以上で１,５００万円、それと口座振替の加入促進で４０％以上で２００万円で８,２００万円になると認識しております。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問","question":"これは成績別の話だということで、差し押さえも、今、７５０件ほどになってきていると思うのですけれども、毎年毎年上がってきておりますが、この収納率の向上の体制というのは、年々上がっている中で、新たに何か組んでおられるのか伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"収納率向上の取り組みというご質問ですが、先ほど来、別の委員からも質問がありましたように、払える人と払えない人がいるかと思います。払えるのに払わない人に対して滞納処分を推進するということで、今、公平性を担保するためにさまざまな形で作業を進めているところです。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"その中でやはり差し押さえを強硬に行っていくということはやめてほしいと求めました。１００分の６７を算入するということですけれども、この１００の総額と６７の額を、もう一度お願いいたします。","respondent":"高森国保医療年金課長","answer":"平成２６年度の高額療養費がおよそ２６億円ほどでしたので、１００分の６７ということで、おおよそ１７億円ほどが算入という形になります。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問","question":"この保険料への算入によって、やはりこれも保険料が高くなっていくと、高過ぎる国保料につながっていると思いますので、ぜひ誰でも医療を受けられるようにするために、この算入をやめるべきだと私は思うのですけれども、区の見解を伺います。","respondent":"高森国保医療年金課長","answer":"そこについては向こう３年間の中で柔軟に対応していくというふうな区長会決定がございましたので、平成２８年度については１７％というふうなことで、これはもうこのまま流れの中に１００分の１００を入れていくという流れに変わりはございません。","id":"exchange-069"},{"speaker":"のだて委員","kind":"質問","question":"やはりこういったところで誰もが気軽に医療を受けられるように、保険料の引き下げにこそそういったお金を充てていくべきだと思います。早め早めに治療して、健康を維持してもらうほうがよいと私は思うのですけれども、区の考えを伺います。","respondent":"高森国保医療年金課長","answer":"確かに区民の方で加入されている方は、さまざまな状況の方がいらっしゃいます。１万円は何とか頑張って払っていただけるということであれば、柔軟に、早め早めにおいでいただいてご相談いただければというふうに思います。","id":"exchange-070"},{"speaker":"のだて委員","kind":"質問・要望","question":"窓口だけではなくて、電話相談の方にもきめ細かくやってほしいと求めましたし、ぜひそこに充てていくようにしていってほしいと求めました。最後に、特別区の場合は５８対４２と割合が違うわけなのですけれども、これは２３区の中で品川区が低所得者が多いということなのか尋ねました。","respondent":"高森国保医療年金課長","answer":"これは品川区は２３区の中で平均より収入の多い方が多いということ。均等割が下がっているというのは、所得割のほうが増えているというのはそういうことです。","id":"exchange-071"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"７ページです、１人当たりの医療費水準が高く、そういう認識があるのかということをお聞きしたいと思います。","respondent":"高森国保医療年金課長","answer":"区のお金で、またはほかの保険者からの支援金ということでお金が入ってくるわけですけれども、さまざまな形で医療が高度化している。それをやはり最低限の負担については、これは制度としては、そういう流れで進めていかざるを得ないというところで私たちは考えているところです。","id":"exchange-072"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"７ページに書かれているように、都知事の要望書からもこういうふうなことが言われて、そういうことで所得に占める保険料負担が重くなっている。そしてまた非正規の方とかが入っている割合が多いわけではないか尋ねました。","respondent":"高森国保医療年金課長","answer":"こちらのほうは３６.４歳ということで、年齢差がありますから、療養費は大きくなるのはいたし方ないというのが現状です。それが構造的な部分だというふうに理解しているところです。","id":"exchange-073"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"全国のというのではなくて、品川の国保です。品川の国保で、ここに書かれている７ページの一番上の1)のところに書かれている、こういう認識があるのかというふうなことでお聞きしたのです。","respondent":"高森国保医療年金課長","answer":"1)の認識があるのかといえば、あります。先ほど、６０歳以上が４０％と申し上げましたし、医療費水準も２３区の中でも比較的高い状況です。","id":"exchange-074"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ここの1)番のところの認識があるかどうかというふうなところで、何度も何度も確認をさせていただきました。当然これは国が言っているように、なぜその立場に立てないのか、そこの考え方をお聞かせほしいと求めました。","respondent":"高森国保医療年金課長","answer":"平成２７年度から１,７００億円の行使ですけれども、当初は財政支援の拡充ということで、本来はこれはお金がおりてきたという理解でおりました。１２月にも申し上げましたように、１２月６日に国に最終的に申請をした状況でございまして、まだ今後の検討課題ということです。","id":"exchange-075"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"７割減免の方は置いておいたとしても、２割、５割の減免の方は所得割も出ているわけではないですか。この高い保険料になっているという、そういう認識に私はぜひとも区としてもなっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"この中に、平成２０年４月には、後期高齢者医療制度に伴う国保以外の保険料もそこに入ってきている形になっています。この限度額が１２万円ということですから、それほど大きな形で値上がりしている形ではありませんので、そこはよろしくお願いしたいと思います。","id":"exchange-076"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それは国保料ではないのですか。国保料としてそれを払っているわけですから、国保課長からそういう答弁があるというのは、ちょっと私は理解できないということです。","respondent":"高森国保医療年金課長","answer":"先ほど、委員のほうから、２００７年度からというふうなお話がございましたので、その間には後期高齢者の保険料が、いわゆる保険料の中にプラスにされているというふうに申し上げたです。","id":"exchange-077"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"改めてそこのところは、ぜひとも国保料がこれほど高い、国保の加入者にとってはそれだけ保険料が上がっているというのが実態ですから。伺いたいのが、１人当たりにすると幾らぐらいになるのか、そこのところを教えていただけないか尋ねました。","respondent":"高森国保医療年金課長","answer":"２６億円を９万２,０００で割りますと、２万８,２６０円ほどになります。","id":"exchange-078"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、今まで一般財源で出していた高額療養費の分を保険料でまかなうという形に変えたことで、２万８,２６０円、それが１人当たりで国保料を押し上げるという、そういう形になるという考え方か尋ねました。","respondent":"高森国保医療年金課長","answer":"もともと一般会計繰入金はずっと制度の中で不足している国保の歳入の欠陥を補うために繰り入れていく形になっていますので、数字の上で見ればそういうことになるかもしれません。","id":"exchange-079"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"区の繰り入れというのは、法定外と法定内というのがありますね。法定内と法定外がそれぞれ幾らになるのか教えていただきたいのと、今、医療分と後期高齢者の支援分と両方合計でいいのですので説明を求めました。","respondent":"高森国保医療年金課長","answer":"済みません、今、計算をもう１回きちんとします。平成２６年度の決算で見ますと、法定内が２０億１,９００万円、法定外が２１億６,４００万円ほどです。","id":"exchange-080"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この資料からすると、１６ページと１７ページに、歳入のところの区繰入金というのがありますね。そこの表の見方もあわせて法定外の今の２１億円という数字は、どこを見れば２１億円という数字がわかるのかを教えてほしいと求めました。","respondent":"高森国保医療年金課長","answer":"１７ページのほうは、これは平成２８年度の賦課計算の資料ですので、今、私が申し上げたのは、平成２６年度の決算数値で申し上げました。","id":"exchange-081"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この１６ページ、１７ページで、区の繰入金というのがあるではないですか。これが支援金分と、それから医療分とに両方ありますけれども、これとは関係ないのか尋ねました。","respondent":"高森国保医療年金課長","answer":"見方としてはちょっと難しいのですけれども、私が言ったのは、平成２８年度の予算上の法定内繰入と法定外繰入の予算額です。","id":"exchange-082"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうすると、区の繰入金は、法定外は今、高額療養費の分の１７億円が少なくなったという、そういうことの考え方になるのでしょうか。法定外です、法定外の繰入金は、高額療養費の分だけで減ったという考え方でいいのか尋ねました。","respondent":"高森国保医療年金課長","answer":"法定外の繰入金については、平成２５年度が２２億４,１００万円に対して、平成２６年度は２１億６,４００万円ですから、７,６００万円ほど減っている状況にはなっています。","id":"exchange-083"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"その法定外の繰入金というのは、あとほかにはどんなものが入っているのかについても教えてください。項目として。","respondent":"高森国保医療年金課長","answer":"法定外ということですけれども、法定内が基礎安定軽減分だとか、基礎安定支援分、職員給与費等の繰入金、出産育児一時金等繰入金ですから、それ以外のものが入って、いろいろなものが入っているのです。","id":"exchange-084"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１,７００億円が出、そして３,４００億円が出、安倍首相もそうやって国会の答弁で答えたのです。そういうふうなことで言っているわけですから、そして区長会でそういう方向を出していただきたいと強く要望いたしますけれども、いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"委員の要望ということで受けとめします。","id":"exchange-085"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひ要望を受けとめていただいて、発言にもつなげていってほしいと求めました。だけど、もうそれは絶対払ったら食べていけないというふうな状況になるわけですから、自分が病気をしていなければ払わないという状況が続くわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"医療にかかれなくて、手おくれになってしまうという、命を奪うというふうな状況も生まれているのがこの国保の問題なのです。そういうところからすると、本当に親身になった相談がまず第一に必要だというふうに思うのですけれども、その点ではいかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"納付がなかなか厳しい状況の中、窓口に相談をいただいている方については、生活状況を勘案しながら、無理な約束をしても、結局不履行ということで約束が果たせないのは目に見えている状況ですから、そういうふうなことのないように心がけて対応しています。","id":"exchange-087"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"課長のほうからもぜひ、そういう姿勢でというふうなことで、改めてお願いをしておきたいと思います。平成２６年度、平成２７年度、わかっている数字があったら教えてほしいと求めました。","respondent":"高森国保医療年金課長","answer":"平成２６年度の滞納処分による差し押さえ件数ですけれども、７４４件です。平成２７年度につきましては、１月３１日現在で６２１件です。","id":"exchange-088"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"７４４件で、幾らぐらいの差し押さえで、そして幾らぐらい換金できたのかという数字もわかったら説明を求めました。","respondent":"高森国保医療年金課長","answer":"平成２６年度が４,９４８万円で、平成２７年度が、現在、７,１４０万円ほどです。","id":"exchange-089"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この４,９００何万円と７,４００何万円というのは、差し押さえの額ということで、換金の額ではなくて差し押さえの額ということでよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"換金額。差し押さえの総額というのはわからないか尋ねました。","respondent":"高森国保医療年金課長","answer":"６,４００万円ほどです。いわゆる競売事件だとか、いろいろなものも含まれてきますので、そこの数字とちょっと数字が動いていますけれども。","id":"exchange-091"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"直接本人の状況を確認する、それが原則ですというやりとりというのは、国会の審議の中でもされているのです。そういうことは認識されているのか伺いたいと思います。","respondent":"高森国保医療年金課長","answer":"７割というと、均等割が５万円程度ですから、大体毎月１,４００円とか１,５００円ぐらいの保険料というふうな形になります。個々の案件でさまざまな対応が考えられますので、解除できませんというお話をする場合もありますし、その辺のところはご理解いただきたいと思います。","id":"exchange-092"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"私は滞納して、来てもらえば相談に応じますということだと、滞納を区役所に来るために差し押さえするのですかということになってしまうわけです。７６条で、１０万円プラス２万円というふうなことで、その金額以下の場合は差し押さえてはならないというのがあるではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"横山委員","kind":"質問","question":"６番の保健事業のところに、市町村の主な役割というところで、「被保険者の特性に応じたきめ細かい保健事業を実施」とあります。２３区のほうでもいろいろ協議などされていくかと思うのですけれども、今現在の状況ですとか、今後の見通しを教えていただけたらと思います。","respondent":"高森国保医療年金課長","answer":"今現在のところ、東京都と２３区の話し合いの中では、身近なところで地域に密着した形で進めていくという方向が打ち出されていると聞いてあります。隔年で実施されている方、全体の事業を進めていきたいと思いますので、よろしくお願いします。","id":"exchange-094"},{"speaker":"横山委員","kind":"質問・要望","question":"身近な品川区、市町村というところで、データヘルスを今後進めていく素案が今出ているという状況を確認させていただきました。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ご説明をいろいろいただいたのですけれども、まずお聞きしたいのは、根本を聞きたいのは、保険とは何ぞやということを教えてほしいと求めました。それはきちんと説明してくれないと、こういう議論は両方あるのだから、ぜひそこら辺の話をお聞きしたいと思います。","respondent":"高森国保医療年金課長","answer":"１つ目の質問で、３割の自己負担で７割は給付できるということで、それはそれはすばらしい制度だというふうに思います。この保険料をしっかりした形でおさめていただくという努力がまず行政に課せられた使命だと考えていますので、よろしくお願いしたいと思います。","id":"exchange-096"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"３,４００億円、いろいろな形で要望をしていって、それはまだわかる話です。国保の金額をその保険内でやってきれと言ったら、繰り入れを出すのがおかしいだろうと社保の人たちから言われたらどう説明するのですかということ。","respondent":"高森国保医療年金課長","answer":"しっかりとした形で、ただ保険料をとるだけではなく、都、国にもさまざまな要望を機会あるごとにしながら、国保財政をよりよいものにしていきたいと思いますので、よろしくお願いします。","id":"exchange-097"},{"speaker":"若林委員","kind":"意見","question":"被保険者加入所帯が６万３,０００所帯余、それに対して一番下に減額・免除と、それは平成２６年度でいうと４３件で金額が２８０万円。減額・免除をされていない方が７４４件なのか、この方たちの中で何割かが７４４に入っているのかという、何かざくっとわかればと思いますとの意見を述べました。","respondent":"高森国保医療年金課長","answer":"後者のほうのものは、差し押さえの中に若干軽減されている方も含まれている部分もあります。翌年、今まで全然おさめていらっしゃらない方が今年何らかの理由で軽減になる、そういうふうなケースの場合もあります。","id":"exchange-098"},{"speaker":"若林委員","kind":"質問・要望","question":"５割、２割ということで、一定当然されている。引き続き、特に所得の低い方の対応については、窓口も含めてしっかりとまたやっていただきたいというふうに要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１３億５,０００万円を保険料算定にするということで、２６億円丸々を保険料算定にしていくという、いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"済みません、ちょっと手元に資料がございませんので、もう一度そこは後で報告させてください。間違っていては困りますので。","id":"exchange-100"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"２分の１となると、品川区の分は１３億５,０００万円になるのを、その１３億５,０００万円を４分の１ずつ１年間３億３,７００万円くらいずつ保険料を算定していくというふうなことで書かれているのですけれどもとの意見を述べました。","respondent":"高森国保医療年金課長","answer":"ここに２分の１というふうに出ております。１３億円ということになります。","id":"exchange-101"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この保険料に、直接保険料の算定にかかわるのがこの部分なので、ここの部分は正確にしていただいたほうがいいかなと思って申し上げたものですけれども、そうしますと、本年度分の高額療養費分の値上げになる分で、１人当たりの保険料分とすると、幾らぐらいになるのかというところを説明を求めました。","respondent":"高森国保医療年金課長","answer":"今回提案しています平成２８年度の賦課総額は２,６２４億円ですので、２３区として見たときには、おおよそ３９億円という形になります。","id":"exchange-102"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それが品川区にすると幾らぐらいになって、１人当たりの保険料が幾らぐらいになるのかということを質問したのです。","respondent":"高森国保医療年金課長","answer":"４万５,６００円ということで、６００円均等割額が下がる、推計ではそういう数字。所得割、保険料については、据え置いた場合、おおよそですけれども、１,５００円保険料が下がる形になります。","id":"exchange-103"}]},{"id":"topic-05","title":"第４８号議案 東京都後期高齢者医療広域連合規約の変更","agenda":"第４８号議案 東京都後期高齢者医療広域連合規約の変更","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回この特例軽減が継続されるということになって、住民の方の負担が増えないということで喜ばしく思っておりますけれども、この継続をした理由をお聞きしたいと思います。","respondent":"高森国保医療年金課長","answer":"特別対策の継続につきましては、高齢者の負担を軽減するということで、来年度また消費税率が上がったり、そういうふうなことも予定されておりますので、そういうふうなことを総合的に勘案いたしまして、６２区市町村として特別対策については同意をしています。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"負担軽減ということで、ぜひこれからも続けていってほしいと求めました。平成２９年度分に、その前に余った剰余金８４億円を入れるということだと思うのですけれども、この剰余金が出た理由を説明を求めました。","respondent":"高森国保医療年金課長","answer":"広域連合のほうでは、剰余金が発生した主たる要因といたしましては、被保険者数が、また１人当たりの医療費の伸びが算定をいたしましたときよりも下回ったことに伴う医療給付費総額の減によるものだというふうな説明がございました。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問","question":"加入者数と給付が減ったということで剰余金が出たということでしたけれども、この剰余金というのは、今回、繰り入れられるわけですけれども、その前の部分で保険料引き下げに使うということは、制度上できないのか尋ねました。","respondent":"高森国保医療年金課長","answer":"平成２７年のこの２年間で８４億円ほどが見込まれているというふうな形で、剰余金が平成２６・２７年度、合わせて８４億円出たということです。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問","question":"先ほど、剰余金が８４億円出た理由を教えていただいたのですけれども、前年度は４０何億円ということですけれども、約倍になっているというところで、そこの先ほどの理由とかぶってしまうかもしれませんが、倍になった理由を説明を求めました。","respondent":"高森国保医療年金課長","answer":"いろいろな見込みなどを入れて勘案していますので、若干安全率も入れた保険料率の算定になっているのかというふうに思います。ちなみに、いわゆる平成２７年度末に安定化基金の残高がそのまま残ったということで、それを引き続き平成２８年も活用するということです。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"ゼロ円になっているのですけれども、そのときに来年度の保険料がさらに上がってしまうという懸念もあるのですけれども、そこの考え方を説明を求めました。","respondent":"高森国保医療年金課長","answer":"確かに基金が６４億円でしたか、平成３０・３１年度保険料で基金が全くなくなってしまうなどということが、広域連合のほうでしっかりした形で保険料率を算定しているというふうに理解しています。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"この基金がなくならないようにやっているということですので、引き続き、保険料が上がっていかないようにやっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"わかったら教えていただきたいのが１点と、どういう方向になっているのかという情報とかがあったら教えていただきたいのと、区からも要望を上げていただきたいと思うのですけれども。","respondent":"高森国保医療年金課長","answer":"確かに国は廃止するような方向だということなのですけれども、これから検討するというような、たしかそういう流れだと聞いております。国のほうにはやはりこの軽減対策は必要なものだからということで、機会あるごとに要望として上げるように話はさせていただいているところです。","id":"exchange-110"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今の軽減の世帯数なのですけれども、これ、均等割が１万８,６００世帯で、所得割というのが都独自の軽減措置ですよね。ここの対象がどれぐらいかというのも説明を求めました。","respondent":"高森国保医療年金課長","answer":"済みません、均等割の軽減の部分とかぶってしまうので、一応、数字としては４,０００ほどとというふうに理解しています。","id":"exchange-111"}]},{"id":"topic-06","title":"平成２８年請願第３号 国保・後期高齢者医療保険料の引き下げと特養ホーム・老健施設の増設を求める請願","agenda":"平成２８年請願第３号 国保・後期高齢者医療保険料の引き下げと特養ホーム・老健施設の増設を求める請願","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"これは２年間で２０２名で、１１カ所８８４名というのが、高齢者比率に対しての定員受け入れは妥当なのかどうなのかということをまずお伺いしたい。土地が出たときに、私は所管はいろいろご努力をされて施設を整備しているという思いでいますが、それが正しいのかどうかだけお伺いします。","respondent":"大串福祉計画課長","answer":"やはり今後の高齢者のニーズを踏まえながら、さまざまな形での施設整備は行っていきたいというふうに考えているところです。土地活用の考え方、それに向けた形で土地活用、用地情報等々を踏まえながら施設の整備も考えていきたいというふうに考えているところです。","id":"exchange-112"},{"speaker":"いながわ委員","kind":"意見","question":"整備率が２３区中２１位、前々からこの話は聞いているのですけれども、所管としてどう思っているのか。ここだけいつもこれで低いから整備しろよというのは、何か僕もイコールにはならないのではないかと思うのですけれども、これを見て区はどうお考えかとの意見を述べました。","respondent":"大串福祉計画課長","answer":"確かにそういった形で数値をやった場合、必ずしもこの整備率だけが実際の高齢者に対しての福祉のものさしだけではないというふうに考えております。","id":"exchange-113"},{"speaker":"のだて委員","kind":"質問","question":"先ほども国保と後期高齢者のほうでは、ぜひ私としても保険料を下げてほしいということを言ってきましたので、ぜひやってもらいたいと思います。そこで、特養ホームなのですけれども、今現在、２月の申し込みが行われていると思うのですけれども、現段階での申込者数をわかれば説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"各在宅介護支援センターのほうで受付をしておりますので、まだ区のほうに書類等が全て整っておりませんので、現段階ではわからない状況になっております。","id":"exchange-114"},{"speaker":"のだて委員","kind":"質問","question":"現段階ではわからないということでしたので、昨年の場合は、９月の段階で４５０名申し込んで待機待ちをしているということでした。この間の平塚橋、みやこ荘跡地整備、これらができれば待機者は出ないと考えているのか伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"現在、４５０名のお申込者がいらっしゃいますけれども、今はキャンセルしますよというようなことを言われたりというところもあります。ですから、施設ができたからといって、すぐにそれが待機者がなくなるとか、そういうような考えは持っておりません。","id":"exchange-115"},{"speaker":"のだて委員","kind":"質問","question":"すぐに待機者はなくならない、その考え方が難しいということでしたけれども、そうしましたら、報告があったかもしれないですが、前年度の申し込んだ方と、入れた方の人数を教えていただけますか。","respondent":"永尾高齢者福祉課長","answer":"平成２７年８月末の締め切りの分は、名簿が最終的には４月上旬ぐらいまで、多少動いていくところがあると認識しております。","id":"exchange-116"},{"speaker":"のだて委員","kind":"質問","question":"まだ８月末の分は確定した数字はわからないということでしたけれども、申込者全員が入れる見込みというのはあるのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"ですので、あとはどうしても皆さん、区内をご希望される方が多くなっております。できるだけ介護者が楽な状況、また、ご本人も安心して介護を受けられるような状況にしようというふうに努めているところです。","id":"exchange-117"},{"speaker":"のだて委員","kind":"質問・要望","question":"入所した方も住みなれたところで住み続けられるということになっていくと思いますので、ぜひ増設していってほしいと求めました。１８年度、２カ所目ができるということですけれども、十分だと考えているのか伺いたいと思います。","respondent":"大串福祉計画課長","answer":"入所の期間もおおむね３カ月といったところになっておりますし、在宅のほうに戻られて、なおかつリハビリを継続されるという形になってまいります。","id":"exchange-118"},{"speaker":"のだて委員","kind":"質問","question":"十分かどうかではないというお話でしたけれども、先ほどの説明では、老健施設、やはり身近にあることが重要だというような説明があったと思うのですけれども、その認識は正しいか伺いたいと思います。","respondent":"大串福祉計画課長","answer":"あくまでもこの老健施設、こういった１００人規模の老健施設については拠点というふうに捉えているところです。そういったものを中心とした施設、業者、こういったものになってまいるです。","id":"exchange-119"},{"speaker":"のだて委員","kind":"質問・要望","question":"その後、在宅へもつなげていきやすいと思いますので、ぜひ老健施設についても増設していってほしいと求めました。この請願の趣旨に私は賛同したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどの国保の続きをさせていただきたいと思うのですが……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１つは、そこのことについて、そういう方向でやるのかということが１点です。差押禁止金額が国税徴収法の７６条で決められいまして、１人世帯であれば、区としては差し押さえていくのかというところをお聞きしたいと思います。","respondent":"高森国保医療年金課長","answer":"扶養対象が１人いれば４万５,０００円、対面維持費ということで２割ぐらいが禁止財産部分に当たるのかと、そんな状況だと思います。我々は総合的に判断して、必要に応じて滞納処分を行っている状況です。","id":"exchange-122"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"合計した財産がその１２万円以下しかないという年金と、それから合計額合わせて１２万円以下しかその方の１カ月の収入はないという、そういうことでいくのかというところでお聞きしました。","respondent":"高森国保医療年金課長","answer":"１,４００円ぐらいだと思いますけれども、年間で１万５,０００円幾らかと思いますので、そういうふうな負担をしていただく。平成２５年度、平成２６年度については執行停止にかけていったり、それはもう本当にその方のケース・バイ・ケースで柔軟に対応しているです。","id":"exchange-123"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"あるにもかかわらず、私は差し押さえを行うというのは、ちょっと区としてはやり過ぎではないかと思うのです。それは差し押さえてはいけないということですから、禁止額ということが法律で決められているわけですから、いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"年金が振り込まれた口座をそのまま知っていながら押さえることについてはいかがなものかというふうな形での判例が出ていることも承知しております。","id":"exchange-124"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１０万円プラス２万円ということで１２万円というふうなことでなっているわけですから、そして徴収法、ここにのっとってぜひやっていただきたい。ぜひ見ていただきたいということで、このことに対しては、再考を求めたいと思います。","respondent":"大串福祉計画課長","answer":"先般の一般質問でもお答えをさせていただいたように、例えば小山台の関係ですが、東京都とも連携しながらと。あるいは、これまでの経緯、こういったものを含めて総合的に検討するといったところです。","id":"exchange-125"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう形で検討ということなのですけれども、ここの中では、特養ホームも含めての総合的な検討ということで確認させていただいてもいいでしょうか。そういう実態、介護離職の実態とか、つかまれている部分がありましたらお聞かせほしいと求めました。","respondent":"大串福祉計画課長、永尾高齢者福祉課長","answer":"あるいはオリンピック・パラリンピックを見据えて、あるいは防災上の関係、さまざまな視点が入ってまいります。そうした中で総合的に判断をさせていただいているといったところですので、私からは以上です。もうすぐ定年になるので、それをきっかけにというような方もいらっしゃるということで、さまざまかなというふうに感じているところです。","id":"exchange-126"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひそういう点からも特養ホームの増設をぜひしていただきたいということと、１カ月で４例ぐらい報道されたと、その点ではいかがでしょうか。だから、そういう点でぜひ特養ホームをこの先も増設するという、そういう方針を持っていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"大串福祉計画課長","answer":"あわせてソフトの支援、さまざまなソフトの支援、こういったものが総合的に必要になってくると考えています。ですので、特養だけが高齢者施設、またこれだけにスポットを当てて何事かというところではないというふうに考えているところです。","id":"exchange-127"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"特養だけやってくださいと言っているわけではないのです。もう予防介護は要りませんとか、これでいいのではないですかと言っているわけではなくて、そこのところについて答えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"特養も含めて、そういった高齢者サービス、高齢者の施設のあり方を含めて総合的に判断していきたいというふうに思っております。","id":"exchange-128"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"特養ホームが必要なのは１００ベッドで３,０００m2あればできるわけですから、購入なり、ぜひよろしくお願いしたいと思います。老健施設というのは、品川区民からするとどれぐらい必要だというふうな考えがあるのか、そこら辺についてもお聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"したがいまして、冒頭申し上げましたけれども、老健につきましては２カ所目という形で、今、整備をまさにやっている最中です。こちらを整備させていただいて、在宅復帰の２カ所目の拠点というふうに位置づけ、このように考えているところです。","id":"exchange-129"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ということは、老健施設はこの２カ所目の後に、とりあえずこれだけ必要だとかという考え方は持っていないということなのでしょうかというところです。ほかの施設で、品川区はここが進んでいるというものがあったらお聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"それから、小規模多機能のこちらにつきましては、８カ所ということで、２３区内でいけば５位ぐらいという形になっております。全体的なバランスをとりながら福祉の全体の政策をまとめていくということ、これこそが一番必要なことだというふうに考えているところです。","id":"exchange-130"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"在宅を支えるそういう施設ですから、そこが特養やグループホームや老健施設が足りないことを補充できるものではないというふうに思います。そういうところで、特養や老健の増設というところに大きく踏み出していただきたいと強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"どういうご両親、どういう形で面倒を見ていくのがいいかというのは、ぜひ聞いてほしいと求めました。そういうあっ旋できることも含めて、いろいろな形で私はここの部分はやっていっていただきたいと考えていますので、この請願については不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"若林委員","kind":"質問・要望","question":"方針を立てて、これから施設のさまざまな老朽化に合わせて等、しっかりとこれまでの方針を継承して取り組んでほしいと求めました。ただ一方、ここで特にこの２つを取り立てて増設をするということはそぐわないというふうに判断いたしますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すで、採択でお願いしたいと思います。入りたい人が入れるようにしていく、この実現が必要だと思いますので、採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-134"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先ほど、質問させていただいたように、計画的にしっかりと進めてほしいと求めました。ソフト、ハードの面でいろいろと支援するやり方もあると思いますので、そういうものも含めて不採択にさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"}]},{"id":"topic-07","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"最初は１万円ずつ払っていくということですけれども、その後、平成２９年１２月から５万円に上がっているのですけれども、これはしっかりと払っていける額なのか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"和解の条項ということで、弁護士と被告、原告ともに、生活費も考慮した上でこの金額が決められているところです。平成２９年１２月から５万円に上がるですが、平成２９年１２月からは満額支給になりますので、それに合わせて金額も変更したところです。","id":"exchange-136"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/540863?Template=document&Id=3438#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":90728,"voices":344}},{"id":"h28-20160222-8","meetingId":"h28-cm02","date":"2016年2月22日","dateIso":"2016-02-22","committee":"建設委員会","time":"午前１０時００分～午前１１時４４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"最初に、(1)の第３３号議案 品川区建築審査会条例の一部を改正する条例","agenda":"最初に、(1)の第３３号議案 品川区建築審査会条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２点伺いますけれども、今回２年に定めた、２年に定めたという理由の中身をお伺いしたいと思います。実際に何が変わっていくのかということは、やはり気になるところですので、そこら辺もお伺いします。","respondent":"中村都市計画課長","answer":"審査会は従来２年の任期で行っておりましたけれども、２年という任期についても、２年という定めにいたしました。以上です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"建築審査会という性格上、都市計画課から住宅課に変わると若干違和感がありますけれども、そこに関してはいかがでしょうか。今回変わるということで、住宅課になると何人体制になってしまうといったところがもしあれば、そこら辺もお伺いします。","respondent":"中村都市計画課長","answer":"窓口の変更、組織の担当の変更につきましては、組織の効率的な事務の執行に基づく考えによるものです。以上です。","id":"exchange-002"},{"speaker":"西本委員","kind":"確認","question":"１点確認ですが、２年の任期は、今までは品川区の条例の中に入ってなかったので、今回、明確にしましたという理解でよろしいか尋ねました。","respondent":"中村都市計画課長","answer":"４月１日の施行に伴い建築基準法の一部が削除されてしまいますけれども、現行では任期についての定めがございました。以上です。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"先ほどの答弁の中で、２年間ということは、今までもそういう形でやってきて問題がなかったから、２年間にしますという理解でよろしいでしょうか。もともと２年間でやっているのだったら、きちんと品川区の条例の中にも提示してもよかったのではないかと思ったのですが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"第１には、区として、どれだけの期間が適切かということを検討した結果、このようになりました。以上です。","id":"exchange-004"},{"speaker":"筒井委員","kind":"質問","question":"細かいところですけど、建築基準法新旧対照表の現行の第８３条の「～除く外」の後の下線部と、「～委員の」後の下線部はどういった意味ですか。任期などが入っているといいますか、ほかは何で線が入ってないのか尋ねました。","respondent":"中村都市計画課長","answer":"こちらは、この下線の部分は、改正後のところで、改正になる部分の下線を入れたのですけれども、説明が不十分で申しわけございませんでした。申しわけございません。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"率直に伺いたいのですけど、占用料も上がるということなのですけれども、これをリンクさせることの理由は何でしょうか。もっと簡単に言ってしまうと、上げなければ占用を認めている行政の側が損をする、負担が増すということなのかお伺いします。","respondent":"安井土木管理課長","answer":"それと全く違うような基準を持ってくるということは、説明として非常に難しいので、ここでは２３区ともそのようにしております。事業者としても混乱を招きますので、そこら辺は統一しているということで、うちのほうではその単価を使っているという形です。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回、占用料が上がるということですけれども、率直に、それがいわゆる一般区民の重い負担にならないかというところが心配なところではあります。どういう企業が多いのか、割合なども含めて教えていただきたいと思うのですが、いかがか尋ねました。","respondent":"安井土木管理課長","answer":"２m2までは全免にしているという対象になっていますので、比較的大型の有限会社以上といった会社は、企業として負担しているところだと思います。以上です。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"法定外公共物について、実際に払っている方が、どういうものが請求されているかだけは教えていただきたい。なるべく占用料を低くして、間接的に設置支援をすべきだという考えもあるかと思うのですけれども、何か優遇措置などがあるのでしょうかお伺いします。","respondent":"安井土木管理課長","answer":"約２分の１減免を公園についてかけて、インセンティブを与えて、単価としては５１０円という形を設定しています。以上です。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"品川区としては減免をかけているということですが、条文には書いてないと思いますけれども、これは要綱で定めるかと思います。なぜここに附則みたいな形で定めないのか、要綱で定める理由だけ、再度お願いします。","respondent":"安井土木管理課長","answer":"今回については、従来の判例など踏襲いたしまして、要綱のほうで定めるという形です。以上です。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それの進み具合が、今どうなっているのかということで、１点教えてください。これは今の区の考え方は、たしか公設民営でいくという考え方でいった場合には、直接及んでこないということでいいのか尋ねました。","respondent":"安井土木管理課長","answer":"家の屋根を切り落とすというわけにもまいりませんので、やがて家の建替えというときには、売却。３点目の保育所の考え方ですけれども、１０年の占用期間が認められておりますので、民間のほうの誘導もあろうというところです。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"一つわからなかったので、この中でアーチ状の看板が出ていたものは、これは道路占用ですか。商店街の看板のようなアーチ状ということで、イメージはよろしいか尋ねました。","respondent":"安井土木管理課長","answer":"そういった場合はアーチ状のものが附帯される場合がありますので、そういったものが、アーケードではある。アーケードの場合は上方４ｍ５０cm以上の通行に障害のないような形でやっている場合がありますので、そういったものもつくるという形になります。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"今の質問の中で、運営はという関係が入ってしまうかわからないのですけれども、占用料はどこまで入るのかと思いました。占用料が発生するものと発生しないものがあると、その上で民間の活力をこれからいろいろ使われると思いますけど、そこの判断はどこにあるのか。","respondent":"安井土木管理課長","answer":"区がつくっているものですので、借りている主体自体は、区という形になります。だれが、実際上、そこの建物を建てているかという実態の問題で判断しているということなので、そういう考え方になります。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"この土地をどうぞと、取るのですか、取らないのですか。占用料はかからないのですか、かかるのか尋ねました。","respondent":"安井土木管理課長","answer":"もともとは限定が非常に厳しい、道路は非常に想定されてないですので、あくまでもそういう形で限定的に求められているという形になります。ですから、区域会議のほうへ申請して、オーケーが出ない限りは、たとえ区だとしても、建てられないということになります。","id":"exchange-013"},{"speaker":"西本委員","kind":"確認","question":"最後、もう一度確認させてください。でも、土地を貸すから、民間で建物もつくる運営もやるという場合には、占用料はかかるという確認です。","respondent":"安井土木管理課長","answer":"当然かかります。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の風営法改正に伴う条例改正ということですが、大もとの風営法改正の理由と背景について、もう少しご説明をいただきたいのですけれども、。","respondent":"鈴木（和）建築課長","answer":"すなわちダンスが少年の健全な育成に障害を及ぼす行為という認識から、ダンスをさせること自体が、規制の対象と今までなってきたものです。先ほどご説明しましたように、今回、国のほうで風営法を変えたです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"どういう施設で、該当施設は赤いところですが、地域には実際どれぐらいあるのでしょうかお伺いします。資料３のまだ規制の対象のままになってしまったところですが、これはどういう施設で、地域には実際どれくらいあるのかについても伺えればと思います。","respondent":"鈴木（和）建築課長","answer":"こちらにつきましても、現在、特別工業地区条例区域内は１軒もございません。以上です。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問","question":"ダンスホールは、飲食の提供がないということでしたけれども、イメージ的には、ただひたすらダンスをやるということになるのですか。文化センター的な場所になるのか尋ねました。","respondent":"鈴木（和）建築課長","answer":"これはまたダンスホールとは位置づけが違いまして、建築基準法的にも、通常は教室という位置づけになっております。今回、改正をされましたけれども、昔のダンスホール、営業、バンドが伴うようなダンスホールは非常に少ないというイメージです。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。今回の条例改正によって、特定工業地区指定エリアでも、ダンスホールを開設することができるということでよろしいか尋ねました。","respondent":"鈴木（和）建築課長","answer":"これからダンス文化が非常に醸成されて、昔のようなダンスホールの需要が出てくれば、特別工業地区内で、そういった営業ができるという改正です。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"資料１の改正後の新２号営業の（現５号営業）の現５号は、どういうものなのでしょうか。もう少しこれを利用して、厳密にそういうものを規制することもいいのではないかと思うのですが、その辺いかがか尋ねました。","respondent":"鈴木（和）建築課長","answer":"平成２５年以降、そういったところを、本来であれば東京都が５年ごとに土地利用現況調査を行っています。変えていく必要があるかどうかということは判断していくわけですけれども、今現在のところ、規制をさらにエリアを拡大するという予定はないです。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"成果がかなりあったのではないかと思うのですが、そういうことであるならば、品川区の中で変えることができるのかどうか。その自由度はいかがか尋ねました。","respondent":"鈴木（和）建築課長","answer":"当然、品川区の条例ですので、地域の声あるいは土地利用の現状、実態を見ながら変えることはできる、区の判断でできるという内容です。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"これは要望ですが、品川区全体を見たときに、やはりいろいろ問題が起きていることがあると思います。ぜひ今後、研究としてやっていただきたいと考えていますが、これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"安藤委員","kind":"意見","question":"２０１２年に１６万人分の請願署名が国会に提出されるなど、日本のクラブ文化を守れということでクラブを実現させたものです。しかし、今回、一歩前進であることは間違いないので、賛成ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"内容というのでしょうか、どういった基準で、こういう額になっているのかということをお伺いしたいと思います。そういった基準とか、分かれ目といいますか、どこら辺にあるのかをお伺いします。","respondent":"稲田道路課長","answer":"相手と示談交渉をしまして、５割対５割というところで、今回はなった模様です。そういうものも含めながら、区の施設として、これが管理瑕疵に当たるかどうかということは、その時点、時点で判断をしてやっているです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"意見","question":"ケース・バイ・ケースといえばケース・バイ・ケースですが、どういった場合に歩行者の責任、もちろん注意しようというところがある中で、今回区の責任があるとなったわけですけれども、そこら辺の基準、考え方、どこでどうなるのかということをもう少し知りたいとの意見を述べました。","respondent":"稲田道路課長","answer":"区が安全に管理しなければいけないというところにおいては、これは瑕疵があったと考えて、北品川の場合はこういう感じでやったということです。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"今回、損害保険会社も関与したということですけど、その過失割合、５対５ということで、北品川の場合ですと、女性の方も不注意を認められたということでよろしいか尋ねました。","respondent":"稲田道路課長","answer":"そうです。５割程度の不注意、瑕疵というところになってあります。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今度、目視なり、点検していただいて、かなりの数を直したのか、どうか。そのまま直されていない状況もあるので、直すということは、どういうふうに判断していって修理するのかということも１点お伺いします。","respondent":"稲田道路課長","answer":"今まではそれで発見した数ですが、平成２６年度におきましては、月に数カ所から１０カ所ぐらいの頻度で、ちょこちょこ直してきているという状況です。今回、月に２回ほど点検数を増して、今は実施しています。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"点検していただいて、なるべく早くそういう事故が起きないような形にしてもらいたい。あそこはひどいという話は出てきて、道路課に来て、そういうものを直すというような連携はできているものなのか尋ねました。","respondent":"稲田道路課長","answer":"もちろん、職員もそうですけれども、職員も現場に出たときなど、あそこが悪いということは上がってきます。維持担当という部署がありますので、そちらが受けて、直していくという状況でやっております。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"意見","question":"職員の方は、かなり表へ出て、道路課だけではなくて、いろいろなところへ出ているから、その辺も徹底しておいたほうがいいかと、何かのときには、事故を避けるため、万が一のことを避けておかなければと思いますので、その辺の徹底もまたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問","question":"そういうパターンとして、どういうものが多いのかがわかれば、まずその辺を説明を求めました。","respondent":"稲田道路課長","answer":"区民の陳情、苦情という形で、平成２６年度の集計は、道路がこういうふうに壊れていたり、排水が悪かったり、樹木の枝が落ちていたりというものを合わせますと、全体で４２２件の陳情があったです。","id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"そういった声をもう少し反映していく仕組みを工夫していけば、逆にこうしたことは減っていくというところはあると思います。今回特に第３号のほうは、何かによってなったのか、その辺は明らかになっているのか尋ねました。","respondent":"稲田道路課長","answer":"そのふたとふたとの間でありまして、何か力が上に乗ることで、ふたとふたが競り合って、ブロックが割れたのではないかと区のほうでは考えております。","id":"exchange-030"},{"speaker":"つる委員","kind":"確認","question":"何か被害を受けた方に対する賠償責任は、保険の関係上、区が管理責任者として持っていると思います。今回例えば第３号のほうは、それだけお金がかかることですから、このあたりを確認で説明を求めました。","respondent":"稲田道路課長","answer":"保険会社との関係ですけれども、私どもも現場を調査して、先ほど私が答弁したような状況についても、保険会社に話をしている。「これは、これぐらいの歩合です」と言いながら、意見のやりとりしながら決めていくものです。","id":"exchange-031"},{"speaker":"つる委員","kind":"確認","question":"管理者としての対応ですが、間接的には保険料を区として支払っているわけですから、最終的に本来それを償わなければいけない方です。当然、金額にもよるのですけど、やられているのか、そこの部分の確認をしたいのです。","respondent":"稲田道路課長、松代防災まちづくり部長","answer":"あれなのですけれども、構造上のタイルの割れ方や破損の仕方等、担当のほうでは分析しています。例えば、職員が、壊したということまではないというところまでは判断しながらやってあります。担当課長が答えた範囲に加えて、当然これは事故対応ということで、区のほうへ連絡が来るようになっております。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"結局、５割ということになると、総額で言うと１５万円ぐらいになりますか。眼鏡代という形があると思いますけど、一例も含めて、どういう中身になっているのかということを教えてもらえますか。","respondent":"稲田道路課長","answer":"賠償額の内訳ですが、第４号の場合は、傷害慰謝料が１３万４,０００円、治療費が３,８４０円、文書料が５,４００円です。合計１４万３,２４０円の半分で、７万１,６２０円です。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"ですから、そこを今後どういうふうにするのか。今、難しいかもしれませんけど、お考えがいろいろあればお伺いします。","respondent":"稲田道路課長","answer":"今回の現場に関してはありませんということで、きちんとご説明をして、ご納得いただいて、済んできているものです。全て払うというスタンスではありませんで、きちんと原因を確かめながら、瑕疵の割合等も考えながらやっていきたいと考えています。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、今回２件ですけれども、こういう部分はこうでというきちんとした説明を自信を持って言っていただけることも必要であると感じました。いろいろな違う意味でも、何かの時の備えを進めていくことも必要であると思いましたので、ご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"木村副委員長","kind":"質問","question":"今回は区道だったわけですけれども、区道、都道、国道とあった場合に、国道であれば、区が対応するということはできない。電話は区にかかってくると思いますけれども、その場合には、区側としては、どのように対処するのか尋ねました。","respondent":"中村都市計画課長、稲田道路課長","answer":"道路によってそれぞれ管轄がことなりますので、情報を得た時点で速やかにその管轄の部署のほうにお伝えをして、適切な対応をとっていただく。区内を通行している方のけがということで、迅速に対応していただけるようにお願いしています。 国道、都道でありましても、現場の担当者は一応その現場を確認して、国道、都道のほうには伝える。先に伝えるのですけれども、現場の状況等も確認しているという状況です。","id":"exchange-036"},{"speaker":"木村副委員長","kind":"質問・要望","question":"ちょっとした段差につまずくようになってくるわけですから、区道であれば、ものすごく過敏にならなければいけない部分はあると思います。これは要望ですけれども、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"要望だけです。パトロールを強化していただいて、最後の表層工事のことについても、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区のほうからは、区内で１０カ所の１０メートル以下の高さ制限を設けている箇所があるなどの紹介があった上で、３つほどお伺いしたい。３点目は、あわせて導入の検討を開始すべきと思いますが、区としては、課題がどこにあると考えているのかをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862367?Template=document&Id=4162#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":30504,"voices":127}}]);
